export function lbBandFor(budget) {
  for (const b of LB_BANDS) if (budget <= b.max) return b;
  return LB_BANDS[LB_BANDS.length - 1];
}

export function lbUseLabel(use) {
  for (const u of LB_USES) if (u.key === use) return u.label;
  return null;
}

export function lbSpecFor(bandKey, use) {
  return LB_SPECS[bandKey + ":" + use] || null;
}

export function lbVerdictLabel(verdict) {
  if (verdict === "below-floor") return "Below the floor";
  if (verdict === "tight") return "Tight — it works, with compromises";
  if (verdict === "good") return "Good fit";
  if (verdict === "overkill") return "More than this use needs";
  return "";
}

export function lbCompute(budget, use) {
  const b = Number(budget);
  if (!Number.isFinite(b)) return null;
  if (b !== Math.trunc(b) || b < LB_MIN_BUDGET || b > LB_MAX_BUDGET) return null;
  if (typeof use !== "string") return null;
  const useLabel = lbUseLabel(use);
  if (useLabel === null) return null;
  const band = lbBandFor(b);
  const spec = lbSpecFor(band.key, use);
  if (!spec) return null;
  // Gaming GPU tiers have their own thresholds inside the bands:
  // the RTX 2050 tier starts near Rs 59,000 and the RTX 4050 at
  // about Rs 75,000 (see sources.md). Inside the b50/b65 bands the
  // GPU follows the exact budget, not just the band — at Rs 50,000
  // a gamer is below the RTX 2050 tier and the checker says so.
  let gpu = spec.gpu;
  let gpuShort = spec.gpuShort;
  let verdict = spec.verdict;
  let note = spec.note;
  let stretchTo = spec.stretchTo;
  let stretchNote = spec.stretchNote;
  if (use === "gaming" && band.key === "b50" && b < 59000) {
    gpu = "Integrated only — the RTX 2050 tier starts near ₹59,000";
    gpuShort = "Integrated";
    verdict = "tight";
    note = "At this budget you are below the RTX 2050 tier, which starts near ₹59,000 (ASUS Vivobook 16X) — light and older games only on integrated graphics.";
    stretchTo = 60000;
    stretchNote = "₹60,000 buys an RTX 2050 with 16GB — the first real gaming laptop.";
  }
  if (use === "gaming" && band.key === "b65" && b < 75000) {
    gpu = "RTX 2050 (RTX 4050 from ~₹75,000)";
    gpuShort = "RTX 2050";
    verdict = "good";
    note = "The RTX 2050 tier: an RTX 2050 plays modern games at 1080p on medium settings. The RTX 4050 starts at about ₹75,000.";
    stretchTo = 75000;
    stretchNote = "₹75,000 buys an RTX 4050 — the step up for AAA games at high settings.";
  }
  const idx = LB_BANDS.indexOf(band);
  const up = idx < LB_BANDS.length - 1 ? LB_BANDS[idx + 1] : null;
  const down = idx > 0 ? LB_BANDS[idx - 1] : null;
  return {
    budget: b,
    use,
    useLabel,
    bandKey: band.key,
    bandLabel: band.label,
    bandSpec: band.spec,
    bandExample: band.example,
    bandBestFor: band.bestFor,
    cpu: spec.cpu,
    ram: spec.ram,
    ramShort: spec.ramShort,
    storage: spec.storage,
    display: spec.display,
    gpu,
    gpuShort,
    verdict,
    verdictLabel: lbVerdictLabel(verdict),
    note,
    stretchTo,
    stretchNote,
    avoid: spec.avoid,
    bandUp: up ? up.key : null,
    bandUpLabel: up ? up.label : null,
    bandDown: down ? down.key : null,
    bandDownLabel: down ? down.label : null
  };
}

