// Retirement calculator.
// Current age + retirement age + life expectancy + monthly expenses
// today + savings so far + inflation + returns before/after
// retirement + yearly SIP step-up -> the corpus needed, the
// shortfall and the monthly SIP that closes it.
// Conventions (stated on the page, matching the published
// anchors in sources.md):
// - Today's expenses are inflated to the retirement age:
//   E = monthly expenses x 12 x (1 + inflation)^years to save.
// - The corpus is the present value, on the day you retire, of a
//   yearly expense that keeps rising with inflation until your
//   life expectancy, discounted at your post-retirement return.
//   Expenses are drawn at the START of each year, so the corpus
//   is E x (1 - q^n) / (1 - q) with q = (1 + inflation) /
//   (1 + post-retirement return) and n = years in retirement.
//   (A calculator that pays expenses at the END of each year
//   gives a corpus about 1.9% smaller for the same inputs -
//   see the RupeeCase note in sources.md.)
// - Savings grow at the pre-retirement return, compounded
//   annually: savings x (1 + pre-return)^years to save.
// - The monthly SIP is the shortfall divided by what Rs 1 a
//   month grows to at the pre-retirement return, paid at the
//   START of each month at the nominal monthly rate
//   (pre-return / 12) - the same convention as this site's SIP
//   calculator. The step-up SIP is the first month's SIP when
//   the SIP rises by the step-up percentage every year.
// - "Invest once today" is the shortfall discounted at the
//   pre-retirement return.
// - The 25x check is 25 x the first year's expenses in
//   retirement (the 4% rule); the 33x check is 33 x (the 3%
//   rule many Indian planners prefer).
// All money outputs round to the nearest rupee. The year
// tables telescope by construction: the accumulation table
// ends at the corpus (or at the grown savings when those
// already cover it) and the depletion table ends at zero.
export const RT_MIN_AGE = 18;
export const RT_MAX_AGE = 70;
export const RT_MIN_RETIRE = 30;
export const RT_MAX_RETIRE = 75;
export const RT_MIN_LIFE = 60;
export const RT_MAX_LIFE = 100;
export const RT_MIN_EXPENSES = 1000;
export const RT_MAX_EXPENSES = 1000000;
export const RT_MAX_SAVINGS = 100000000;
export const RT_MIN_INFLATION = 0;
export const RT_MAX_INFLATION = 12;
export const RT_MIN_PRE = 0;
export const RT_MAX_PRE = 20;
export const RT_MIN_POST = 0;
export const RT_MAX_POST = 15;
export const RT_MIN_STEPUP = 0;
export const RT_MAX_STEPUP = 25;

export function rtCompute(age, retireAge, lifeAge, expenses, savings, inflationPct, prePct, postPct, stepUpPct) {
  if (![age, retireAge, lifeAge, expenses, savings, inflationPct, prePct, postPct, stepUpPct].every(v => typeof v === "number" && Number.isFinite(v))) return null;
  const a = Number(age);
  const r = Number(retireAge);
  const l = Number(lifeAge);
  const exp = Number(expenses);
  const sav = Number(savings);
  const g = Number(inflationPct) / 100;
  const rp = Number(prePct) / 100;
  const rq = Number(postPct) / 100;
  const s = Number(stepUpPct) / 100;
  if (![a, r, l, exp, sav, g, rp, rq, s].every(Number.isFinite)) return null;
  if (a !== Math.trunc(a) || r !== Math.trunc(r) || l !== Math.trunc(l)) return null;
  if (a < RT_MIN_AGE || a > RT_MAX_AGE) return null;
  if (r < RT_MIN_RETIRE || r > RT_MAX_RETIRE) return null;
  if (l < RT_MIN_LIFE || l > RT_MAX_LIFE) return null;
  if (r <= a || l <= r) return null;
  if (exp < RT_MIN_EXPENSES || exp > RT_MAX_EXPENSES) return null;
  if (sav < 0 || sav > RT_MAX_SAVINGS) return null;
  if (g < RT_MIN_INFLATION / 100 || g > RT_MAX_INFLATION / 100) return null;
  if (rp < RT_MIN_PRE / 100 || rp > RT_MAX_PRE / 100) return null;
  if (rq < RT_MIN_POST / 100 || rq > RT_MAX_POST / 100) return null;
  if (s < RT_MIN_STEPUP / 100 || s > RT_MAX_STEPUP / 100) return null;
  const yearsToSave = r - a;
  const yearsInRetirement = l - r;
  const annualAtRetirement = exp * 12 * Math.pow(1 + g, yearsToSave);
  const monthlyAtRetirement = annualAtRetirement / 12;
  const q = (1 + g) / (1 + rq);
  const corpus = Math.abs(q - 1) < 1e-12
    ? annualAtRetirement * yearsInRetirement
    : annualAtRetirement * (1 - Math.pow(q, yearsInRetirement)) / (1 - q);
  const corpusToday = corpus / Math.pow(1 + g, yearsToSave);
  const savingsGrown = sav * Math.pow(1 + rp, yearsToSave);
  const shortfall = Math.max(0, corpus - savingsGrown);
  const investOnce = shortfall / Math.pow(1 + rp, yearsToSave);
  const i = rp / 12;
  const months = yearsToSave * 12;
  const annuity = i === 0 ? months : (Math.pow(1 + i, months) - 1) / i * (1 + i);
  const sip = shortfall / annuity;
  const stepAnnuity = i === 0 ? 12 : (Math.pow(1 + i, 12) - 1) / i * (1 + i);
  let stepSum = 0;
  for (let k = 0; k < yearsToSave; k++) {
    stepSum += Math.pow(1 + s, k) * Math.pow(1 + i, 12 * (yearsToSave - 1 - k));
  }
  const sipStepUp = shortfall / (stepAnnuity * stepSum);
  const realReturn = (1 + rq) / (1 + g) - 1;
  const firstYearWithdrawalPct = annualAtRetirement / corpus * 100;
  const check25 = annualAtRetirement * 25;
  const check33 = annualAtRetirement * 33;
  const accumulationRows = [];
  let sipFv = 0;
  let prevClosing = sav;
  for (let k = 0; k < yearsToSave; k++) {
    const sipMonth = sipStepUp * Math.pow(1 + s, k);
    const paid = 12 * sipMonth;
    const thisYearFv = sipMonth * stepAnnuity;
    sipFv = sipFv * Math.pow(1 + i, 12) + thisYearFv;
    const closing = sav * Math.pow(1 + rp, k + 1) + sipFv;
    accumulationRows.push({
      year: k + 1,
      age: a + k + 1,
      paid: Math.round(paid),
      growth: Math.round(closing - prevClosing - paid),
      closing: Math.round(closing)
    });
    prevClosing = closing;
  }
  const depletionRows = [];
  let balance = corpus;
  for (let j = 0; j < yearsInRetirement; j++) {
    const withdrawal = annualAtRetirement * Math.pow(1 + g, j);
    const opening = balance;
    balance = (balance - withdrawal) * (1 + rq);
    depletionRows.push({
      year: j + 1,
      age: r + j + 1,
      withdrawal: Math.round(withdrawal),
      growth: Math.round(balance - opening + withdrawal),
      closing: Math.round(balance)
    });
  }
  return {
    age: a,
    retireAge: r,
    lifeAge: l,
    expenses: exp,
    savings: sav,
    inflationPct: Number(inflationPct),
    prePct: Number(prePct),
    postPct: Number(postPct),
    stepUpPct: Number(stepUpPct),
    yearsToSave,
    yearsInRetirement,
    monthlyAtRetirement: Math.round(monthlyAtRetirement),
    annualAtRetirement: Math.round(annualAtRetirement),
    corpus: Math.round(corpus),
    corpusToday: Math.round(corpusToday),
    savingsGrown: Math.round(savingsGrown),
    shortfall: Math.round(shortfall),
    investOnce: Math.round(investOnce),
    sip: Math.round(sip),
    sipStepUp: Math.round(sipStepUp),
    realReturn: Math.round(realReturn * 10000) / 10000,
    firstYearWithdrawalPct: Math.round(firstYearWithdrawalPct * 100) / 100,
    check25: Math.round(check25),
    check33: Math.round(check33),
    accumulationRows,
    depletionRows
  };
}

