// Home loan eligibility calculator.
// Net monthly income + existing EMIs + down payment + interest rate +
// tenure + FOIR limit + optional current age -> the maximum home price,
// the maximum loan, the EMI, the loan-to-value ratio and which limit
// binds (income or property value).
// Conventions (stated on the page, matching the published anchors in
// sources.md):
// - Maximum EMI = net monthly income x FOIR - existing EMIs, floored at 0.
// - Maximum loan from income = maximum EMI x (1 - (1 + r)^-n) / r, where
//   r is the monthly rate (annual rate / 12 / 100) and n is the number of
//   months in the effective tenure - the inverse of the standard EMI
//   formula. At 8.5% over 20 years every Rs 1,000 of EMI repays about
//   Rs 1,15,231 of loan.
// - The effective tenure is the tenure entered, capped at 65 - age when
//   an age is given (lenders want the loan repaid by retirement at 65);
//   without an age the tenure entered is used as it stands.
// - The RBI loan-to-value cap is the largest loan L satisfying
//   L <= ltv(L) x (L + down payment), with ltv 90% for loans up to
//   Rs 30 lakh, 80% for Rs 30-75 lakh and 75% above Rs 75 lakh (RBI
//   Master Circular on Housing Finance, 1 April 2025). That works out
//   to nine times the down payment capped at Rs 30 lakh, four times
//   capped at Rs 75 lakh, or three times the down payment - whichever
//   band the capped loan falls in. The final loan is the lower of the
//   income loan and the LTV-capped loan.
// - The comfortable price repeats the calculation at 40% FOIR and the
//   stretch price at 55% FOIR. The closed-EMIs and 1-point-lower-rate
//   uplifts are computed from the UNROUNDED prices, so they can differ
//   by Re 1 from subtracting the displayed rounded prices.
// - Stamp duty + registration are shown as 6%-8% of the maximum price,
//   rounded to the nearest Rs 1,000 (5-7% stamp duty + about 1%
//   registration, set by each state).
// All money outputs round to the nearest rupee; the LTV ratio to
// 1 decimal. A zero loan carries a zeroReason ("emis", "age" or
// "down") so the page can say why.
export const HLE_MIN_INCOME = 10000;
export const HLE_MAX_INCOME = 1000000;
export const HLE_MIN_EMIS = 0;
export const HLE_MAX_EMIS = 500000;
export const HLE_MIN_DOWN = 0;
export const HLE_MAX_DOWN = 20000000;
export const HLE_MIN_RATE = 0;
export const HLE_MAX_RATE = 15;
export const HLE_MIN_YEARS = 1;
export const HLE_MAX_YEARS = 30;
export const HLE_MIN_AGE = 18;
export const HLE_MAX_AGE = 70;
export const HLE_RETIREMENT_AGE = 65;

export function hleLtvBand(loan) {
  if (loan <= 3000000) return 90;
  if (loan <= 7500000) return 80;
  return 75;
}

export function hleLtvCapLoan(down) {
  const cands = [Math.min(3000000, 9 * down)];
  if (4 * down > 3000000) cands.push(Math.min(7500000, 4 * down));
  if (3 * down > 7500000) cands.push(3 * down);
  return Math.max(...cands);
}

export function hleCore(income, emis, down, ratePct, years, foirPct, age) {
  const maxEmi = Math.max(0, income * foirPct / 100 - emis);
  const effYears = age === null || age === undefined ? years : Math.max(0, Math.min(years, HLE_RETIREMENT_AGE - age));
  const months = effYears * 12;
  const r = ratePct / 1200;
  const factor = months === 0 ? 0 : r === 0 ? months : (1 - Math.pow(1 + r, -months)) / r;
  const foirLoanRaw = maxEmi * factor;
  const ltvLoanRaw = hleLtvCapLoan(down);
  const loanRaw = Math.min(foirLoanRaw, ltvLoanRaw);
  const priceRaw = loanRaw + down;
  const loan = Math.round(loanRaw);
  const price = loan + down;
  const emi = loan === 0 || months === 0
    ? 0
    : r === 0
      ? Math.round(loan / months)
      : Math.round(loan * r * Math.pow(1 + r, months) / (Math.pow(1 + r, months) - 1));
  const zeroReason = effYears === 0 ? "age" : maxEmi <= 0 ? "emis" : down === 0 && foirLoanRaw > 0 ? "down" : null;
  return {
    maxEmi: Math.round(maxEmi),
    effYears,
    effMonths: months,
    monthlyRate: r,
    foirLoan: Math.round(foirLoanRaw),
    foirLoanRaw,
    ltvBand: hleLtvBand(loan),
    ltvLoan: Math.round(ltvLoanRaw),
    ltvLoanRaw,
    loan,
    loanRaw,
    price,
    priceRaw,
    emi,
    ltvPct: price > 0 ? Math.round(loan / price * 1000) / 10 : 0,
    binding: loan === 0 ? "none" : loan === Math.round(foirLoanRaw) ? "FOIR" : "LTV",
    zeroReason,
    stampLow: Math.round(0.06 * price / 1000) * 1000,
    stampHigh: Math.round(0.08 * price / 1000) * 1000
  };
}

export function hleCompute(income, emis, down, ratePct, years, foirPct, age) {
  if (age === undefined) age = null;
  if (![income, emis, down, ratePct, years, foirPct].every(v => typeof v === "number" && Number.isFinite(v))) return null;
  if (age !== null && (typeof age !== "number" || !Number.isFinite(age))) return null;
  if (![income, emis, down, ratePct, years, foirPct].every(Number.isFinite)) return null;
  if (age !== null && !Number.isFinite(age)) return null;
  if (income !== Math.trunc(income) || emis !== Math.trunc(emis) || down !== Math.trunc(down) || years !== Math.trunc(years)) return null;
  if (age !== null && age !== Math.trunc(age)) return null;
  if (income < HLE_MIN_INCOME || income > HLE_MAX_INCOME) return null;
  if (emis < HLE_MIN_EMIS || emis > HLE_MAX_EMIS) return null;
  if (down < HLE_MIN_DOWN || down > HLE_MAX_DOWN) return null;
  if (ratePct < HLE_MIN_RATE || ratePct > HLE_MAX_RATE) return null;
  if (years < HLE_MIN_YEARS || years > HLE_MAX_YEARS) return null;
  if (foirPct !== 40 && foirPct !== 50 && foirPct !== 55) return null;
  if (age !== null && (age < HLE_MIN_AGE || age > HLE_MAX_AGE)) return null;
  const core = hleCore(income, emis, down, ratePct, years, foirPct, age);
  const comfortable = hleCore(income, emis, down, ratePct, years, 40, age);
  const stretch = hleCore(income, emis, down, ratePct, years, 55, age);
  const closed = hleCore(income, 0, down, ratePct, years, foirPct, age);
  const lowRate = hleCore(income, emis, down, Math.max(0, ratePct - 1), years, foirPct, age);
  return {
    income,
    emis,
    down,
    ratePct,
    years,
    foirPct,
    age,
    maxEmi: core.maxEmi,
    effYears: core.effYears,
    effMonths: core.effMonths,
    monthlyRate: core.monthlyRate,
    foirLoan: core.foirLoan,
    ltvBand: core.ltvBand,
    ltvLoan: core.ltvLoan,
    loan: core.loan,
    price: core.price,
    emi: core.emi,
    ltvPct: core.ltvPct,
    binding: core.binding,
    zeroReason: core.zeroReason,
    stampLow: core.stampLow,
    stampHigh: core.stampHigh,
    comfortableLoan: comfortable.loan,
    comfortablePrice: comfortable.price,
    stretchLoan: stretch.loan,
    stretchPrice: stretch.price,
    closedPrice: closed.price,
    upliftClosed: Math.round(closed.priceRaw - core.priceRaw),
    lowRatePrice: lowRate.price,
    upliftRate: Math.round(lowRate.priceRaw - core.priceRaw)
  };
}

