// Education loan EMI calculator.
// Loan amount + interest rate + repayment tenure + moratorium
// (course duration + grace, in months) + what happens to the simple
// interest during the moratorium -> the monthly EMI after the
// moratorium, the moratorium interest, the principal at EMI start,
// the total interest and total payable, a year-by-year amortisation
// table, and a pay-interest-now vs let-it-capitalise comparison.
// Conventions (stated on the page, matching the published anchors in
// sources.md):
// - Standard reducing-balance EMI: EMI = P x r x (1 + r)^n /
//   ((1 + r)^n - 1), where P is the principal at EMI start, r is the
//   monthly rate (annual rate / 12 / 100) and n is the tenure in
//   months. At 0% the EMI is P / n.
// - Moratorium interest is SIMPLE interest on the loan amount:
//   P x annual rate x moratorium months / 12 / 100, rounded to the
//   nearest rupee. If it is capitalised, the principal at EMI start
//   is the loan + that interest; if it is paid during the moratorium,
//   the principal stays the loan amount and the interest paid counts
//   in the all-in total.
// - The total repayment comes from the unrounded EMI - total =
//   EMI x n, rounded to the nearest rupee - which is why the rounded
//   EMI times the tenure can differ from the total by a few rupees
//   (the same convention as the site's car loan calculator).
// - "Total interest" on the page is the all-in interest: the
//   repayment-phase interest plus the moratorium interest. That is
//   the definition admitverse.com uses for its headline interest
//   figure (Rs 10,06,639 on the headline case), so the tool's
//   all-in figure matches it exactly; the two parts are also shown
//   separately.
// - The amortisation table telescopes exactly: the final year's
//   interest is the total repayment interest minus the earlier years'
//   rounded interest, and its principal is the principal at EMI start
//   minus the earlier years' rounded principal, so both columns sum
//   exactly (the same method as the site's car loan calculator).
//   Two ranking pages get their final row wrong by Re 1 - see
//   math-tests.md - and the tool does not copy the error.
// All money outputs round to the nearest rupee.
export const EL_MIN_AMOUNT = 50000;
export const EL_MAX_AMOUNT = 15000000;
export const EL_MIN_RATE = 0;
export const EL_MAX_RATE = 16;
export const EL_MIN_YEARS = 1;
export const EL_MAX_YEARS = 15;
export const EL_MIN_MORATORIUM = 0;
export const EL_MAX_MORATORIUM = 60;

export function elEmi(principal, annualRatePct, months) {
  const P = Number(principal);
  const pct = Number(annualRatePct);
  const n = Math.round(Number(months));
  if (!Number.isFinite(P) || !Number.isFinite(pct) || !Number.isFinite(n)) return null;
  if (!(P > 0) || !(n > 0) || !(pct >= 0)) return null;
  const r = pct / 1200;
  if (r === 0) return P / n;
  return P * r * Math.pow(1 + r, n) / (Math.pow(1 + r, n) - 1);
}

export function elSchedule(principal, annualRatePct, months, emiExact, totalInterest) {
  const P = Math.trunc(Number(principal));
  const pct = Number(annualRatePct);
  const n = Math.round(Number(months));
  const emi = Number(emiExact);
  if (!Number.isFinite(P) || !Number.isFinite(pct) || !Number.isFinite(n) || !Number.isFinite(emi)) return null;
  if (!(P > 0) || !(n > 0) || !(pct >= 0)) return null;
  const r = pct / 1200;
  const totalYears = Math.ceil(n / 12);
  let balance = P;
  let done = 0;
  let year = 1;
  let prevPrincipal = 0;
  let prevInterest = 0;
  const rows = [];
  while (done < n) {
    const mInYear = Math.min(12, n - done);
    const openingExact = balance;
    let yInt = 0;
    let yPrin = 0;
    for (let m = 0; m < mInYear; m++) {
      done++;
      const interest = balance * r;
      let principal = emi - interest;
      if (done === n) principal = balance;
      balance -= principal;
      if (balance > 0 && balance <= 0.01) balance = 0;
      yInt += interest;
      yPrin += principal;
    }
    if (year < totalYears) {
      const row = {
        year,
        label: mInYear === 12 ? "Year " + year : "Year " + year + " (" + mInYear + " months)",
        opening: roundRupee(openingExact),
        interest: roundRupee(yInt),
        principal: roundRupee(yPrin),
        closing: roundRupee(balance),
        payments: roundRupee(yInt + yPrin)
      };
      rows.push(row);
      prevPrincipal += row.principal;
      prevInterest += row.interest;
    } else {
      const interestR = totalInterest - prevInterest;
      const principalR = P - prevPrincipal;
      rows.push({
        year,
        label: mInYear === 12 ? "Year " + year : "Year " + year + " (" + mInYear + " months)",
        opening: roundRupee(openingExact),
        interest: interestR,
        principal: principalR,
        closing: 0,
        payments: interestR + principalR
      });
    }
    year++;
  }
  return rows;
}

export function elCore(amount, ratePct, years, moratoriumMonths, treatment) {
  const P = Number(amount);
  const rate = Number(ratePct);
  const y = Number(years);
  const mor = Number(moratoriumMonths);
  if (!Number.isFinite(P) || !Number.isFinite(rate) || !Number.isFinite(y) || !Number.isFinite(mor)) return null;
  if (!(P > 0) || !(rate >= 0) || !(y > 0) || !(mor >= 0)) return null;
  if (treatment !== "pay" && treatment !== "capitalise") return null;
  const n = Math.round(y * 12);
  const moratoriumInterest = roundRupee(P * rate * mor / 12 / 100);
  const monthlyMoratoriumInterest = mor > 0 ? roundRupee(P * rate / 1200) : 0;
  const principalAtStart = treatment === "capitalise" ? P + moratoriumInterest : P;
  const emiExact = elEmi(principalAtStart, rate, n);
  if (emiExact === null) return null;
  const emi = roundRupee(emiExact);
  const totalPayment = roundRupee(emiExact * n);
  const repaymentInterest = totalPayment - principalAtStart;
  const totalInterest = repaymentInterest + moratoriumInterest;
  const totalPayable = P + totalInterest;
  const yearlyRows = elSchedule(principalAtStart, rate, n, emiExact, repaymentInterest);
  if (yearlyRows === null) return null;
  return {
    amount: P,
    ratePct: rate,
    years: y,
    moratoriumMonths: mor,
    treatment,
    moratoriumInterest,
    monthlyMoratoriumInterest,
    principalAtStart,
    months: n,
    emiExact,
    emi,
    totalPayment,
    repaymentInterest,
    totalInterest,
    totalPayable,
    yearlyRows
  };
}

export function elCompare(amount, ratePct, years, moratoriumMonths) {
  const pay = elCore(amount, ratePct, years, moratoriumMonths, "pay");
  const capitalise = elCore(amount, ratePct, years, moratoriumMonths, "capitalise");
  if (pay === null || capitalise === null) return null;
  return {
    pay,
    capitalise,
    emiDifference: capitalise.emi - pay.emi,
    extraCost: capitalise.totalPayable - pay.totalPayable
  };
}

export function elCompute(amount, ratePct, years, moratoriumMonths, treatment) {
  if (![amount, ratePct, years, moratoriumMonths].every(v => typeof v === "number" && Number.isFinite(v))) return null;
  if (typeof treatment !== "string") return null;
  if (amount !== Math.trunc(amount) || years !== Math.trunc(years) || moratoriumMonths !== Math.trunc(moratoriumMonths)) return null;
  if (amount < EL_MIN_AMOUNT || amount > EL_MAX_AMOUNT) return null;
  if (ratePct < EL_MIN_RATE || ratePct > EL_MAX_RATE) return null;
  if (years < EL_MIN_YEARS || years > EL_MAX_YEARS) return null;
  if (moratoriumMonths < EL_MIN_MORATORIUM || moratoriumMonths > EL_MAX_MORATORIUM) return null;
  if (treatment !== "pay" && treatment !== "capitalise") return null;
  const core = elCore(amount, ratePct, years, moratoriumMonths, treatment);
  if (core === null) return null;
  const cmp = elCompare(amount, ratePct, years, moratoriumMonths);
  if (cmp === null) return null;
  return {
    ...core,
    comparison: {
      payEmi: cmp.pay.emi,
      payTotalPayment: cmp.pay.totalPayment,
      payRepaymentInterest: cmp.pay.repaymentInterest,
      payTotalInterest: cmp.pay.totalInterest,
      payTotalPayable: cmp.pay.totalPayable,
      capEmi: cmp.capitalise.emi,
      capTotalPayment: cmp.capitalise.totalPayment,
      capRepaymentInterest: cmp.capitalise.repaymentInterest,
      capTotalInterest: cmp.capitalise.totalInterest,
      capTotalPayable: cmp.capitalise.totalPayable,
      emiDifference: cmp.emiDifference,
      extraCost: cmp.extraCost
    }
  };
}

