// Bike loan EMI calculator.
// Bike on-road price + down payment + interest rate + tenure (years)
// -> the loan amount (price - down payment), the monthly EMI, the
// total interest, the total payable, the interest as a share of the
// loan, a year-by-year amortisation table and a month-by-month
// schedule. Conventions (stated on the page, matching the published
// anchors in sources.md):
// - Standard reducing-balance EMI: EMI = P x r x (1 + r)^n /
//   ((1 + r)^n - 1), where P is the loan amount, r is the monthly
//   rate (annual rate / 12 / 100) and n is the tenure in months.
//   At 0% the EMI is P / n.
// - The total repayment comes from the unrounded EMI - total =
//   EMI x n, rounded to the nearest rupee - which is why the rounded
//   EMI times the tenure can differ from the total by a few rupees
//   (the same convention as the site's car loan and education loan
//   calculators). Two ranking pages multiply the ROUNDED EMI
//   instead - see math-tests.md - and the tool does not copy that.
// - "Total payable" is what goes to the lender: the loan plus the
//   interest. The "total cost of the bike" adds the down payment
//   back: the on-road price plus the interest.
// - The amortisation tables telescope exactly: the final year's /
//   month's interest is the total interest minus the earlier rows'
//   rounded interest, and its principal is the loan minus the
//   earlier rows' rounded principal, so both columns sum exactly
//   (the same method as the site's car loan calculator).
// All money outputs round to the nearest rupee.
export const BL_MIN_PRICE = 40000;
export const BL_MAX_PRICE = 2500000;
export const BL_MIN_RATE = 0;
export const BL_MAX_RATE = 30;
export const BL_MIN_YEARS = 1;
export const BL_MAX_YEARS = 5;

export function blEmi(principal, annualRatePct, months) {
  const P = Number(principal);
  const pct = Number(annualRatePct);
  const n = Math.round(Number(months));
  if (!Number.isFinite(P) || !Number.isFinite(pct) || !Number.isFinite(n)) return null;
  if (!(P > 0) || !(n > 0) || !(pct >= 0)) return null;
  const r = pct / 1200;
  if (r === 0) return P / n;
  return P * r * Math.pow(1 + r, n) / (Math.pow(1 + r, n) - 1);
}

export function blSchedule(principal, annualRatePct, months, emiExact, totalInterest) {
  const P = Math.trunc(Number(principal));
  const pct = Number(annualRatePct);
  const n = Math.round(Number(months));
  const emi = Number(emiExact);
  if (!Number.isFinite(P) || !Number.isFinite(pct) || !Number.isFinite(n) || !Number.isFinite(emi)) return null;
  if (!(P > 0) || !(n > 0) || !(pct >= 0)) return null;
  const r = pct / 1200;
  const totalYears = Math.ceil(n / 12);
  let balance = P;
  let done = 0;
  let year = 1;
  let prevPrincipal = 0;
  let prevInterest = 0;
  const rows = [];
  while (done < n) {
    const mInYear = Math.min(12, n - done);
    const openingExact = balance;
    let yInt = 0;
    let yPrin = 0;
    for (let m = 0; m < mInYear; m++) {
      done++;
      const interest = balance * r;
      let principal = emi - interest;
      if (done === n) principal = balance;
      balance -= principal;
      if (balance > 0 && balance <= 0.01) balance = 0;
      yInt += interest;
      yPrin += principal;
    }
    if (year < totalYears) {
      const row = {
        year,
        label: mInYear === 12 ? "Year " + year : "Year " + year + " (" + mInYear + " months)",
        opening: roundRupee(openingExact),
        interest: roundRupee(yInt),
        principal: roundRupee(yPrin),
        closing: roundRupee(balance),
        payments: roundRupee(yInt + yPrin)
      };
      rows.push(row);
      prevPrincipal += row.principal;
      prevInterest += row.interest;
    } else {
      const interestR = totalInterest - prevInterest;
      const principalR = P - prevPrincipal;
      rows.push({
        year,
        label: mInYear === 12 ? "Year " + year : "Year " + year + " (" + mInYear + " months)",
        opening: roundRupee(openingExact),
        interest: interestR,
        principal: principalR,
        closing: 0,
        payments: interestR + principalR
      });
    }
    year++;
  }
  return rows;
}

export function blMonthlySchedule(principal, annualRatePct, months, emiExact, totalInterest) {
  const P = Math.trunc(Number(principal));
  const pct = Number(annualRatePct);
  const n = Math.round(Number(months));
  const emi = Number(emiExact);
  if (!Number.isFinite(P) || !Number.isFinite(pct) || !Number.isFinite(n) || !Number.isFinite(emi)) return null;
  if (!(P > 0) || !(n > 0) || !(pct >= 0)) return null;
  const r = pct / 1200;
  let balance = P;
  let prevPrincipal = 0;
  let prevInterest = 0;
  const rows = [];
  for (let m = 1; m <= n; m++) {
    const openingExact = balance;
    const interest = balance * r;
    let principal = emi - interest;
    if (m === n) principal = balance;
    balance -= principal;
    if (balance > 0 && balance <= 0.01) balance = 0;
    if (m < n) {
      const row = {
        month: m,
        opening: roundRupee(openingExact),
        emi: roundRupee(emi),
        principal: roundRupee(principal),
        interest: roundRupee(interest),
        closing: roundRupee(balance)
      };
      rows.push(row);
      prevPrincipal += row.principal;
      prevInterest += row.interest;
    } else {
      const interestR = totalInterest - prevInterest;
      const principalR = P - prevPrincipal;
      rows.push({
        month: m,
        opening: roundRupee(openingExact),
        emi: interestR + principalR,
        principal: principalR,
        interest: interestR,
        closing: 0
      });
    }
  }
  return rows;
}

export function blCore(price, down, ratePct, years) {
  const P = Number(price);
  const D = Number(down);
  const rate = Number(ratePct);
  const y = Number(years);
  if (!Number.isFinite(P) || !Number.isFinite(D) || !Number.isFinite(rate) || !Number.isFinite(y)) return null;
  if (!(P > 0) || !(D >= 0) || !(rate >= 0) || !(y > 0)) return null;
  const loan = P - D;
  if (!(loan > 0)) return null;
  const n = Math.round(y * 12);
  const emiExact = blEmi(loan, rate, n);
  if (emiExact === null) return null;
  const emi = roundRupee(emiExact);
  const totalPayment = roundRupee(emiExact * n);
  const totalInterest = totalPayment - loan;
  const totalPayable = loan + totalInterest;
  const bikeCost = P + totalInterest;
  const interestPct = totalInterest / loan * 100;
  const downPct = D / P * 100;
  const yearlyRows = blSchedule(loan, rate, n, emiExact, totalInterest);
  if (yearlyRows === null) return null;
  const monthlyRows = blMonthlySchedule(loan, rate, n, emiExact, totalInterest);
  if (monthlyRows === null) return null;
  return {
    price: P,
    down: D,
    downPct,
    loan,
    ratePct: rate,
    years: y,
    months: n,
    emiExact,
    emi,
    totalPayment,
    totalInterest,
    totalPayable,
    bikeCost,
    interestPct,
    yearlyRows,
    monthlyRows
  };
}

export function blCompute(price, down, ratePct, years) {
  if (![price, down, ratePct, years].every(v => typeof v === "number" && Number.isFinite(v))) return null;
  if (price !== Math.trunc(price) || down !== Math.trunc(down) || years !== Math.trunc(years)) return null;
  if (price < BL_MIN_PRICE || price > BL_MAX_PRICE) return null;
  if (down < 0 || down >= price) return null;
  if (ratePct < BL_MIN_RATE || ratePct > BL_MAX_RATE) return null;
  if (years < BL_MIN_YEARS || years > BL_MAX_YEARS) return null;
  return blCore(price, down, ratePct, years);
}

