// Simple interest calculator (India).
// Simple interest is charged or paid on the original principal only:
// SI = P x R x T / 100, where P is the principal in rupees, R the
// annual rate in percent and T the time in years. The total amount is
// P + SI. The same amount is added every year, so the balance grows
// in a straight line. Conventions (stated on the page, matching the
// published anchors in sources.md):
// - Time in months is converted to years by dividing by 12; time in
//   days by dividing by 365 (a 365-day year). A lender that counts
//   days differently (for example a 360-day year) gets a slightly
//   different figure for a period given in days.
// - A rate quoted per month is annualised by multiplying by 12 (the
//   Indian moneylender convention: "Rs 2 per hundred per month" is
//   2% a month, 24% a year as simple interest). The entered monthly
//   rate is capped at 3% a month so the annualised rate never
//   exceeds the 36% a year cap.
// - Interest per year is P x R / 100; per month is that divided by
//   12 and per day by 365. The tool shows whole rupees; the exact
//   two-decimal figures are kept alongside (for example the sample
//   is Rs 583.33 a month and Rs 19.18 a day, shown as Rs 583 and
//   Rs 19).
// - The compounding comparison is quarterly, as bank fixed deposits
//   usually compound: the balance is (1 + R/400) per quarter.
//   Interest is added only at the end of each quarter, so a part
//   quarter earns simple interest on the principal for the
//   remaining days - over 90 days at 7% the quarterly figure is
//   exactly the simple figure, Rs 1,726.03, as credocalc.com
//   states. The annual-compounding figure is kept alongside for
//   the nivesh.org.in anchor, which compares against annual
//   compounding.
// - Doubling time under simple interest is 100 / R years; under
//   quarterly compounding it is ln 2 / (4 ln(1 + R/400)) years.
// - The flat-rate loan comparison uses the standard reducing
//   balance EMI formula, EMI = P x r x (1+r)^n / ((1+r)^n - 1)
//   with r the monthly rate, and the effective reducing-balance
//   rate of a flat-rate quote is solved by bisection.
// All money outputs round to the nearest rupee.
export const SI_MIN_PRINCIPAL = 1000;
export const SI_MAX_PRINCIPAL = 10000000;
export const SI_MIN_RATE = 0.1;
export const SI_MAX_RATE = 36;
export const SI_MIN_RATE_MONTHLY = 0.1;
export const SI_MAX_RATE_MONTHLY = 3;
export const SI_MIN_TIME_YEARS = 0.1;
export const SI_MAX_TIME_YEARS = 30;
export const SI_MIN_TIME_MONTHS = 1;
export const SI_MAX_TIME_MONTHS = 360;
export const SI_MIN_TIME_DAYS = 1;
export const SI_MAX_TIME_DAYS = 10950;
export const SI_DAYS_PER_YEAR = 365;
export const SI_MONTHS_PER_YEAR = 12;
export const SI_COMPOUNDING_PER_YEAR = 4;
export const SI_TIME_UNITS = ["years", "months", "days"];
export const SI_RATE_BASES = ["year", "month"];

export function siTimeYears(timeValue, timeUnit) {
  const v = Number(timeValue);
  if (!Number.isFinite(v) || !(v > 0)) return null;
  if (timeUnit === "years") return v;
  if (timeUnit === "months") return v / SI_MONTHS_PER_YEAR;
  if (timeUnit === "days") return v / SI_DAYS_PER_YEAR;
  return null;
}

export function siAnnualRate(rate, rateBasis) {
  const r = Number(rate);
  if (!Number.isFinite(r) || !(r > 0)) return null;
  if (rateBasis === "year") return r;
  if (rateBasis === "month") return r * SI_MONTHS_PER_YEAR;
  return null;
}

export function siRound2(n) {
  return Math.round(n * 100) / 100;
}

export function siRound1(n) {
  return Math.round(n * 10) / 10;
}

export function siCompoundQuarterlyExact(principal, annualRate, timeYears) {
  const p = Number(principal);
  const r = Number(annualRate);
  const t = Number(timeYears);
  if (!Number.isFinite(p) || !Number.isFinite(r) || !Number.isFinite(t)) return null;
  if (!(p > 0) || !(r > 0) || !(t > 0)) return null;
  const fullQuarters = Math.floor(4 * t + 1e-9);
  const remainderYears = t - fullQuarters / SI_COMPOUNDING_PER_YEAR;
  const balance = p * Math.pow(1 + r / (100 * SI_COMPOUNDING_PER_YEAR), fullQuarters)
    + p * r * remainderYears / 100;
  return balance - p;
}

export function siCompoundAnnualExact(principal, annualRate, timeYears) {
  const p = Number(principal);
  const r = Number(annualRate);
  const t = Number(timeYears);
  if (!Number.isFinite(p) || !Number.isFinite(r) || !Number.isFinite(t)) return null;
  if (!(p > 0) || !(r > 0) || !(t > 0)) return null;
  return p * (Math.pow(1 + r / 100, t) - 1);
}

export function siGrowthRows(principal, annualRate, timeYears) {
  const p = Number(principal);
  const r = Number(annualRate);
  const t = Number(timeYears);
  if (!Number.isFinite(p) || !Number.isFinite(r) || !Number.isFinite(t)) return null;
  if (!(p > 0) || !(r > 0) || !(t > 0)) return null;
  const rows = [];
  const whole = Math.floor(t + 1e-9);
  for (let y = 1; y <= whole; y++) {
    const si = roundRupee(p * r * y / 100);
    const ci = roundRupee(siCompoundQuarterlyExact(p, r, y));
    rows.push({
      t: y,
      simpleInterest: si,
      simpleBalance: p + si,
      compoundInterest: ci,
      compoundBalance: p + ci,
      extra: ci - si
    });
  }
  if (t - whole > 1e-9) {
    const si = roundRupee(p * r * t / 100);
    const ci = roundRupee(siCompoundQuarterlyExact(p, r, t));
    rows.push({
      t,
      simpleInterest: si,
      simpleBalance: p + si,
      compoundInterest: ci,
      compoundBalance: p + ci,
      extra: ci - si
    });
  }
  return rows;
}

export function siReducingEmi(principal, annualRate, months) {
  const p = Number(principal);
  const r = Number(annualRate) / 1200;
  const n = Number(months);
  if (!Number.isFinite(p) || !Number.isFinite(r) || !Number.isFinite(n)) return null;
  if (!(p > 0) || !(r > 0) || !(n > 0)) return null;
  return p * r * Math.pow(1 + r, n) / (Math.pow(1 + r, n) - 1);
}

export function siEffectiveRate(flatEmi, principal, months) {
  const e = Number(flatEmi);
  const p = Number(principal);
  const n = Number(months);
  if (!Number.isFinite(e) || !Number.isFinite(p) || !Number.isFinite(n)) return null;
  if (!(e > 0) || !(p > 0) || !(n > 0)) return null;
  let lo = 0;
  let hi = 0.05;
  for (let i = 0; i < 200; i++) {
    const mid = (lo + hi) / 2;
    if (siReducingEmi(p, mid * 1200, n) > e) hi = mid;
    else lo = mid;
  }
  return siRound2((lo + hi) / 2 * 1200);
}

export function siCore(principal, rate, rateBasis, timeValue, timeUnit) {
  const p = Number(principal);
  const r = Number(rate);
  const v = Number(timeValue);
  if (!Number.isFinite(p) || !Number.isFinite(r) || !Number.isFinite(v)) return null;
  if (!(p > 0) || !(r > 0) || !(v > 0)) return null;
  if (!SI_RATE_BASES.includes(rateBasis)) return null;
  if (!SI_TIME_UNITS.includes(timeUnit)) return null;
  const annualRate = siAnnualRate(r, rateBasis);
  const timeYears = siTimeYears(v, timeUnit);
  if (annualRate === null || timeYears === null) return null;
  const principalRounded = roundRupee(p);
  const siExact = p * annualRate * timeYears / 100;
  const si = roundRupee(siExact);
  const total = principalRounded + si;
  const perYearExact = p * annualRate / 100;
  const perYear = roundRupee(perYearExact);
  const perMonthExact = perYearExact / SI_MONTHS_PER_YEAR;
  const perMonth = roundRupee(perMonthExact);
  const perDayExact = perYearExact / SI_DAYS_PER_YEAR;
  const perDay = roundRupee(perDayExact);
  const compoundExact = siCompoundQuarterlyExact(p, annualRate, timeYears);
  const compoundInterest = roundRupee(compoundExact);
  const compoundAnnualExact = siCompoundAnnualExact(p, annualRate, timeYears);
  const compoundAnnualInterest = roundRupee(compoundAnnualExact);
  const growthRows = siGrowthRows(p, annualRate, timeYears);
  if (compoundExact === null || compoundAnnualExact === null || growthRows === null) return null;
  return {
    principal: principalRounded,
    rate: r,
    rateBasis,
    annualRate,
    timeValue: v,
    timeUnit,
    timeYears,
    siExact: siRound2(siExact),
    si,
    total,
    perYearExact: siRound2(perYearExact),
    perYear,
    perMonthExact: siRound2(perMonthExact),
    perMonth,
    perDayExact: siRound2(perDayExact),
    perDay,
    compoundExact: siRound2(compoundExact),
    compoundInterest,
    compoundAnnualExact: siRound2(compoundAnnualExact),
    compoundAnnualInterest,
    extra: compoundInterest - si,
    extraExact: siRound2(compoundExact - siExact),
    extraAnnual: compoundAnnualInterest - si,
    growthRows,
    doubleSimpleYears: siRound1(100 / annualRate),
    doubleCompoundYears: siRound1(Math.log(2) / (SI_COMPOUNDING_PER_YEAR * Math.log(1 + annualRate / (100 * SI_COMPOUNDING_PER_YEAR))))
  };
}

export function siCompute(principal, rate, rateBasis, timeValue, timeUnit) {
  if (![principal, rate, timeValue].every(v => typeof v === "number" && Number.isFinite(v))) return null;
  if (typeof rateBasis !== "string" || typeof timeUnit !== "string") return null;
  if (principal < SI_MIN_PRINCIPAL || principal > SI_MAX_PRINCIPAL) return null;
  if (rateBasis === "year" && (rate < SI_MIN_RATE || rate > SI_MAX_RATE)) return null;
  if (rateBasis === "month" && (rate < SI_MIN_RATE_MONTHLY || rate > SI_MAX_RATE_MONTHLY)) return null;
  if (!SI_RATE_BASES.includes(rateBasis) || !SI_TIME_UNITS.includes(timeUnit)) return null;
  if (timeUnit === "years" && (timeValue < SI_MIN_TIME_YEARS || timeValue > SI_MAX_TIME_YEARS)) return null;
  if (timeUnit === "months" && (timeValue < SI_MIN_TIME_MONTHS || timeValue > SI_MAX_TIME_MONTHS)) return null;
  if (timeUnit === "days" && (timeValue < SI_MIN_TIME_DAYS || timeValue > SI_MAX_TIME_DAYS)) return null;
  const core = siCore(principal, rate, rateBasis, timeValue, timeUnit);
  if (core === null) return null;
  return { ...core, answer: core.si };
}

