// CAGR calculator (India).
// The compound annual growth rate is the one steady yearly rate
// that takes a starting value to an ending value over a period:
// CAGR = (End / Start)^(1/years) - 1. Rearranged, the ending
// value is Start x (1 + CAGR)^years, and the years needed are
// ln(End / Start) / ln(1 + CAGR). The calculator works all three
// ways. Conventions (stated on the page, matching the published
// anchors in sources.md):
// - A period is entered in years and months; each month counts as
//   one twelfth of a year, so 6 years and 6 months is 6.5 years.
// - The growth table is worked out at the EXACT (unrounded) CAGR,
//   so its final row lands exactly on the ending value. The
//   displayed CAGR is rounded to two decimals; the table is not
//   recomputed from the rounded figure. This is why the sample's
//   first-year value is Rs 5,66,612 (at the exact 13.3224%) rather
//   than Rs 5,66,600 (at the rounded 13.32%).
// - A growth row's "that year" figure is the exact growth that
//   year rounded to the nearest rupee, and "so far" is the rounded
//   value minus the start. This reproduces ap7am.com's
//   year-by-year table cell for cell.
// - The fixed-deposit comparison compounds at 7% a year, the rate
//   quickworkstudio.com uses for its FD check. "Beats the FD by"
//   is the difference in percentage points between the CAGR and
//   7%, not a ratio.
// - The rule of 72 (72 / CAGR) is only a quick estimate of the
//   doubling time; the exact doubling time is ln 2 / ln(1 + CAGR).
//   Both are shown only when the CAGR is positive. At a negative
//   CAGR the money does not double; the halving time
//   ln 0.5 / ln(1 + CAGR) is shown instead.
// - The equivalent monthly rate is (1 + CAGR)^(1/12) - 1: a 12%
//   CAGR is 0.95% a month, not 1%. Going the other way, 1% a
//   month compounds to 12.68% a year.
// - Past CAGR is not a forecast, and CAGR hides volatility: it
//   looks only at the start and the end.
// All money outputs round to the nearest rupee; rates and returns
// round to two decimals; doubling times round to one decimal.
export const CAGR_MIN_START = 1000;
export const CAGR_MAX_START = 100000000;
export const CAGR_MIN_END = 1;
export const CAGR_MAX_END = 100000000;
export const CAGR_MIN_RATE = -90;
export const CAGR_MAX_RATE = 100;
export const CAGR_MIN_PERIOD_YEARS = 0.5;
export const CAGR_MAX_PERIOD_YEARS = 50;
export const CAGR_MAX_YEARS_INPUT = 50;
export const CAGR_MAX_MONTHS_INPUT = 11;
export const CAGR_MONTHS_PER_YEAR = 12;
export const CAGR_FD_RATE = 7;
export const CAGR_MODES = ["cagr", "end", "years"];

export function cagrRound2(n) {
  return Math.round(n * 100) / 100;
}

export function cagrRound1(n) {
  return Math.round(n * 10) / 10;
}

export function cagrPeriodYears(years, months) {
  const y = Number(years);
  const m = Number(months);
  if (!Number.isFinite(y) || !Number.isFinite(m)) return null;
  if (!(y >= 0) || !(m >= 0) || !(m <= CAGR_MAX_MONTHS_INPUT)) return null;
  if (y > CAGR_MAX_YEARS_INPUT) return null;
  return y + m / CAGR_MONTHS_PER_YEAR;
}

export function cagrYearsMonths(periodYears) {
  const t = Number(periodYears);
  if (!Number.isFinite(t) || !(t > 0)) return null;
  let years = Math.floor(t + 1e-9);
  let months = Math.round((t - years) * CAGR_MONTHS_PER_YEAR);
  if (months === CAGR_MONTHS_PER_YEAR) {
    years += 1;
    months = 0;
  }
  return { years, months };
}

export function cagrFromValues(start, end, periodYears) {
  const s = Number(start);
  const e = Number(end);
  const t = Number(periodYears);
  if (!Number.isFinite(s) || !Number.isFinite(e) || !Number.isFinite(t)) return null;
  if (!(s > 0) || !(e > 0) || !(t > 0)) return null;
  return (Math.pow(e / s, 1 / t) - 1) * 100;
}

export function cagrEndValue(start, ratePct, periodYears) {
  const s = Number(start);
  const r = Number(ratePct);
  const t = Number(periodYears);
  if (!Number.isFinite(s) || !Number.isFinite(r) || !Number.isFinite(t)) return null;
  if (!(s > 0) || !(t > 0)) return null;
  if (r <= -100) return null;
  return s * Math.pow(1 + r / 100, t);
}

export function cagrYearsNeeded(start, end, ratePct) {
  const s = Number(start);
  const e = Number(end);
  const r = Number(ratePct);
  if (!Number.isFinite(s) || !Number.isFinite(e) || !Number.isFinite(r)) return null;
  if (!(s > 0) || !(e > 0)) return null;
  if (r === 0 || r <= -100) return null;
  const years = Math.log(e / s) / Math.log(1 + r / 100);
  if (!Number.isFinite(years) || !(years > 0)) return null;
  return years;
}

export function cagrMonthlyRate(ratePct) {
  const r = Number(ratePct);
  if (!Number.isFinite(r) || r <= -100) return null;
  return (Math.pow(1 + r / 100, 1 / CAGR_MONTHS_PER_YEAR) - 1) * 100;
}

export function cagrDoubleYears(ratePct) {
  const r = Number(ratePct);
  if (!Number.isFinite(r) || !(r > 0)) return null;
  return Math.log(2) / Math.log(1 + r / 100);
}

export function cagrRule72Years(ratePct) {
  const r = Number(ratePct);
  if (!Number.isFinite(r) || !(r > 0)) return null;
  return 72 / r;
}

export function cagrHalfYears(ratePct) {
  const r = Number(ratePct);
  if (!Number.isFinite(r) || !(r >= -100) || !(r < 0)) return null;
  return Math.log(0.5) / Math.log(1 + r / 100);
}

export function cagrGrowthRows(start, ratePct, periodYears) {
  const s = Number(start);
  const r = Number(ratePct);
  const t = Number(periodYears);
  if (!Number.isFinite(s) || !Number.isFinite(r) || !Number.isFinite(t)) return null;
  if (!(s > 0) || !(t > 0)) return null;
  if (r <= -100) return null;
  const rows = [];
  const whole = Math.floor(t + 1e-9);
  let prevExact = s;
  for (let y = 1; y <= whole; y++) {
    const exact = s * Math.pow(1 + r / 100, y);
    const value = roundRupee(exact);
    rows.push({
      t: y,
      value,
      growth: roundRupee(exact - prevExact),
      cumulative: value - roundRupee(s)
    });
    prevExact = exact;
  }
  if (t - whole > 1e-9) {
    const exact = s * Math.pow(1 + r / 100, t);
    const value = roundRupee(exact);
    rows.push({
      t,
      value,
      growth: roundRupee(exact - prevExact),
      cumulative: value - roundRupee(s)
    });
  }
  return rows;
}

export function cagrCore(mode, start, end, rate, years, months) {
  if (!CAGR_MODES.includes(mode)) return null;
  const s = Number(start);
  if (!Number.isFinite(s) || !(s > 0)) return null;
  let periodYears;
  let cagrExact;
  let endExact;
  if (mode === "cagr" || mode === "end") {
    periodYears = cagrPeriodYears(years, months);
    if (periodYears === null) return null;
    if (periodYears < CAGR_MIN_PERIOD_YEARS || periodYears > CAGR_MAX_PERIOD_YEARS) return null;
  }
  if (mode === "cagr") {
    const e = Number(end);
    if (!Number.isFinite(e) || !(e > 0)) return null;
    cagrExact = cagrFromValues(s, e, periodYears);
    if (cagrExact === null) return null;
    endExact = e;
  } else if (mode === "end") {
    const r = Number(rate);
    if (!Number.isFinite(r)) return null;
    cagrExact = r;
    endExact = cagrEndValue(s, r, periodYears);
    if (endExact === null) return null;
  } else {
    const e = Number(end);
    const r = Number(rate);
    if (!Number.isFinite(e) || !(e > 0)) return null;
    if (!Number.isFinite(r)) return null;
    cagrExact = r;
    periodYears = cagrYearsNeeded(s, e, r);
    if (periodYears === null || periodYears > CAGR_MAX_PERIOD_YEARS) return null;
    endExact = e;
  }
  const startRounded = roundRupee(s);
  const endRounded = roundRupee(endExact);
  const gainExact = endExact - s;
  const gain = endRounded - startRounded;
  const absReturnExact = gainExact / s * 100;
  const multipleExact = endExact / s;
  const monthlyExact = cagrMonthlyRate(cagrExact);
  const fdExact = cagrEndValue(s, CAGR_FD_RATE, periodYears);
  const fdEnd = roundRupee(fdExact);
  const growthRows = cagrGrowthRows(s, cagrExact, periodYears);
  if (monthlyExact === null || fdExact === null || growthRows === null) return null;
  const split = cagrYearsMonths(periodYears);
  if (split === null) return null;
  const doubleExact = cagrDoubleYears(cagrExact);
  const rule72Exact = cagrRule72Years(cagrExact);
  const halfExact = cagrHalfYears(cagrExact);
  return {
    mode,
    start: startRounded,
    end: endRounded,
    endExact: cagrRound2(endExact),
    rate: cagrExact,
    years: split.years,
    months: split.months,
    periodYears,
    cagr: cagrRound2(cagrExact),
    cagrExact,
    absReturn: cagrRound2(absReturnExact),
    absReturnExact: cagrRound2(absReturnExact),
    gain,
    gainExact: cagrRound2(gainExact),
    multiple: cagrRound2(multipleExact),
    multipleExact,
    monthlyRate: cagrRound2(monthlyExact),
    monthlyRateExact: cagrRound2(monthlyExact),
    fdEnd,
    fdGain: fdEnd - startRounded,
    beatsFd: cagrRound2(cagrExact - CAGR_FD_RATE),
    doubleYears: doubleExact === null ? null : cagrRound1(doubleExact),
    doubleYearsExact: doubleExact,
    rule72Years: rule72Exact === null ? null : cagrRound1(rule72Exact),
    rule72YearsExact: rule72Exact,
    halfYears: halfExact === null ? null : cagrRound1(halfExact),
    halfYearsExact: halfExact,
    growthRows,
    answer: mode === "cagr" ? cagrRound2(cagrExact) : mode === "end" ? endRounded : cagrRound2(periodYears)
  };
}

export function cagrCompute(mode, start, end, rate, years, months) {
  if (typeof mode !== "string" || !CAGR_MODES.includes(mode)) return null;
  if (typeof start !== "number" || !Number.isFinite(start)) return null;
  if (start < CAGR_MIN_START || start > CAGR_MAX_START) return null;
  if (mode === "cagr" || mode === "years") {
    if (typeof end !== "number" || !Number.isFinite(end)) return null;
    if (end < CAGR_MIN_END || end > CAGR_MAX_END) return null;
  }
  if (mode === "end" || mode === "years") {
    if (typeof rate !== "number" || !Number.isFinite(rate)) return null;
    if (rate < CAGR_MIN_RATE || rate > CAGR_MAX_RATE) return null;
  }
  if (mode === "cagr" || mode === "end") {
    if (typeof years !== "number" || !Number.isFinite(years)) return null;
    if (typeof months !== "number" || !Number.isFinite(months)) return null;
    if (years < 0 || years > CAGR_MAX_YEARS_INPUT) return null;
    if (months < 0 || months > CAGR_MAX_MONTHS_INPUT) return null;
    const t = years + months / CAGR_MONTHS_PER_YEAR;
    if (t < CAGR_MIN_PERIOD_YEARS || t > CAGR_MAX_PERIOD_YEARS) return null;
  }
  const core = cagrCore(mode, start, end, rate, years, months);
  if (core === null) return null;
  return core;
}

