// BMR calculator (India).
// Basal Metabolic Rate is the calories the body burns at complete
// rest. The calculator uses the Mifflin-St Jeor equation (1990),
// the formula the published Indian BMR calculators use and the one
// recommended by the Academy of Nutrition and Dietetics:
//   Men:   BMR = (10 x weight in kg) + (6.25 x height in cm)
//                - (5 x age in years) + 5
//   Women: BMR = (10 x weight in kg) + (6.25 x height in cm)
//                - (5 x age in years) - 161
// Total Daily Energy Expenditure (TDEE) is BMR x an activity
// multiplier: Sedentary 1.2, Lightly active 1.375, Moderately
// active 1.55, Very active 1.725, Extra active 1.9.
// Conventions (stated on the page, matching the published anchors
// in sources.md):
// - BMR and TDEE round to whole kcal a day; weekly figures are the
//   daily figure x 7, monthly figures x 30.
// - The weight-loss target is TDEE - 500 kcal, but never below the
//   BMR: when TDEE - 500 would fall below the BMR, the target is
//   the BMR itself and the page says so. The weight-gain target is
//   TDEE + 300 kcal. Both follow the ranges the fetched competitor
//   pages publish (lose 300-500 below TDEE, gain 250-300 above).
// - The BMI shown with the result uses the same WHO categories as
//   the site's own BMI calculator (underweight below 18.5,
//   healthy 18.5-24.9, overweight 25-29.9, obese 30 and above).
//   Indian guidance (ICMR / Asia-Pacific) uses lower thresholds
//   for Indians — overweight from 23, obese from 25 — and the page
//   says so; the category shown stays the WHO one so it agrees
//   with the BMI calculator.
// - The Harris-Benedict equation (revised 1984) is shown only as a
//   comparison: it runs about 5% higher than Mifflin-St Jeor and
//   is no longer the recommended formula.
// - The formula is validated for healthy adults. The calculator
//   accepts ages 18-80 only, and the page says it is not for
//   under-18s, pregnant or breastfeeding women, or people with a
//   thyroid disorder — all of whom need separate guidance.
// - 1 inch = 2.54 cm exactly, so feet and inches convert without
//   rounding loss.
// All calorie outputs round to the nearest whole kcal (half up);
// percentages round to one decimal.
export const BMR_MIN_AGE = 18;
export const BMR_MAX_AGE = 80;
export const BMR_MIN_WEIGHT_KG = 30;
export const BMR_MAX_WEIGHT_KG = 200;
export const BMR_MIN_HEIGHT_CM = 130;
export const BMR_MAX_HEIGHT_CM = 220;
export const BMR_MIN_FEET = 3;
export const BMR_MAX_FEET = 7;
export const BMR_MAX_INCHES = 11;
export const BMR_LOSE_DEFICIT = 500;
export const BMR_GAIN_SURPLUS = 300;
export const BMR_ACTIVITY_LEVELS = [
  { id: "sedentary", label: "Sedentary", multiplier: 1.2, note: "Desk job, little or no exercise" },
  { id: "light", label: "Lightly active", multiplier: 1.375, note: "Light exercise 1-3 days a week" },
  { id: "moderate", label: "Moderately active", multiplier: 1.55, note: "Moderate exercise 3-5 days a week" },
  { id: "very", label: "Very active", multiplier: 1.725, note: "Hard exercise 6-7 days a week" },
  { id: "extra", label: "Extra active", multiplier: 1.9, note: "Physical job or training twice a day" }
];

export function bmrRound(n) {
  return Math.round(n);
}

export function bmrRound2(n) {
  return Math.round(n * 100) / 100;
}

export function bmrRound1(n) {
  return Math.round(n * 10) / 10;
}

export function bmrActivity(id) {
  if (typeof id !== "string") return null;
  const found = BMR_ACTIVITY_LEVELS.find(level => level.id === id);
  return found || null;
}

export function bmrFromMetric(sex, age, weightKg, heightCm) {
  if (sex !== "male" && sex !== "female") return null;
  const a = Number(age);
  const w = Number(weightKg);
  const h = Number(heightCm);
  if (!Number.isFinite(a) || !Number.isFinite(w) || !Number.isFinite(h)) return null;
  if (!(a >= BMR_MIN_AGE) || !(a <= BMR_MAX_AGE)) return null;
  if (!(w >= BMR_MIN_WEIGHT_KG) || !(w <= BMR_MAX_WEIGHT_KG)) return null;
  if (!(h >= BMR_MIN_HEIGHT_CM) || !(h <= BMR_MAX_HEIGHT_CM)) return null;
  return 10 * w + 6.25 * h - 5 * a + (sex === "male" ? 5 : -161);
}

export function bmrHarrisBenedict(sex, age, weightKg, heightCm) {
  if (sex !== "male" && sex !== "female") return null;
  const a = Number(age);
  const w = Number(weightKg);
  const h = Number(heightCm);
  if (!Number.isFinite(a) || !Number.isFinite(w) || !Number.isFinite(h)) return null;
  if (!(a >= BMR_MIN_AGE) || !(a <= BMR_MAX_AGE)) return null;
  if (!(w >= BMR_MIN_WEIGHT_KG) || !(w <= BMR_MAX_WEIGHT_KG)) return null;
  if (!(h >= BMR_MIN_HEIGHT_CM) || !(h <= BMR_MAX_HEIGHT_CM)) return null;
  if (sex === "male") return 88.362 + 13.397 * w + 4.799 * h - 5.677 * a;
  return 447.593 + 9.247 * w + 3.098 * h - 4.33 * a;
}

export function bmrHeightCmFromFeetInches(feet, inches) {
  const ft = Number(feet);
  const inch = Number(inches);
  if (!Number.isFinite(ft) || !Number.isFinite(inch)) return null;
  if (!Number.isInteger(ft) || !Number.isInteger(inch)) return null;
  if (!(ft >= BMR_MIN_FEET) || !(ft <= BMR_MAX_FEET)) return null;
  if (!(inch >= 0) || !(inch <= BMR_MAX_INCHES)) return null;
  return (ft * 12 + inch) * 2.54;
}

export function bmrTdee(bmr, multiplier) {
  const b = Number(bmr);
  const m = Number(multiplier);
  if (!Number.isFinite(b) || !Number.isFinite(m)) return null;
  if (!(b > 0) || !(m > 0)) return null;
  return b * m;
}

export function bmrTdeeRows(bmrExact) {
  const b = Number(bmrExact);
  if (!Number.isFinite(b) || !(b > 0)) return null;
  return BMR_ACTIVITY_LEVELS.map(level => ({
    id: level.id,
    label: level.label,
    multiplier: level.multiplier,
    note: level.note,
    tdee: bmrRound(b * level.multiplier)
  }));
}

export function bmrCore(sex, age, weightKg, heightCm, activityId) {
  const bmrExact = bmrFromMetric(sex, age, weightKg, heightCm);
  if (bmrExact === null) return null;
  const level = bmrActivity(activityId);
  if (level === null) return null;
  const tdeeExact = bmrTdee(bmrExact, level.multiplier);
  if (tdeeExact === null) return null;
  const bmr = bmrRound(bmrExact);
  const tdee = bmrRound(tdeeExact);
  const tdeeRows = bmrTdeeRows(bmrExact);
  if (tdeeRows === null) return null;
  const loseExact = tdeeExact - BMR_LOSE_DEFICIT;
  const loseFloored = loseExact < bmrExact;
  const loseTarget = bmrRound(loseFloored ? bmrExact : loseExact);
  const gainTarget = bmrRound(tdeeExact + BMR_GAIN_SURPLUS);
  const bmiResult = bmiCompute(heightCm, weightKg);
  if (bmiResult === null) return null;
  const hbExact = bmrHarrisBenedict(sex, age, weightKg, heightCm);
  if (hbExact === null) return null;
  const hbBmr = bmrRound(hbExact);
  return {
    sex,
    age: Number(age),
    weightKg: Number(weightKg),
    heightCm: Number(heightCm),
    activity: level.id,
    activityLabel: level.label,
    multiplier: level.multiplier,
    bmr,
    bmrExact: bmrRound2(bmrExact),
    tdee,
    tdeeExact: bmrRound2(tdeeExact),
    tdeeRows,
    weeklyBmr: bmrRound(bmrExact * 7),
    weeklyTdee: bmrRound(tdeeExact * 7),
    monthlyBmr: bmrRound(bmrExact * 30),
    monthlyTdee: bmrRound(tdeeExact * 30),
    loseTarget,
    loseFloored,
    maintainTarget: tdee,
    gainTarget,
    bmi: bmiResult.bmi1dp,
    bmiExact: bmiResult.bmi,
    bmiCategory: bmiResult.category.label,
    bmiCategoryKey: bmiResult.category.key,
    healthyLow: bmrRound1(bmiResult.healthyLow),
    healthyHigh: bmrRound1(bmiResult.healthyHigh),
    hbBmr,
    hbDiff: hbBmr - bmr,
    hbDiffPct: bmrRound1((hbExact - bmrExact) / bmrExact * 100),
    answer: bmr
  };
}

export function bmrCompute(sex, age, weightKg, heightCm, activityId) {
  if (typeof sex !== "string" || (sex !== "male" && sex !== "female")) return null;
  if (typeof age !== "number" || !Number.isFinite(age)) return null;
  if (!Number.isInteger(age)) return null;
  if (typeof weightKg !== "number" || !Number.isFinite(weightKg)) return null;
  if (typeof heightCm !== "number" || !Number.isFinite(heightCm)) return null;
  if (typeof activityId !== "string") return null;
  if (age < BMR_MIN_AGE || age > BMR_MAX_AGE) return null;
  if (weightKg < BMR_MIN_WEIGHT_KG || weightKg > BMR_MAX_WEIGHT_KG) return null;
  if (heightCm < BMR_MIN_HEIGHT_CM || heightCm > BMR_MAX_HEIGHT_CM) return null;
  const core = bmrCore(sex, age, weightKg, heightCm, activityId);
  if (core === null) return null;
  return core;
}

export function bmrComputeFromFeetInches(sex, age, weightKg, feet, inches, activityId) {
  const heightCm = bmrHeightCmFromFeetInches(feet, inches);
  if (heightCm === null) return null;
  return bmrCompute(sex, age, weightKg, heightCm, activityId);
}

