export function tdsRound2(n) {
  return Math.round(n * 100) / 100;
}

export function tdsRoundInt(n) {
  return Math.round(n);
}

export function tdsTypeById(id) {
  if (typeof id !== "string") return null;
  const found = TDS_TYPES.find((t) => t.id === id);
  return found === undefined ? null : found;
}

export function tdsThresholdFor(type, seniorCitizen) {
  if (type.id === "bank-interest" && seniorCitizen === true) return type.seniorThresholdValue;
  return type.thresholdValue;
}

export function tdsThresholdTextFor(type, seniorCitizen) {
  if (type.id === "bank-interest" && seniorCitizen === true) return "₹1,00,000 a year";
  return type.threshold;
}

export function tdsNoPanRate(type) {
  if (typeof type.noPanRate === "number") return type.noPanRate;
  if (type.ratePct === null) return null;
  return Math.max(type.ratePct, TDS_NO_PAN_RATE);
}

export function tdsSlabNew(taxable) {
  const t = Number(taxable);
  if (!Number.isFinite(t) || t < 0) return null;
  const bands = [[400000, 0], [800000, 0.05], [1200000, 0.10], [1600000, 0.15], [2000000, 0.20], [2400000, 0.25], [Infinity, 0.30]];
  let tax = 0;
  let prev = 0;
  for (const [top, rate] of bands) {
    if (t <= prev) break;
    tax += (Math.min(t, top) - prev) * rate;
    prev = top;
  }
  return Math.round(tax);
}

export function tdsSurchargeRate(taxable) {
  const t = Number(taxable);
  if (!Number.isFinite(t) || t < 0) return null;
  if (t <= 5000000) return 0;
  if (t <= 10000000) return 0.10;
  if (t <= 20000000) return 0.15;
  return 0.25;
}

export function tdsNewRegimeTax(taxable) {
  const t = Number(taxable);
  if (!Number.isFinite(t) || t < 0) return null;
  const slabTax = tdsSlabNew(t);
  if (slabTax === null) return null;
  let rebate = 0;
  let marginalRelief = 0;
  let afterRebate = slabTax;
  if (t <= TDS_REBATE_LIMIT) {
    rebate = Math.min(slabTax, TDS_REBATE_MAX);
    afterRebate = slabTax - rebate;
  } else if (slabTax > t - TDS_REBATE_LIMIT) {
    marginalRelief = slabTax - (t - TDS_REBATE_LIMIT);
    afterRebate = t - TDS_REBATE_LIMIT;
  }
  const surchargeRate = tdsSurchargeRate(t);
  const surcharge = Math.round(afterRebate * surchargeRate);
  const cess = Math.round((afterRebate + surcharge) * TDS_CESS_RATE);
  return {
    slabTax,
    rebate,
    marginalRelief,
    surchargeRate,
    surcharge,
    cess,
    taxAfterRebate: afterRebate,
    total: afterRebate + surcharge + cess
  };
}

export function tdsSalaryTax(grossSalary) {
  const g = Number(grossSalary);
  if (!Number.isFinite(g) || g < 0) return null;
  const taxable = Math.max(0, g - TDS_STANDARD_DEDUCTION);
  const tax = tdsNewRegimeTax(taxable);
  if (tax === null) return null;
  return {
    grossSalary: g,
    standardDeduction: Math.min(g, TDS_STANDARD_DEDUCTION),
    taxable,
    slabTax: tax.slabTax,
    rebate: tax.rebate,
    marginalRelief: tax.marginalRelief,
    surchargeRate: tax.surchargeRate,
    surcharge: tax.surcharge,
    cess: tax.cess,
    taxAfterRebate: tax.taxAfterRebate,
    annualTax: tax.total,
    monthlyTds: Math.round(tax.total / 12),
    monthlySalary: Math.round(g / 12)
  };
}

export function tdsCompute(typeId, amount, panFurnished, seniorCitizen) {
  const type = tdsTypeById(typeId);
  if (type === null) return null;
  if (typeof amount !== "number" || !Number.isFinite(amount)) return null;
  if (amount < TDS_MIN_AMOUNT || amount > TDS_MAX_AMOUNT) return null;
  if (typeof panFurnished !== "boolean" || typeof seniorCitizen !== "boolean") return null;
  const thresholdValue = tdsThresholdFor(type, seniorCitizen);
  const thresholdText = tdsThresholdTextFor(type, seniorCitizen);
  const base = {
    typeId: type.id,
    payment: type.payment,
    newSection: type.newSection,
    oldSection: type.oldSection,
    amount,
    amountLabel: type.amountLabel,
    panFurnished,
    seniorCitizen,
    applies: false,
    ratePct: type.ratePct,
    rateText: type.rateText,
    threshold: thresholdText,
    thresholdValue,
    thresholdUnit: type.thresholdUnit,
    compare: type.compare,
    baseKind: type.base,
    taxableBase: 0,
    tds: 0,
    tdsExact: 0,
    net: amount,
    monthlyTds: null,
    monthlyNet: null,
    annualTds: null,
    annualNet: null,
    salary: null,
    reason: null,
    answer: null
  };
  if (type.id === "salary") {
    const sal = tdsSalaryTax(amount);
    if (sal === null) return null;
    base.salary = sal;
    if (sal.annualTax <= 0) {
      base.applies = false;
      base.reason = "no-tax";
      base.net = sal.monthlySalary;
      base.monthlyNet = sal.monthlySalary;
      base.annualTds = 0;
      base.annualNet = amount;
      base.answer = 0;
      return base;
    }
    base.applies = true;
    if (panFurnished) {
      base.monthlyTds = sal.monthlyTds;
      base.ratePct = null;
      base.rateText = "Slab rates";
    } else {
      const noPanMonthly = Math.round(sal.monthlySalary * TDS_NO_PAN_RATE / 100);
      base.monthlyTds = Math.max(sal.monthlyTds, noPanMonthly);
      base.ratePct = TDS_NO_PAN_RATE;
      base.rateText = "20% (no PAN)";
    }
    base.tdsExact = base.monthlyTds * 12;
    base.tds = base.monthlyTds * 12;
    base.annualTds = base.monthlyTds * 12;
    base.monthlyNet = sal.monthlySalary - base.monthlyTds;
    base.net = base.monthlyNet;
    base.annualNet = amount - base.annualTds;
    base.taxableBase = amount;
    base.answer = base.monthlyTds;
    return base;
  }
  const rate = panFurnished ? type.ratePct : tdsNoPanRate(type);
  base.ratePct = rate;
  base.rateText = panFurnished
    ? type.rateText
    : (type.noPanRate !== undefined ? type.noPanRate + "% (no PAN)" : rate + "% (no PAN)");
  let applies;
  if (thresholdValue === null) {
    applies = true;
  } else if (type.compare === ">=") {
    applies = amount >= thresholdValue;
  } else {
    applies = amount > thresholdValue;
  }
  if (!applies) {
    base.applies = false;
    base.reason = "below-threshold";
    base.net = amount;
    if (type.thresholdUnit === "month") {
      base.monthlyTds = 0;
      base.monthlyNet = amount;
      base.annualTds = 0;
      base.annualNet = amount * 12;
    }
    base.answer = 0;
    return base;
  }
  base.applies = true;
  base.taxableBase = type.base === "excess" ? amount - thresholdValue : amount;
  base.tdsExact = tdsRound2(base.taxableBase * rate / 100);
  base.tds = tdsRoundInt(base.tdsExact);
  base.net = amount - base.tds;
  if (type.thresholdUnit === "month") {
    base.monthlyTds = base.tds;
    base.monthlyNet = base.net;
    base.annualTds = base.tds * 12;
    base.annualNet = base.net * 12;
  }
  base.answer = base.tds;
  return base;
}

