// Pregnancy due date calculator (India).
// Naegele's rule: for a regular 28-day cycle the estimated due date
// (EDD) is the first day of the last menstrual period (LMP) plus 280
// days (40 weeks). A longer or shorter cycle shifts the date by the
// difference from 28 days: EDD = LMP + 280 + (cycle - 28) days, and
// conception is estimated at LMP + cycle - 14 days (ovulation about
// 14 days before the next period).
// From a conception date: EDD = conception + 266 days (38 weeks),
// and the derived LMP is conception - 14 days.
// From an IVF embryo transfer: EDD = transfer + 263 days for a day-3
// transfer and + 261 days for a day-5 (blastocyst) transfer — 266 days
// minus the embryo's age in days. The derived LMP is EDD - 280 days
// and conception is estimated at the transfer date minus the embryo's
// age in days.
// Trimesters (weeks from the LMP): first 1-13, second 14-27, third
// 28-40. Milestones from the LMP: first heartbeat about 6 weeks
// (LMP + 42 days), end of the first trimester 13 weeks 6 days
// (LMP + 97 days), anatomy scan window 18-22 weeks (LMP + 126 to
// LMP + 154 days), viability about 24 weeks (LMP + 168 days), full
// term 39 weeks (LMP + 273 days), due date 40 weeks (LMP + 280 days),
// 42 weeks post-term (LMP + 294 days).
// The result is an ESTIMATE, not a medical fact: Naegele's rule
// assumes a regular cycle and ovulation on day 14, and only about 5%
// of babies arrive on the due date. The page states this.
// Conventions (stated on the page):
// - Dates are calendar dates (UTC, YYYY-MM-DD); day counts are exact
//   calendar-day differences, so leap years and year boundaries are
//   handled by the calendar, not by the code.
// - Cycle length 21-35 days (integer); anything outside is rejected.
// - A future LMP / conception / transfer date (after the reference
//   date) is rejected. An LMP more than 42 weeks before the reference
//   date still computes — the due date is in the past and the client
//   shows a gentle "due date has passed" message instead of a result
//   error.
// - Weeks pregnant are whole weeks from the LMP (floor of days / 7);
//   progress is days pregnant / 280, rounded to the nearest whole
//   percent and capped at 100.
export const PDD_MIN_CYCLE = 21;
export const PDD_MAX_CYCLE = 35;
export const PDD_GESTATION_DAYS = 280;
export const PDD_CONCEPTION_DAYS = 266;
export const PDD_IVF_DAY3_DAYS = 263;
export const PDD_IVF_DAY5_DAYS = 261;
export const PDD_POST_TERM_DAYS = 294;
export const PDD_TRIMESTER1_END_DAYS = 97;
export const PDD_TRIMESTER2_START_DAYS = 98;
export const PDD_TRIMESTER2_END_DAYS = 195;
export const PDD_TRIMESTER3_START_DAYS = 196;

export const PDD_KEYS = ["mode", "lmp", "cycle", "conception", "transfer", "transferDay", "ref"];

export function pddParseISO(iso) {
  if (typeof iso !== "string") return null;
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(iso);
  if (!m) return null;
  const d = new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
  if (d.getUTCFullYear() !== +m[1] || d.getUTCMonth() !== +m[2] - 1 || d.getUTCDate() !== +m[3]) return null;
  return d;
}

export function pddISODate(date) {
  const y = date.getUTCFullYear();
  const m = String(date.getUTCMonth() + 1).padStart(2, "0");
  const d = String(date.getUTCDate()).padStart(2, "0");
  return y + "-" + m + "-" + d;
}

export function pddAddDays(iso, days) {
  const d = pddParseISO(iso);
  if (!d) return null;
  return pddISODate(new Date(d.getTime() + days * 86400000));
}

export function pddDiffDays(aISO, bISO) {
  const a = pddParseISO(aISO);
  const b = pddParseISO(bISO);
  if (!a || !b) return null;
  return Math.round((b.getTime() - a.getTime()) / 86400000);
}

export function pddWeekday(iso) {
  const d = pddParseISO(iso);
  if (!d) return null;
  return ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"][d.getUTCDay()];
}

export function pddCompute(input) {
  if (!input || typeof input !== "object" || Array.isArray(input)) return null;
  const keys = Object.keys(input);
  if (keys.length !== PDD_KEYS.length) return null;
  for (const k of PDD_KEYS) {
    if (!Object.prototype.hasOwnProperty.call(input, k)) return null;
  }
  const mode = input.mode;
  if (mode !== "lmp" && mode !== "conception" && mode !== "ivf") return null;
  const ref = pddParseISO(input.ref);
  if (!ref) return null;
  const refISO = input.ref;
  let lmpISO;
  let conceptionISO;
  if (mode === "lmp") {
    if (input.conception !== null || input.transfer !== null || input.transferDay !== null) return null;
    const cycle = input.cycle;
    if (typeof cycle !== "number" || !Number.isInteger(cycle)) return null;
    if (cycle < PDD_MIN_CYCLE || cycle > PDD_MAX_CYCLE) return null;
    const lmp = pddParseISO(input.lmp);
    if (!lmp) return null;
    if (lmp.getTime() > ref.getTime()) return null;
    lmpISO = input.lmp;
    conceptionISO = pddAddDays(lmpISO, cycle - 14);
  } else if (mode === "conception") {
    if (input.lmp !== null || input.cycle !== null || input.transfer !== null || input.transferDay !== null) return null;
    const conc = pddParseISO(input.conception);
    if (!conc) return null;
    if (conc.getTime() > ref.getTime()) return null;
    conceptionISO = input.conception;
    lmpISO = pddAddDays(conceptionISO, -14);
  } else {
    if (input.lmp !== null || input.cycle !== null || input.conception !== null) return null;
    const transfer = pddParseISO(input.transfer);
    if (!transfer) return null;
    if (transfer.getTime() > ref.getTime()) return null;
    const day = input.transferDay;
    if (day !== 3 && day !== 5) return null;
    const add = day === 3 ? PDD_IVF_DAY3_DAYS : PDD_IVF_DAY5_DAYS;
    const eddTmp = pddAddDays(input.transfer, add);
    lmpISO = pddAddDays(eddTmp, -PDD_GESTATION_DAYS);
    conceptionISO = pddAddDays(input.transfer, -day);
  }
  const edd = pddAddDays(lmpISO, PDD_GESTATION_DAYS + (mode === "lmp" ? input.cycle - 28 : 0));
  const daysPregnant = pddDiffDays(lmpISO, refISO);
  const weeks = Math.floor(daysPregnant / 7);
  const days = daysPregnant % 7;
  const trimester = weeks <= 13 ? 1 : (weeks <= 27 ? 2 : 3);
  const pastDue = refISO > edd;
  const progressPct = Math.min(100, Math.round(daysPregnant * 100 / PDD_GESTATION_DAYS));
  const trimesters = [
    { n: 1, start: lmpISO, end: pddAddDays(lmpISO, PDD_TRIMESTER1_END_DAYS) },
    { n: 2, start: pddAddDays(lmpISO, PDD_TRIMESTER2_START_DAYS), end: pddAddDays(lmpISO, PDD_TRIMESTER2_END_DAYS) },
    { n: 3, start: pddAddDays(lmpISO, PDD_TRIMESTER3_START_DAYS), end: edd }
  ];
  const milestones = [
    { id: "heartbeat", label: "First heartbeat can be seen on a scan", iso: pddAddDays(lmpISO, 42), weekday: pddWeekday(pddAddDays(lmpISO, 42)), when: "about 6 weeks" },
    { id: "end-first-trimester", label: "End of the first trimester", iso: pddAddDays(lmpISO, 97), weekday: pddWeekday(pddAddDays(lmpISO, 97)), when: "13 weeks 6 days" },
    { id: "anatomy-opens", label: "Anatomy scan window opens", iso: pddAddDays(lmpISO, 126), weekday: pddWeekday(pddAddDays(lmpISO, 126)), when: "18 weeks" },
    { id: "anatomy-closes", label: "Anatomy scan window closes", iso: pddAddDays(lmpISO, 154), weekday: pddWeekday(pddAddDays(lmpISO, 154)), when: "22 weeks" },
    { id: "viability", label: "Viability — about 24 weeks", iso: pddAddDays(lmpISO, 168), weekday: pddWeekday(pddAddDays(lmpISO, 168)), when: "24 weeks" },
    { id: "full-term", label: "Full term begins", iso: pddAddDays(lmpISO, 273), weekday: pddWeekday(pddAddDays(lmpISO, 273)), when: "39 weeks" },
    { id: "due-date", label: "Estimated due date", iso: edd, weekday: pddWeekday(edd), when: "40 weeks" },
    { id: "post-term", label: "42 weeks — post-term", iso: pddAddDays(lmpISO, 294), weekday: pddWeekday(pddAddDays(lmpISO, 294)), when: "42 weeks" }
  ];
  return {
    mode: mode,
    edd: edd,
    eddWeekday: pddWeekday(edd),
    lmp: lmpISO,
    conception: conceptionISO,
    weeks: weeks,
    days: days,
    daysPregnant: daysPregnant,
    progressPct: progressPct,
    trimester: trimester,
    pastDue: pastDue,
    trimesters: trimesters,
    milestones: milestones
  };
}

