                <div>
                  <strong id="box2-val">${inr2(sample.totalReturns)}</strong>
                  <small id="box2-label">RETURNS EARNED</small>
                </div>
                <div>
                  <strong id="box3-val">${inr2(sample.finalBalance)}</strong>
