// Ovulation calculator (India).
// Calendar method: ovulation is estimated at cycle length minus the
// luteal phase, counted from the first day of the last menstrual
// period (LMP). Ovulation day = LMP + (cycle - luteal) days; the
// next period is LMP + cycle days.
// The fertile window is 6 days: the 5 days before ovulation plus
// ovulation day itself (Wilcox et al., NEJM 1995; NHS "Trying to get
// pregnant"; ACOG FAQ024; Cleveland Clinic "Ovulation"). Sperm can
// survive up to 5 days, so the days before ovulation are fertile;
// the egg lives only 12-24 hours after release, so the day after
// ovulation is NOT in the window. Several competitor calculators
// publish a 7-day window (5 days before + ovulation day + 1 day
// after) — this tool does NOT follow that variant, and the page
// says so.
// Due date if conception occurs this cycle = ovulation + 266 days
// (38 weeks from conception). Earliest pregnancy-test day = the
// expected next period (a test on that day is the stated
// convention; earlier testing can miss a pregnancy).
// The result is an ESTIMATE, not a medical fact: the calendar
// method assumes a regular cycle and a stable luteal phase. It is
// unreliable for irregular cycles, PCOS, thyroid conditions and
// recent contraceptive use, and must NOT be used as contraception.
// The page states this.
// Conventions (stated on the page):
// - Dates are calendar dates (UTC, YYYY-MM-DD); day counts are exact
//   calendar-day differences, so leap years and year boundaries are
//   handled by the calendar, not by the code.
// - Cycle length 21-35 days (integer); luteal phase 10-16 days
//   (integer, default 14); anything outside is rejected.
// - A future LMP (after the reference date) is rejected. An LMP
//   whose ovulation has already passed still computes — the client
//   shows a gentle "your ovulation has passed" message instead of
//   a result error.
export const OVL_MIN_CYCLE = 21;
export const OVL_MAX_CYCLE = 35;
export const OVL_MIN_LUTEAL = 10;
export const OVL_MAX_LUTEAL = 16;
export const OVL_DEFAULT_LUTEAL = 14;
export const OVL_FERTILE_DAYS = 6;
export const OVL_CONCEPTION_DAYS = 266;

export const OVL_KEYS = ["lmp", "cycle", "luteal", "ref"];

export function ovlParseISO(iso) {
  if (typeof iso !== "string") return null;
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(iso);
  if (!m) return null;
  const d = new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
  if (d.getUTCFullYear() !== +m[1] || d.getUTCMonth() !== +m[2] - 1 || d.getUTCDate() !== +m[3]) return null;
  return d;
}

export function ovlISODate(date) {
  const y = date.getUTCFullYear();
  const m = String(date.getUTCMonth() + 1).padStart(2, "0");
  const d = String(date.getUTCDate()).padStart(2, "0");
  return y + "-" + m + "-" + d;
}

export function ovlAddDays(iso, days) {
  const d = ovlParseISO(iso);
  if (!d) return null;
  return ovlISODate(new Date(d.getTime() + days * 86400000));
}

export function ovlDiffDays(aISO, bISO) {
  const a = ovlParseISO(aISO);
  const b = ovlParseISO(bISO);
  if (!a || !b) return null;
  return Math.round((b.getTime() - a.getTime()) / 86400000);
}

export function ovlWeekday(iso) {
  const d = ovlParseISO(iso);
  if (!d) return null;
  return ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"][d.getUTCDay()];
}

export function ovlCompute(input) {
  if (!input || typeof input !== "object" || Array.isArray(input)) return null;
  const keys = Object.keys(input);
  if (keys.length !== OVL_KEYS.length) return null;
  for (const k of OVL_KEYS) {
    if (!Object.prototype.hasOwnProperty.call(input, k)) return null;
  }
  const ref = ovlParseISO(input.ref);
  if (!ref) return null;
  const refISO = input.ref;
  const cycle = input.cycle;
  if (typeof cycle !== "number" || !Number.isInteger(cycle)) return null;
  if (cycle < OVL_MIN_CYCLE || cycle > OVL_MAX_CYCLE) return null;
  const luteal = input.luteal;
  if (typeof luteal !== "number" || !Number.isInteger(luteal)) return null;
  if (luteal < OVL_MIN_LUTEAL || luteal > OVL_MAX_LUTEAL) return null;
  const lmp = ovlParseISO(input.lmp);
  if (!lmp) return null;
  if (lmp.getTime() > ref.getTime()) return null;
  const lmpISO = input.lmp;
  const cycleDay = cycle - luteal;
  const ovulation = ovlAddDays(lmpISO, cycleDay);
  const fertileStart = ovlAddDays(ovulation, -(OVL_FERTILE_DAYS - 1));
  const fertileEnd = ovulation;
  const nextPeriod = ovlAddDays(lmpISO, cycle);
  const dueDate = ovlAddDays(ovulation, OVL_CONCEPTION_DAYS);
  const testDate = nextPeriod;
  const daysToOvulation = ovlDiffDays(refISO, ovulation);
  const ovulationPassed = refISO > ovulation;
  const fertileDays = [];
  for (let i = 0; i < OVL_FERTILE_DAYS; i++) {
    const iso = ovlAddDays(fertileStart, i);
    fertileDays.push({
      n: i + 1,
      iso: iso,
      weekday: ovlWeekday(iso),
      dayInCycle: cycleDay - (OVL_FERTILE_DAYS - 1) + i,
      label: i === OVL_FERTILE_DAYS - 1 ? "Ovulation day" : "Fertile day " + (i + 1)
    });
  }
  return {
    lmp: lmpISO,
    cycle: cycle,
    luteal: luteal,
    cycleDay: cycleDay,
    ovulation: ovulation,
    ovulationWeekday: ovlWeekday(ovulation),
    fertileStart: fertileStart,
    fertileEnd: fertileEnd,
    fertileDays: fertileDays,
    nextPeriod: nextPeriod,
    nextPeriodWeekday: ovlWeekday(nextPeriod),
    dueDate: dueDate,
    dueDateWeekday: ovlWeekday(dueDate),
    testDate: testDate,
    testDateWeekday: ovlWeekday(testDate),
    daysToOvulation: daysToOvulation,
    ovulationPassed: ovulationPassed
  };
}

