export const STAMP_STATE_IDS = ["maharashtra-mumbai", "maharashtra-pune", "delhi", "karnataka", "tamil-nadu", "uttar-pradesh", "gujarat", "punjab", "madhya-pradesh", "telangana"];

export function stampRound2(x) {
  return Math.round(x * 100) / 100;
}

export function stampRound1(x) {
  return Math.round(x * 10) / 10;
}

export function stampCompute(input) {
  if (!input || typeof input !== "object" || Array.isArray(input)) return null;
  const keys = Object.keys(input);
  if (keys.length !== STAMP_KEYS.length) return null;
  for (const k of STAMP_KEYS) {
    if (!Object.prototype.hasOwnProperty.call(input, k)) return null;
  }
  const stateId = input.state;
  const buyer = input.buyer;
  const value = input.value;
  if (typeof stateId !== "string" || STAMP_STATE_IDS.indexOf(stateId) === -1) return null;
  if (buyer !== "male" && buyer !== "female" && buyer !== "joint") return null;
  if (typeof value !== "number" || !Number.isFinite(value) || value <= 0 || value > STAMP_MAX_VALUE) return null;
  const st = STAMP_STATES[stateId];
  let baseRate;
  if (st.slabs !== null) {
    baseRate = null;
    for (const slab of st.slabs) {
      if (slab.max === null || value <= slab.max) { baseRate = slab.rate; break; }
    }
    if (baseRate === null) return null;
  } else {
    baseRate = st.duty[buyer];
    if (buyer === "female" && st.femaleMax !== null && value > st.femaleMax) baseRate = st.femaleAbove;
  }
  const baseDuty = stampRound2(value * baseRate / 100);
  const surcharge = stampRound2(baseDuty * st.cessOnDuty / 100) + stampRound2(value * st.cessOnValue / 100);
  const stampDuty = stampRound2(baseDuty + surcharge);
  let regPct = st.regPct;
  if (st.regZeroFemale && buyer === "female") regPct = 0;
  else if (buyer === "female" && st.regFemalePct !== null && value <= st.regFemaleMax) regPct = st.regFemalePct;
  const regRaw = stampRound2(value * regPct / 100);
  const regCapped = st.regCap !== null && regRaw > st.regCap;
  const regFee = stampRound2((regCapped ? st.regCap : regRaw) + st.regExtra);
  const total = stampRound2(stampDuty + regFee);
  return {
    state: stateId,
    buyer: buyer,
    value: value,
    baseRate: baseRate,
    baseDuty: baseDuty,
    cessOnDuty: st.cessOnDuty,
    cessOnValue: st.cessOnValue,
    surcharge: surcharge,
    stampDuty: stampDuty,
    stampPct: stampRound2(stampDuty / value * 100),
    regPct: regPct,
    regFee: regFee,
    regCapped: regCapped,
    total: total,
    totalPct: stampRound1(total / value * 100)
  };
}

