    slabRows = [{ from: 0, to: null, units: units, rate: 5.8, amount: energy }];
    fixed = ebcRound2(150 * load);
    fixedNote = "Rs 150 per kW on " + load + " kW sanctioned load";
    const tax = ebcRound2(0.09 * energy);
    const pg = ebcRound2(0.35 * units);
    dutyLines = [
      { label: "Electricity tax 9% on the energy charge only", amount: tax },
      { label: "P&G surcharge Rs 0.35 per unit", amount: pg }
    ];
    if (fuelValue !== null && fuelValue !== undefined) {
      fuelPerUnit("FPPCA Rs " + fuelValue + " per unit");
    }
    subtotal = ebcRound2(energy + fixed + tax + pg + fuel);
    if (subsidyOn) {
      subsidyAmount = ebcRound2(Math.min(units, 200) * 5.8);
      subsidyNote = "Gruha Jyoti: the energy charge on the first 200 units is paid by the government - fixed charge, tax and P&G stay payable.";
    } else {
      subsidyNote = "Gruha Jyoti not applied - registered households get up to 200 units free.";
    }
    total = ebcRound2(subtotal - subsidyAmount);
