      schedule: schedule,
      scheduleLabel: schedLabel,
      stateLabel: stateLabel,
      period: period,
      periodLabel: period,
      units: units,
      unitsSource: unitsSource,
      prevReading: input.prevReading,
      currReading: input.currReading,
      mf: input.mf,
      loadKw: load,
      phase: phase,
      subsidy: subsidyOn,
      fuelValue: fuelValue,
      slabRows: slabRows,
      energy: energy,
      fixed: fixed,
      fixedNote: fixedNote,
      wheeling: wheeling,
      fuel: fuel,
      fuelLabel: fuelLabel,
      dutyLines: dutyLines,
      meterRent: meterRent,
      subsidyAmount: subsidyAmount,
      subsidyNote: subsidyNote,
      subtotal: subtotal,
      total: total,
      avgPerUnit: avg,
      freeUnits: freeUnits,
      notes: notes,
      category: category
