// Brick Calculator.
// Bricks, cement and sand for a wall, by the volume method — worked out
// in the browser.
// - Wall volume = net face area (length x height, less openings) x
//   thickness. In feet mode the thickness is the exact inch value
//   (9 in = 228.6 mm); in metres mode it is the nominal 230 mm.
//   (NineClip's worked examples use exact inches: 10x10 ft x 9 in =
//   75 cft = 2.12 m3; 12x9 ft less a 21 sq ft door x 4.5 in = 32.6 cft
//   = 0.92 m3.)
// - Brick + joint module = (length + 10 mm) x (width + 10 mm) x
//   (height + 10 mm). Bricks exact = wall volume / module volume.
// - Bricks to buy = ceil(bricks exact x (1 + wastage / 100)). The
//   wastage % applies to BRICKS ONLY (RupeesCalc's convention).
//   CivilSite adds a separate 5% mortar allowance and NineClip adds
//   3% on cement and 10% on sand — this page does not, and the
//   difference is stated on the page with their after-allowance figures.
// - Wet mortar = wall volume - bricks exact x solid brick volume.
// - Dry mortar = wet mortar x 1.33 (the voids/shrinkage factor all
//   three sources use).
// - Cement volume = dry mortar / (1 + sand parts); cement bags exact =
//   cement volume / 0.0347 m3 per 50 kg bag; bags to buy = ceil(bags).
// - Sand volume = dry mortar x sand parts / (1 + sand parts); sand cft
//   = sand m3 x 35.3147.
// - Cost: bricks to buy x brick rate + bags to buy x cement rate +
//   sand cft x sand rate (a rate of 0 means "not entered" — that line
//   is left out and the total covers only the entered lines).
// - Brick sizes (mm): traditional 230x115x75 (392/m3), traditional
//   230x110x70 (434/m3), modular 190x90x90 (500/m3), jumbo 300x150x100
//   (183/m3). 1 m3 = 35.3147 cft; 1 m2 = 10.7639 sq ft.
// - Display rounding: bricks whole, wall volume 2dp m3 / 1dp cft,
//   mortar 2dp m3, cement bags 2dp, sand 2dp m3 / 1dp cft, money whole
//   rupees with Indian grouping. All rounding is round half up with a
//   1e-9 nudge, matching the independent Python model exactly.
// - Quantities are estimates for planning, not a bill of quantities.
//   Brick sizes vary by kiln and region — measure a sample from the
//   batch you buy. Prices are user-entered or clearly-labelled
//   indicative 2026 ranges, never live quotes.
export const BRICK_KEYS = ["unit", "length", "height", "openings", "thickness", "brick", "mix", "wastage", "brickRate", "cementRate", "sandRate"];
export const BRICK_UNITS = ["ft", "m"];
export const BRICK_THICKNESSES = ["115", "230", "345"];
export const BRICK_THICK_MM = { "115": 115, "230": 230, "345": 345 };
export const BRICK_THICK_IN = { "115": 4.5, "230": 9.0, "345": 13.5 };
export const BRICK_THICK_LABELS = { "115": "4.5-inch (115 mm) half-brick", "230": "9-inch (230 mm) full-brick", "345": "13.5-inch (345 mm) one-and-a-half-brick" };
export const BRICK_SIZES = ["trad115", "trad110", "modular", "jumbo"];
export const BRICK_DIMS_MM = {
  "trad115": [230, 115, 75],
  "trad110": [230, 110, 70],
  "modular": [190, 90, 90],
  "jumbo": [300, 150, 100],
};
export const BRICK_LABELS = {
  "trad115": "Traditional 230 × 115 × 75 mm",
  "trad110": "Traditional 230 × 110 × 70 mm",
  "modular": "Modular 190 × 90 × 90 mm (IS 1077)",
  "jumbo": "Jumbo 300 × 150 × 100 mm",
};
export const BRICK_MIXES = [4, 5, 6];
export const BRICK_JOINT_M = 0.01;
export const BRICK_DRY_FACTOR = 1.33;
export const BRICK_BAG_VOL_M3 = 0.0347;
export const BRICK_CFT_PER_M3 = 35.3147;
export const BRICK_SQFT_PER_M2 = 10.7639;
export const BRICK_FT_TO_M = 0.3048;
export const BRICK_SQFT_TO_M2 = 0.092903;
export const BRICK_WASTAGE_MIN = 0;
export const BRICK_WASTAGE_MAX = 20;
export const BRICK_RATE_MAX = 100;
export const BRICK_CEMENT_RATE_MAX = 1000;
export const BRICK_SAND_RATE_MAX = 500;
export function brickFmt0(x) {
  return String(Math.round(x + 1e-9));
}
export function brickFmt1(x) {
  return (Math.round(x * 10 + 1e-9) / 10).toFixed(1);
}
export function brickFmt2(x) {
  return (Math.round(x * 100 + 1e-9) / 100).toFixed(2);
}
export function brickFmtMod(x) {
  return String(parseFloat((Math.round(x * 1e6 + 1e-9) / 1e6).toFixed(6)));
}
export function brickFmtNum(x) {
  return String(x);
}
export function brickFmtINR(x) {
  const n = Math.round(x + 1e-9);
  const s = String(n);
  if (s.length <= 3) return s;
  const last3 = s.slice(-3);
  let rest = s.slice(0, -3);
  const parts = [];
  while (rest.length > 2) { parts.unshift(rest.slice(-2)); rest = rest.slice(0, -2); }
  if (rest) parts.unshift(rest);
  return parts.join(",") + "," + last3;
}
function brickIsNum(v) {
  return typeof v === "number" && Number.isFinite(v);
}
export function brickValid(input) {
  if (!input || typeof input !== "object" || Array.isArray(input)) return false;
  const keys = Object.keys(input);
  if (keys.length !== BRICK_KEYS.length) return false;
  for (const k of BRICK_KEYS) if (!keys.includes(k)) return false;
  if (!BRICK_UNITS.includes(input.unit)) return false;
  const u = input.unit;
  if (!brickIsNum(input.length)) return false;
  if (u === "ft") {
    if (input.length < 0.5 || input.length > 500) return false;
  } else if (input.length < 0.15 || input.length > 200) return false;
  if (!brickIsNum(input.height)) return false;
  if (u === "ft") {
    if (input.height < 0.5 || input.height > 100) return false;
  } else if (input.height < 0.15 || input.height > 30) return false;
  if (!brickIsNum(input.openings) || input.openings < 0) return false;
  if (input.openings >= input.length * input.height) return false;
  if (!BRICK_THICKNESSES.includes(input.thickness)) return false;
  if (!BRICK_SIZES.includes(input.brick)) return false;
  if (!BRICK_MIXES.includes(input.mix)) return false;
  if (!brickIsNum(input.wastage) || input.wastage < BRICK_WASTAGE_MIN || input.wastage > BRICK_WASTAGE_MAX) return false;
  if (!brickIsNum(input.brickRate) || input.brickRate < 0 || input.brickRate > BRICK_RATE_MAX) return false;
  if (!brickIsNum(input.cementRate) || input.cementRate < 0 || input.cementRate > BRICK_CEMENT_RATE_MAX) return false;
  if (!brickIsNum(input.sandRate) || input.sandRate < 0 || input.sandRate > BRICK_SAND_RATE_MAX) return false;
  return true;
}
export function brickCompute(input) {
  if (!brickValid(input)) return null;
  const u = input.unit;
  const length = input.length;
  const height = input.height;
  const openings = input.openings;
  const thick = input.thickness;
  const brick = input.brick;
  const mix = input.mix;
  const wastage = input.wastage;
  const brickRate = input.brickRate;
  const cementRate = input.cementRate;
  const sandRate = input.sandRate;
  const lengthM = u === "ft" ? length * BRICK_FT_TO_M : length;
  const heightM = u === "ft" ? height * BRICK_FT_TO_M : height;
  const grossAreaM2 = lengthM * heightM;
  const openingsM2 = u === "ft" ? openings * BRICK_SQFT_TO_M2 : openings;
  const netAreaM2 = grossAreaM2 - openingsM2;
  const thicknessM = u === "ft" ? BRICK_THICK_IN[thick] * 0.0254 : BRICK_THICK_MM[thick] / 1000;
  const thicknessLabel = u === "ft"
    ? brickFmtNum(BRICK_THICK_IN[thick]) + " in (" + brickFmt1(BRICK_THICK_IN[thick] * 25.4) + " mm)"
    : BRICK_THICK_MM[thick] + " mm";
  const wallVolM3 = netAreaM2 * thicknessM;
  const wallVolCft = wallVolM3 * BRICK_CFT_PER_M3;
  const dims = BRICK_DIMS_MM[brick];
  const bl = dims[0];
  const bw = dims[1];
  const bh = dims[2];
  const blM = bl / 1000;
  const bwM = bw / 1000;
  const bhM = bh / 1000;
  const moduleVol = (blM + BRICK_JOINT_M) * (bwM + BRICK_JOINT_M) * (bhM + BRICK_JOINT_M);
  const brickVol = blM * bwM * bhM;
  const bricksExact = wallVolM3 / moduleVol;
  const bricksToBuy = Math.ceil(bricksExact * (1 + wastage / 100) - 1e-9);
  const bricksPerM2 = bricksExact / netAreaM2;
  const bricksPerM3 = 1 / moduleVol;
  const netAreaSqFt = netAreaM2 * BRICK_SQFT_PER_M2;
  const bricksPerSqFt = bricksExact / netAreaSqFt;
  const bricksPerSqFtToBuy = bricksToBuy / netAreaSqFt;
  const wetMortar = wallVolM3 - bricksExact * brickVol;
  const dryMortar = wetMortar * BRICK_DRY_FACTOR;
  const cementVol = dryMortar / (1 + mix);
  const cementBagsExact = cementVol / BRICK_BAG_VOL_M3;
  const cementBagsToBuy = Math.ceil(cementBagsExact - 1e-9);
  const sandVol = dryMortar * mix / (1 + mix);
  const sandCft = sandVol * BRICK_CFT_PER_M3;
  const cementBagsPer1000 = (1000 * moduleVol - 1000 * brickVol) * BRICK_DRY_FACTOR / (1 + mix) / BRICK_BAG_VOL_M3;
  const brickCost = brickRate > 0 ? bricksToBuy * brickRate : 0;
  const cementCost = cementRate > 0 ? cementBagsToBuy * cementRate : 0;
  const sandCost = sandRate > 0 ? Math.round(sandCft * sandRate + 1e-9) : 0;
  const totalCost = brickCost + cementCost + sandCost;
  const hasPrices = brickRate > 0 || cementRate > 0 || sandRate > 0;
  const unitWord = u === "ft" ? "ft" : "m";
  const areaWord = u === "ft" ? "sq ft" : "m²";
  const verdict = "Order " + brickFmtINR(bricksToBuy) + " bricks, " + brickFmt0(cementBagsToBuy) + " bags of cement and " + brickFmt1(sandCft) + " cft of sand.";
  const verdictLabel = "Order " + brickFmtINR(bricksToBuy) + " bricks, " + brickFmt0(cementBagsToBuy) + " bags of cement and " + brickFmt1(sandCft) + " cft of sand for this wall.";
  const n1 = "Wall volume " + brickFmt2(wallVolM3) + " m³ (" + brickFmt1(wallVolCft) + " cft) = " + brickFmtNum(length) + " × " + brickFmtNum(height) + " " + unitWord + " wall, " + thicknessLabel + " thick, less " + brickFmtNum(openings) + " " + areaWord + " of openings.";
  const n2 = "Bricks " + brickFmtINR(bricksExact) + " = " + brickFmt2(wallVolM3) + " m³ of wall ÷ " + brickFmtMod(moduleVol) + " m³ per brick with joint (" + bl + " × " + bw + " × " + bh + " mm brick + 10 mm joint). Order " + brickFmtINR(bricksToBuy) + " with " + brickFmtNum(wastage) + "% wastage.";
  const n3 = "Wet mortar " + brickFmt2(wetMortar) + " m³ = " + brickFmt2(wallVolM3) + " m³ of wall − " + brickFmt2(bricksExact * brickVol) + " m³ of solid brick. Dry mortar " + brickFmt2(dryMortar) + " m³ = " + brickFmt2(wetMortar) + " × 1.33.";
  const n4 = "Cement " + brickFmt2(cementBagsExact) + " bags = " + brickFmt2(dryMortar) + " m³ dry ÷ " + (1 + mix) + " parts ÷ 0.0347 m³ a bag — buy " + brickFmt0(cementBagsToBuy) + ". Sand " + brickFmt2(sandVol) + " m³ (" + brickFmt1(sandCft) + " cft) = " + brickFmt2(dryMortar) + " m³ × " + mix + "/" + (1 + mix) + ".";
  let n5;
  if (hasPrices) {
    const parts = [];
    if (brickRate > 0) parts.push(brickFmtINR(bricksToBuy) + " bricks × ₹" + brickFmtINR(brickRate));
    if (cementRate > 0) parts.push(brickFmt0(cementBagsToBuy) + " bags × ₹" + brickFmtINR(cementRate));
    if (sandRate > 0) parts.push(brickFmt1(sandCft) + " cft × ₹" + brickFmtINR(sandRate));
    n5 = "Cost ₹" + brickFmtINR(totalCost) + " = " + parts.join(" + ") + ".";
  } else {
    n5 = "No prices entered — add your local brick, cement and sand rates to see the cost. The quantities above do not need prices.";
  }
  const n6 = "Quantities are estimates for planning, not a bill of quantities. Brick sizes vary by kiln and region — measure a sample from the batch you buy.";
  const notes = [n1, n2, n3, n4, n5, n6];
  return {
    unit: u,
    length: length,
    height: height,
    openings: openings,
    thickness: thick,
    brick: brick,
    mix: mix,
    wastage: wastage,
    brickRate: brickRate,
    cementRate: cementRate,
    sandRate: sandRate,
    lengthM: lengthM,
    heightM: heightM,
    grossAreaM2: grossAreaM2,
    openingsM2: openingsM2,
    netAreaM2: netAreaM2,
    thicknessM: thicknessM,
    thicknessLabel: thicknessLabel,
    wallVolM3: wallVolM3,
    wallVolCft: wallVolCft,
    moduleVolM3: moduleVol,
    brickVolM3: brickVol,
    bricksExact: bricksExact,
    bricksToBuy: bricksToBuy,
    bricksPerM2: bricksPerM2,
    bricksPerM3: bricksPerM3,
    bricksPerSqFt: bricksPerSqFt,
    bricksPerSqFtToBuy: bricksPerSqFtToBuy,
    wetMortarM3: wetMortar,
    dryMortarM3: dryMortar,
    cementVolM3: cementVol,
    cementBagsExact: cementBagsExact,
    cementBagsToBuy: cementBagsToBuy,
    sandVolM3: sandVol,
    sandCft: sandCft,
    cementBagsPer1000: cementBagsPer1000,
    brickCost: brickCost,
    cementCost: cementCost,
    sandCost: sandCost,
    totalCost: totalCost,
    hasPrices: hasPrices,
    brickLabel: BRICK_LABELS[brick],
    thicknessLabelLong: BRICK_THICK_LABELS[thick],
    verdict: verdict,
    verdictLabel: verdictLabel,
    notes: notes,
  };
}

