// Cement Calculator.
// Cement bags, sand, aggregate and water for concrete, plaster and
// brickwork mortar — worked out in the browser.
// - Concrete: wet volume = length x width x thickness (metres, or feet
//   with thickness in inches). Dry volume = wet x 1.54. The nominal mix
//   splits the dry volume by parts: M5 1:5:10, M7.5 1:4:8, M10 1:3:6,
//   M15 1:2:4, M20 1:1.5:3, M25 1:1:2 (IS 456:2000 Table 9 — M5 is
//   1:5:10, NOT 1:4:8; TheCivilStudies' table gives 2.8 bags/m3 for M5,
//   which only 1:5:10 reproduces). Cement = dry x cement parts / total
//   parts; cement kg = cement volume x 1,440 kg/m3; bags = cement volume
//   / 0.0347 m3 (one 50 kg bag). Sand and aggregate take their parts of
//   the dry volume (1,600 kg/m3 each). Water = cement kg x 0.5 (w/c 0.5,
//   indicative).
// - Plaster: wet mortar = wall area x thickness (6/12/15/20 mm). Dry
//   mortar = wet x 1.33. Cement = dry / (1 + sand parts); sand = dry x
//   sand parts / (1 + sand parts). NineClip: 100 sq ft at 12 mm, 1:6 =
//   0.61 bags — reproduces exactly.
// - Brickwork: modular bricks 190 x 90 x 90 mm with a 10 mm joint
//   (module 0.0020 m3, solid brick 0.001539 m3 — the same convention as
//   the site's Brick Calculator). Wall volume = area x thickness (4.5 or
//   9 in) or bricks x 0.0020 m3. Wet mortar = wall volume - solid brick
//   volume (0.2305 m3 of mortar per m3 of brickwork). Dry mortar = wet x
//   1.33; cement and sand as plaster.
// - Wastage (default 3%, 0-15%) is added to the CEMENT BAGS ONLY: bags
//   with wastage = bags exact x (1 + wastage/100); bags to buy = ceil
//   (bags with wastage). Sand, aggregate and water are shown at the
//   theoretical quantity. Cost = bags to buy x the visitor's own rate
//   per bag (0 = not entered). NO fixed cement price is printed anywhere.
// - IS 456:2000 permits nominal mixes only up to M20; M25 and above need
//   a design mix to IS 10262:2019 — the M25 1:1:2 figures (11.09 bags/m3)
//   are nominal site practice, not code, and a design mix usually needs
//   only about 7-8 bags/m3.
// - Display rounding: bags exact 2dp, bags to buy integer, volumes 2dp
//   m3 / 1dp cft, kg and water 0dp, costs whole rupees with Indian
//   grouping. All rounding is round half up with a 1e-9 nudge, matching
//   the independent Python model exactly.
// - Quantities are estimates for ordering, not a bill of quantities.
//   Sand bulking and moisture are not modelled; steel, formwork, labour
//   and curing are extra.
export const CEMENT_KEYS = ["mode", "unit", "length", "width", "thickness", "grade", "area", "plasterThick", "mortarMix", "wallThick", "bricks", "wastage", "rate"];
export const CEMENT_MODES = ["concrete", "plaster", "brickwork"];
export const CEMENT_MODE_LABELS = { "concrete": "Concrete", "plaster": "Plaster", "brickwork": "Brickwork mortar" };
export const CEMENT_UNITS = ["m", "ft"];
export const CEMENT_GRADES = ["M5", "M7.5", "M10", "M15", "M20", "M25"];
export const CEMENT_MIX = {
  "M5": [1, 5, 10],
  "M7.5": [1, 4, 8],
  "M10": [1, 3, 6],
  "M15": [1, 2, 4],
  "M20": [1, 1.5, 3],
  "M25": [1, 1, 2],
};
export const CEMENT_PLASTER_THICKS = [6, 12, 15, 20];
export const CEMENT_MORTAR_MIXES = ["1:3", "1:4", "1:5", "1:6"];
export const CEMENT_BRICKWORK_MIXES = ["1:4", "1:5", "1:6"];
export const CEMENT_WALL_THICKS = [4.5, 9];
export const CEMENT_DRY_FACTOR_CONCRETE = 1.54;
export const CEMENT_DRY_FACTOR_MORTAR = 1.33;
export const CEMENT_DENSITY = 1440;
export const CEMENT_BAG_KG = 50;
export const CEMENT_BAG_VOL_M3 = 0.0347;
export const CEMENT_SAND_DENSITY = 1600;
export const CEMENT_AGG_DENSITY = 1600;
export const CEMENT_WC_RATIO = 0.5;
export const CEMENT_M3_TO_CFT = 35.3147;
export const CEMENT_FT_TO_M = 0.3048;
export const CEMENT_IN_TO_M = 0.0254;
export const CEMENT_SQFT_TO_M2 = 0.092903;
export const CEMENT_M2_TO_SQFT = 10.7639;
export const CEMENT_BRICK_MODULE_VOL = 0.002;
export const CEMENT_BRICK_SOLID_VOL = 0.001539;
export const CEMENT_M_LEN_MIN = 0.05;
export const CEMENT_M_LEN_MAX = 100;
export const CEMENT_M_THICK_MIN = 0.01;
export const CEMENT_M_THICK_MAX = 10;
export const CEMENT_FT_LEN_MIN = 0.2;
export const CEMENT_FT_LEN_MAX = 330;
export const CEMENT_FT_THICK_MIN = 0.5;
export const CEMENT_FT_THICK_MAX = 400;
export const CEMENT_M_AREA_MIN = 0.1;
export const CEMENT_M_AREA_MAX = 100000;
export const CEMENT_FT_AREA_MIN = 1;
export const CEMENT_FT_AREA_MAX = 1000000;
export const CEMENT_BRICKS_MIN = 0;
export const CEMENT_BRICKS_MAX = 1000000;
export const CEMENT_WASTAGE_MIN = 0;
export const CEMENT_WASTAGE_MAX = 15;
export const CEMENT_RATE_MAX = 2000;
export function cementFmt0(x) {
  return String(Math.round(x + 1e-9));
}
export function cementFmt1(x) {
  return (Math.round(x * 10 + 1e-9) / 10).toFixed(1);
}
export function cementFmt2(x) {
  return (Math.round(x * 100 + 1e-9) / 100).toFixed(2);
}
export function cementFmt3(x) {
  return (Math.round(x * 1000 + 1e-9) / 1000).toFixed(3);
}
export function cementFmtNum(x) {
  return String(x);
}
export function cementFmtINR(x) {
  const n = Math.round(x + 1e-9);
  const s = String(n);
  if (s.length <= 3) return s;
  const last3 = s.slice(-3);
  let rest = s.slice(0, -3);
  const parts = [];
  while (rest.length > 2) { parts.unshift(rest.slice(-2)); rest = rest.slice(0, -2); }
  if (rest) parts.unshift(rest);
  return parts.join(",") + "," + last3;
}
function cementIsNum(v) {
  return typeof v === "number" && Number.isFinite(v);
}
export function cementValid(input) {
  if (!input || typeof input !== "object" || Array.isArray(input)) return false;
  const keys = Object.keys(input);
  if (keys.length !== CEMENT_KEYS.length) return false;
  for (const k of CEMENT_KEYS) if (!keys.includes(k)) return false;
  if (!CEMENT_MODES.includes(input.mode)) return false;
  if (!CEMENT_UNITS.includes(input.unit)) return false;
  if (!CEMENT_GRADES.includes(input.grade)) return false;
  const u = input.unit;
  if (!cementIsNum(input.length)) return false;
  if (u === "m") {
    if (input.length < CEMENT_M_LEN_MIN || input.length > CEMENT_M_LEN_MAX) return false;
  } else if (input.length < CEMENT_FT_LEN_MIN || input.length > CEMENT_FT_LEN_MAX) return false;
  if (!cementIsNum(input.width)) return false;
  if (u === "m") {
    if (input.width < CEMENT_M_LEN_MIN || input.width > CEMENT_M_LEN_MAX) return false;
  } else if (input.width < CEMENT_FT_LEN_MIN || input.width > CEMENT_FT_LEN_MAX) return false;
  if (!cementIsNum(input.thickness)) return false;
  if (u === "m") {
    if (input.thickness < CEMENT_M_THICK_MIN || input.thickness > CEMENT_M_THICK_MAX) return false;
  } else if (input.thickness < CEMENT_FT_THICK_MIN || input.thickness > CEMENT_FT_THICK_MAX) return false;
  if (!cementIsNum(input.area)) return false;
  if (u === "m") {
    if (input.area < CEMENT_M_AREA_MIN || input.area > CEMENT_M_AREA_MAX) return false;
  } else if (input.area < CEMENT_FT_AREA_MIN || input.area > CEMENT_FT_AREA_MAX) return false;
  if (!CEMENT_PLASTER_THICKS.includes(input.plasterThick)) return false;
  if (!CEMENT_MORTAR_MIXES.includes(input.mortarMix)) return false;
  if (input.mode === "brickwork" && !CEMENT_BRICKWORK_MIXES.includes(input.mortarMix)) return false;
  if (!CEMENT_WALL_THICKS.includes(input.wallThick)) return false;
  if (!cementIsNum(input.bricks) || !Number.isInteger(input.bricks) || input.bricks < CEMENT_BRICKS_MIN || input.bricks > CEMENT_BRICKS_MAX) return false;
  if (!cementIsNum(input.wastage) || input.wastage < CEMENT_WASTAGE_MIN || input.wastage > CEMENT_WASTAGE_MAX) return false;
  if (!cementIsNum(input.rate) || input.rate < 0 || input.rate > CEMENT_RATE_MAX) return false;
  return true;
}
export function cementCompute(input) {
  if (!cementValid(input)) return null;
  const mode = input.mode;
  const u = input.unit;
  const wastage = input.wastage;
  const rate = input.rate;
  const sp = parseInt(input.mortarMix.split(":")[1], 10);
  let wetM3 = 0;
  let wetCft = 0;
  let dryM3 = 0;
  let aggVol = 0;
  let aggCft = 0;
  let aggKg = 0;
  let waterL = 0;
  let bagsPerM3 = 0;
  let areaM2 = 0;
  let areaSqFt = 0;
  let wallVol = 0;
  let wallVolCft = 0;
  let wetMortar = 0;
  let dryMortar = 0;
  let bricksExact = 0;
  let bagsPer100 = 0;
  let cementVol;
  let sandVol;
  let mixRatio;
  let mixLabel;
  if (mode === "concrete") {
    const mix = CEMENT_MIX[input.grade];
    const c = mix[0];
    const s = mix[1];
    const a = mix[2];
    const parts = c + s + a;
    let lm;
    let wm;
    let dm;
    if (u === "m") {
      lm = input.length;
      wm = input.width;
      dm = input.thickness;
    } else {
      lm = input.length * CEMENT_FT_TO_M;
      wm = input.width * CEMENT_FT_TO_M;
      dm = input.thickness * CEMENT_IN_TO_M;
    }
    wetM3 = lm * wm * dm;
    wetCft = wetM3 * CEMENT_M3_TO_CFT;
    dryM3 = wetM3 * CEMENT_DRY_FACTOR_CONCRETE;
    cementVol = dryM3 * c / parts;
    sandVol = dryM3 * s / parts;
    aggVol = dryM3 * a / parts;
    aggCft = aggVol * CEMENT_M3_TO_CFT;
    aggKg = aggVol * CEMENT_AGG_DENSITY;
    mixRatio = cementFmtNum(c) + ":" + cementFmtNum(s) + ":" + cementFmtNum(a);
    mixLabel = input.grade + " (" + mixRatio + ")";
  } else {
    mixRatio = input.mortarMix;
    mixLabel = input.mortarMix;
    if (u === "m") {
      areaM2 = input.area;
    } else {
      areaM2 = input.area * CEMENT_SQFT_TO_M2;
    }
    areaSqFt = areaM2 * CEMENT_M2_TO_SQFT;
    if (mode === "plaster") {
      wetMortar = areaM2 * input.plasterThick / 1000;
    } else {
      const thickM = input.wallThick * CEMENT_IN_TO_M;
      let solidVol;
      if (input.bricks > 0) {
        wallVol = input.bricks * CEMENT_BRICK_MODULE_VOL;
        bricksExact = input.bricks;
      } else {
        wallVol = areaM2 * thickM;
        bricksExact = wallVol / CEMENT_BRICK_MODULE_VOL;
      }
      wallVolCft = wallVol * CEMENT_M3_TO_CFT;
      solidVol = bricksExact * CEMENT_BRICK_SOLID_VOL;
      wetMortar = wallVol - solidVol;
    }
    dryMortar = wetMortar * CEMENT_DRY_FACTOR_MORTAR;
    dryM3 = dryMortar;
    cementVol = dryMortar / (1 + sp);
    sandVol = dryMortar * sp / (1 + sp);
  }
  const cementKg = cementVol * CEMENT_DENSITY;
  const bagsExact = cementVol / CEMENT_BAG_VOL_M3;
  const bagsWastage = bagsExact * (1 + wastage / 100);
  const bagsToBuy = Math.ceil(bagsWastage - 1e-9);
  const sandCft = sandVol * CEMENT_M3_TO_CFT;
  const sandKg = sandVol * CEMENT_SAND_DENSITY;
  if (mode === "concrete") {
    waterL = cementKg * CEMENT_WC_RATIO;
    bagsPerM3 = bagsExact / wetM3;
  }
  if (mode === "brickwork") {
    bagsPer100 = bagsExact / bricksExact * 100;
  }
  const totalCost = rate > 0 ? bagsToBuy * rate : 0;
  const hasPrices = rate > 0;
  const areaWord = u === "ft" ? "sq ft" : "m²";
  let verdict;
  if (mode === "concrete") {
    verdict = "Buy " + bagsToBuy + " bags of cement (" + cementFmt2(bagsExact) + " bags exact, " + cementFmt0(cementKg) + " kg) for " + cementFmt2(wetM3) + " m³ of " + input.grade + " concrete.";
  } else if (mode === "plaster") {
    verdict = "Buy " + bagsToBuy + " bags of cement (" + cementFmt2(bagsExact) + " bags exact, " + cementFmt0(cementKg) + " kg) to plaster " + cementFmtNum(input.area) + " " + areaWord + " at " + input.plasterThick + " mm, " + input.mortarMix + ".";
  } else if (input.bricks > 0) {
    verdict = "Buy " + bagsToBuy + " bags of cement (" + cementFmt2(bagsExact) + " bags exact, " + cementFmt0(cementKg) + " kg) for the mortar in " + cementFmtINR(input.bricks) + " bricks.";
  } else {
    verdict = "Buy " + bagsToBuy + " bags of cement (" + cementFmt2(bagsExact) + " bags exact, " + cementFmt0(cementKg) + " kg) for the mortar in " + cementFmt2(wallVol) + " m³ of brickwork.";
  }
  const verdictLabel = verdict.slice(0, -1) + " — order " + bagsToBuy + " bags.";
  let n1;
  let n2;
  let n3;
  let n4;
  let n5;
  let n6;
  if (mode === "concrete") {
    if (u === "m") {
      n1 = "Wet volume " + cementFmt2(wetM3) + " m³ (" + cementFmt1(wetCft) + " cft) from " + cementFmtNum(input.length) + " m × " + cementFmtNum(input.width) + " m × " + cementFmtNum(input.thickness) + " m.";
    } else {
      n1 = "Wet volume " + cementFmt2(wetM3) + " m³ (" + cementFmt1(wetCft) + " cft) from " + cementFmtNum(input.length) + " ft × " + cementFmtNum(input.width) + " ft × " + cementFmtNum(input.thickness) + " in.";
    }
    n2 = "Dry volume " + cementFmt2(dryM3) + " m³ — wet volume × 1.54. Wastage is added to the cement bags only, not to the sand or aggregate.";
    const mix = CEMENT_MIX[input.grade];
    n3 = "Cement " + cementFmt2(cementVol) + " m³ (" + cementFmt0(cementKg) + " kg) = " + cementFmt2(dryM3) + " m³ dry × " + cementFmtNum(mix[0]) + "/" + (mix[0] + mix[1] + mix[2]) + " parts. That is " + cementFmt2(bagsExact) + " bags; with " + cementFmtNum(wastage) + "% wastage, buy " + bagsToBuy + " bags.";
    n4 = "Sand " + cementFmt2(sandVol) + " m³ (" + cementFmt1(sandCft) + " cft, " + cementFmt0(sandKg) + " kg); aggregate " + cementFmt2(aggVol) + " m³ (" + cementFmt1(aggCft) + " cft, " + cementFmt0(aggKg) + " kg).";
    n5 = "Water " + cementFmt0(waterL) + " litres at a water–cement ratio of 0.5 (" + cementFmt0(cementKg) + " kg × 0.5) — indicative only; the water actually needed depends on the sand moisture and the slump.";
    if (input.grade === "M25") {
      n6 = "M25 nominal (1:1:2) is shown for reference only — IS 456 allows nominal mixes only up to M20; structural M25 needs a design mix to IS 10262:2019, which usually needs only about 7–8 bags per m³.";
    } else {
      n6 = "Nominal-mix estimate, not a mix design. The 1.54 factor is an estimating convention, not a mix-design clause — sand bulking and moisture are not modelled.";
    }
  } else if (mode === "plaster") {
    n1 = "Wall area " + cementFmt2(areaM2) + " m² (" + cementFmt1(areaSqFt) + " sq ft) at " + input.plasterThick + " mm. Wet mortar " + cementFmt2(wetMortar) + " m³ = area × thickness.";
    n2 = "Dry mortar " + cementFmt2(dryMortar) + " m³ = wet mortar × 1.33.";
    n3 = "Cement " + cementFmt2(cementVol) + " m³ (" + cementFmt0(cementKg) + " kg) = dry mortar ÷ " + (1 + sp) + " parts. That is " + cementFmt2(bagsExact) + " bags; with " + cementFmtNum(wastage) + "% wastage, buy " + bagsToBuy + " bags.";
    n4 = "Sand " + cementFmt2(sandVol) + " m³ (" + cementFmt1(sandCft) + " cft) = dry mortar × " + sp + "/" + (1 + sp) + ".";
    n5 = "Plaster cement is the dry mortar ÷ (1 + sand parts). At 12 mm in 1:6, 100 sq ft takes 0.61 bags — NineClip prints the same figure; charts quoting 3–4 bags per 100 sq ft are about five times too high.";
    n6 = "Estimate for ordering, not a bill of quantities. Plaster thickness varies with the wall — measure the area and the thickness on site before ordering.";
  } else {
    if (input.bricks > 0) {
      n1 = "Brickwork " + cementFmt2(wallVol) + " m³ = " + cementFmtINR(input.bricks) + " modular bricks × 0.0020 m³ per brick with a 10 mm joint.";
    } else {
      n1 = "Brickwork " + cementFmt2(wallVol) + " m³ = " + cementFmt2(areaM2) + " m² of wall × " + cementFmtNum(input.wallThick) + " in (" + cementFmt3(input.wallThick * CEMENT_IN_TO_M) + " m) thick.";
    }
    n2 = "Wet mortar " + cementFmt2(wetMortar) + " m³ = wall volume − solid brick volume (" + cementFmt2(bricksExact * CEMENT_BRICK_SOLID_VOL) + " m³). Dry mortar " + cementFmt2(dryMortar) + " m³ = wet × 1.33.";
    n3 = "Cement " + cementFmt2(cementVol) + " m³ (" + cementFmt0(cementKg) + " kg) = dry mortar ÷ " + (1 + sp) + " parts. That is " + cementFmt2(bagsExact) + " bags; with " + cementFmtNum(wastage) + "% wastage, buy " + bagsToBuy + " bags.";
    n4 = "Sand " + cementFmt2(sandVol) + " m³ (" + cementFmt1(sandCft) + " cft) = dry mortar × " + sp + "/" + (1 + sp) + ".";
    n5 = "That is " + cementFmt2(bagsPer100) + " bags per 100 bricks. The figure sometimes quoted online, 1.25 bags per 100 bricks at 1:6, would need about 1.15 m³ of mortar per m³ of brickwork — more mortar than the wall can hold — and does not survive the volume calculation.";
    n6 = "Estimate for ordering, not a bill of quantities. Brick sizes vary by kiln and region — measure a sample from the batch you buy.";
  }
  const notes = [n1, n2, n3, n4, n5, n6];
  return {
    mode: mode,
    unit: u,
    length: input.length,
    width: input.width,
    thickness: input.thickness,
    grade: input.grade,
    area: input.area,
    plasterThick: input.plasterThick,
    mortarMix: input.mortarMix,
    wallThick: input.wallThick,
    bricks: input.bricks,
    wastage: wastage,
    rate: rate,
    modeLabel: CEMENT_MODE_LABELS[mode],
    mixRatio: mixRatio,
    mixLabel: mixLabel,
    wetM3: wetM3,
    wetCft: wetCft,
    dryM3: dryM3,
    cementVolM3: cementVol,
    cementKg: cementKg,
    cementBagsExact: bagsExact,
    cementBagsWastage: bagsWastage,
    cementBagsToBuy: bagsToBuy,
    sandVolM3: sandVol,
    sandCft: sandCft,
    sandKg: sandKg,
    aggVolM3: aggVol,
    aggCft: aggCft,
    aggKg: aggKg,
    waterL: waterL,
    bagsPerM3: bagsPerM3,
    areaM2: areaM2,
    areaSqFt: areaSqFt,
    wallVolM3: wallVol,
    wallVolCft: wallVolCft,
    wetMortarM3: wetMortar,
    dryMortarM3: dryMortar,
    bricksExact: bricksExact,
    cementBagsPer100Bricks: bagsPer100,
    totalCost: totalCost,
    hasPrices: hasPrices,
    verdict: verdict,
    verdictLabel: verdictLabel,
    notes: notes,
  };
}

