// False Ceiling Cost Calculator.
// Two modes in one calculator card, worked out in the browser.
// - Cost estimator: room length x width (ft/m toggle) x ceiling type
//   (POP / gypsum board / grid / PVC panel) x design (flat / single
//   cove tray / floating island / designer) -> effective area, then a
//   low-typical-high range from InteriorCalculator's 2026 per-sq-ft
//   rates (POP 55-90, gypsum 70-130, grid 60-100, PVC 85-140;
//   typical = midpoint). Cove LED strip at 120-200 per Rft of cove
//   run, where the cove run is ~30% of the room perimeter
//   (InteriorCalculator's rule for a living-room cove); profile
//   lighting at 2,500-5,000 per metre; finishing (putty + primer +
//   emulsion) at 35-60 per sq ft of effective area; extras are
//   user-entered rupees (lights, borders) added after the city
//   multiplier. City multipliers are the midpoint ratios of
//   InteriorCalculator's 200 sq ft gypsum-with-cove city table against
//   Tier-2 as base: Mumbai 47,500/33,500 = 1.42, Delhi NCR
//   43,500/33,500 = 1.30, Bengaluru 40,000/33,500 = 1.19,
//   Hyderabad/Chennai/Pune 38,000/33,500 = 1.13, Tier-2 1.00.
//   GST at 18% is a toggle, off by default: published rates disagree
//   on whether GST is included (Kalikolom notes many quotes exclude
//   GST, wiring and lights), so the page never silently adds it.
//   Effective area = flat area x design multiplier (Toolique:
//   flat 1.00, single cove tray 1.20, floating island 1.35,
//   designer 1.60). The band per-sq-ft figure (ceiling + cove,
//   pre-city, pre-GST) is checked against SpaceForm's 2026 bands
//   (plain 85-130, cove 110-170, designer 170-300+ per sq ft).
// - Material BOQ (gypsum/POP framing, IS 2095 via Toolique):
//   gypsum boards 4 ft x 8 ft = 32 sq ft each, +10% wastage,
//   rounded up; perimeter channel = room perimeter; ceiling
//   sections at 457 mm c/c (lines = floor(width / 0.457) + 1, run
//   along the length); intermediate channels at 1220 mm c/c
//   (lines = floor(length / 1.22) + 1, run across the width);
//   drywall screws at 200 mm centres along each board's perimeter
//   (board 1.22 x 2.44 m = 7.32 m of edge, 37 screws a board —
//   shared edges counted per board, so a conservative count —
//   rounded up to the nearest 100 to buy); joint compound 3 coats
//   at 0.06 kg per sq ft of effective area (USG SHEETROCK spec:
//   125-150 lb per 1,000 sq ft = 0.057-0.068 kg per sq ft), in
//   25 kg bags; downlights 1 per 20-25 sq ft (a range); cove LED
//   length = cove run in Rft, with one 150 W SMPS driver per
//   45-55 Rft (a range). The BOQ is the gypsum/POP framing for the
//   room whatever the ceiling type: grid ceilings use 2x2 ft tiles
//   on a T-grid and PVC uses tongue-and-groove panels, so their
//   BOQ is different — the page says so.
// - Display rounding: money whole rupees with Indian grouping,
//   areas 1dp, metres 2dp, Rft 1dp, per-sq-ft rupees 0dp, kg 1dp.
//   All rounding is round half up with a 1e-9 nudge, matching the
//   independent Python model exactly.
// - No fixed price is presented as fact: every rate is an indicative
//   2026 range with its source and date, and where the sources
//   disagree the disagreement is stated on the page (Toolique's POP
//   single rate of 130 sits above InteriorCalculator's 55-90 plain-POP
//   range — Toolique prices a premium hand-troweled POP; Kalikolom's
//   168 sq ft grid/tile drop ceiling at 18,204 sits above this page's
//   grid range — a different system, priced per tile).
export const FALSECEILING_KEYS = ["mode", "unit", "length", "width", "type", "design", "cove", "profile", "finishing", "city", "gst", "extras"];
export const FALSECEILING_MODES = ["cost", "boq"];
export const FALSECEILING_MODE_LABELS = { "cost": "Cost estimator", "boq": "Material BOQ (gypsum / POP)" };
export const FALSECEILING_TYPES = ["pop", "gypsum", "grid", "pvc"];
export const FALSECEILING_TYPE_LABELS = { "pop": "POP", "gypsum": "gypsum board", "grid": "grid", "pvc": "PVC panel" };
export const FALSECEILING_DESIGNS = ["flat", "cove", "floating", "designer"];
export const FALSECEILING_DESIGN_LABELS = { "flat": "flat", "cove": "single cove tray", "floating": "floating island", "designer": "designer" };
export const FALSECEILING_DESIGN_MULT = { "flat": 1, "cove": 1.2, "floating": 1.35, "designer": 1.6 };
export const FALSECEILING_UNITS = ["ft", "m"];
export const FALSECEILING_CITIES = ["mumbai", "delhi", "bengaluru", "hyd", "tier2"];
export const FALSECEILING_CITY_LABELS = { "mumbai": "Mumbai", "delhi": "Delhi NCR", "bengaluru": "Bengaluru", "hyd": "Hyderabad / Chennai / Pune", "tier2": "Tier-2 / other city" };
export const FALSECEILING_CITY_MULT = { "mumbai": 1.42, "delhi": 1.3, "bengaluru": 1.19, "hyd": 1.13, "tier2": 1 };
export const FALSECEILING_RATES = { "pop": [55, 90], "gypsum": [70, 130], "grid": [60, 100], "pvc": [85, 140] };
export const FALSECEILING_COVE_LO = 120;
export const FALSECEILING_COVE_TYP = 160;
export const FALSECEILING_COVE_HI = 200;
export const FALSECEILING_PROFILE_LO = 2500;
export const FALSECEILING_PROFILE_TYP = 3750;
export const FALSECEILING_PROFILE_HI = 5000;
export const FALSECEILING_FINISH_LO = 35;
export const FALSECEILING_FINISH_TYP = 47.5;
export const FALSECEILING_FINISH_HI = 60;
export const FALSECEILING_COVE_RUN_FRACTION = 0.3;
export const FALSECEILING_GST_RATE = 0.18;
export const FALSECEILING_BOARD_SQFT = 32;
export const FALSECEILING_WASTAGE = 0.1;
export const FALSECEILING_CEILING_SECTION_MM = 457;
export const FALSECEILING_INTER_MM = 1220;
export const FALSECEILING_SCREW_MM = 200;
export const FALSECEILING_BOARD_EDGE_M = 7.32;
export const FALSECEILING_SCREWS_PER_BOARD = 37;
export const FALSECEILING_COMPOUND_KG_PER_SQFT = 0.06;
export const FALSECEILING_COMPOUND_BAG_KG = 25;
export const FALSECEILING_DOWNLIGHT_LO_SQFT = 25;
export const FALSECEILING_DOWNLIGHT_HI_SQFT = 20;
export const FALSECEILING_DRIVER_LO_RFT = 55;
export const FALSECEILING_DRIVER_HI_RFT = 45;
export const FALSECEILING_FT_TO_M = 0.3048;
export const FALSECEILING_MM_PER_M = 1000;
export const FALSECEILING_LENGTH_FT_MIN = 4;
export const FALSECEILING_LENGTH_FT_MAX = 60;
export const FALSECEILING_WIDTH_FT_MIN = 4;
export const FALSECEILING_WIDTH_FT_MAX = 60;
export const FALSECEILING_LENGTH_M_MIN = 1.2;
export const FALSECEILING_LENGTH_M_MAX = 18.3;
export const FALSECEILING_WIDTH_M_MIN = 1.2;
export const FALSECEILING_WIDTH_M_MAX = 18.3;
export const FALSECEILING_AREA_MIN = 40;
export const FALSECEILING_AREA_MAX = 1200;
export const FALSECEILING_PROFILE_MAX = 100;
export const FALSECEILING_EXTRAS_MAX = 200000;
export function falseCeilingFmt0(x) {
  return String(Math.round(x + 1e-9));
}
export function falseCeilingFmt1(x) {
  return (Math.round(x * 10 + 1e-9) / 10).toFixed(1);
}
export function falseCeilingFmt2(x) {
  return (Math.round(x * 100 + 1e-9) / 100).toFixed(2);
}
export function falseCeilingFmt3(x) {
  return (Math.round(x * 1000 + 1e-9) / 1000).toFixed(3);
}
export function falseCeilingFmtNum(x) {
  return String(x);
}
export function falseCeilingFmtINR(x) {
  const n = Math.round(x + 1e-9);
  const s = String(n);
  if (s.length <= 3) return s;
  const last3 = s.slice(-3);
  let rest = s.slice(0, -3);
  const parts = [];
  while (rest.length > 2) { parts.unshift(rest.slice(-2)); rest = rest.slice(0, -2); }
  if (rest) parts.unshift(rest);
  return parts.join(",") + "," + last3;
}
export function falseCeilingIsNum(v) {
  return typeof v === "number" && Number.isFinite(v);
}
export function falseCeilingIsBool(v) {
  return typeof v === "boolean";
}
export function falseCeilingValid(input) {
  if (!input || typeof input !== "object" || Array.isArray(input)) return false;
  const keys = Object.keys(input);
  if (keys.length !== FALSECEILING_KEYS.length) return false;
  for (const k of FALSECEILING_KEYS) if (!keys.includes(k)) return false;
  if (!FALSECEILING_MODES.includes(input.mode)) return false;
  if (!FALSECEILING_UNITS.includes(input.unit)) return false;
  if (!FALSECEILING_TYPES.includes(input.type)) return false;
  if (!FALSECEILING_DESIGNS.includes(input.design)) return false;
  if (!FALSECEILING_CITIES.includes(input.city)) return false;
  if (!falseCeilingIsBool(input.cove)) return false;
  if (!falseCeilingIsBool(input.finishing)) return false;
  if (!falseCeilingIsBool(input.gst)) return false;
  const u = input.unit;
  const lMin = u === "ft" ? FALSECEILING_LENGTH_FT_MIN : FALSECEILING_LENGTH_M_MIN;
  const lMax = u === "ft" ? FALSECEILING_LENGTH_FT_MAX : FALSECEILING_LENGTH_M_MAX;
  const wMin = u === "ft" ? FALSECEILING_WIDTH_FT_MIN : FALSECEILING_WIDTH_M_MIN;
  const wMax = u === "ft" ? FALSECEILING_WIDTH_FT_MAX : FALSECEILING_WIDTH_M_MAX;
  if (!falseCeilingIsNum(input.length) || input.length < lMin || input.length > lMax) return false;
  if (!falseCeilingIsNum(input.width) || input.width < wMin || input.width > wMax) return false;
  const lengthFt = u === "ft" ? input.length : input.length / FALSECEILING_FT_TO_M;
  const widthFt = u === "ft" ? input.width : input.width / FALSECEILING_FT_TO_M;
  const areaSqFt = lengthFt * widthFt;
  if (areaSqFt < FALSECEILING_AREA_MIN || areaSqFt > FALSECEILING_AREA_MAX) return false;
  if (!falseCeilingIsNum(input.profile) || input.profile < 0 || input.profile > FALSECEILING_PROFILE_MAX) return false;
  if (!falseCeilingIsNum(input.extras) || input.extras < 0 || input.extras > FALSECEILING_EXTRAS_MAX) return false;
  return true;
}
export function falseCeilingCompute(input) {
  if (!falseCeilingValid(input)) return null;
  const mode = input.mode;
  const u = input.unit;
  const type = input.type;
  const design = input.design;
  const city = input.city;
  const cove = input.cove;
  const finishing = input.finishing;
  const gst = input.gst;
  const profile = input.profile;
  const extras = input.extras;
  const lengthFt = u === "ft" ? input.length : input.length / FALSECEILING_FT_TO_M;
  const widthFt = u === "ft" ? input.width : input.width / FALSECEILING_FT_TO_M;
  const lengthM = lengthFt * FALSECEILING_FT_TO_M;
  const widthM = widthFt * FALSECEILING_FT_TO_M;
  const areaSqFt = lengthFt * widthFt;
  const areaM2 = lengthM * widthM;
  const perimeterFt = 2 * (lengthFt + widthFt);
  const perimeterM = perimeterFt * FALSECEILING_FT_TO_M;
  const coveRunRft = cove ? FALSECEILING_COVE_RUN_FRACTION * perimeterFt : 0;
  const designMult = FALSECEILING_DESIGN_MULT[design];
  const effArea = areaSqFt * designMult;
  const rateLow = FALSECEILING_RATES[type][0];
  const rateHigh = FALSECEILING_RATES[type][1];
  const rateTyp = (rateLow + rateHigh) / 2;
  const ceilingLow = effArea * rateLow;
  const ceilingTyp = effArea * rateTyp;
  const ceilingHigh = effArea * rateHigh;
  const coveLow = coveRunRft * FALSECEILING_COVE_LO;
  const coveTyp = coveRunRft * FALSECEILING_COVE_TYP;
  const coveHigh = coveRunRft * FALSECEILING_COVE_HI;
  const profileLow = profile * FALSECEILING_PROFILE_LO;
  const profileTyp = profile * FALSECEILING_PROFILE_TYP;
  const profileHigh = profile * FALSECEILING_PROFILE_HI;
  const finishingLow = finishing ? effArea * FALSECEILING_FINISH_LO : 0;
  const finishingTyp = finishing ? effArea * FALSECEILING_FINISH_TYP : 0;
  const finishingHigh = finishing ? effArea * FALSECEILING_FINISH_HI : 0;
  const cityMult = FALSECEILING_CITY_MULT[city];
  const subtotalLow = (ceilingLow + coveLow + profileLow + finishingLow) * cityMult + extras;
  const subtotalTyp = (ceilingTyp + coveTyp + profileTyp + finishingTyp) * cityMult + extras;
  const subtotalHigh = (ceilingHigh + coveHigh + profileHigh + finishingHigh) * cityMult + extras;
  const gstMult = gst ? 1 + FALSECEILING_GST_RATE : 1;
  const totalLow = subtotalLow * gstMult;
  const totalTyp = subtotalTyp * gstMult;
  const totalHigh = subtotalHigh * gstMult;
  const perSqFtTyp = totalTyp / areaSqFt;
  const bandPerSqFt = (ceilingTyp + coveTyp) / areaSqFt;
  const boards = Math.ceil(effArea * (1 + FALSECEILING_WASTAGE) / FALSECEILING_BOARD_SQFT - 1e-9);
  const perimeterChannelFt = perimeterFt;
  const perimeterChannelM = perimeterM;
  const ceilLines = Math.floor(widthM / (FALSECEILING_CEILING_SECTION_MM / FALSECEILING_MM_PER_M) + 1e-9) + 1;
  const ceilSectionM = ceilLines * lengthM;
  const ceilSectionFt = ceilSectionM / FALSECEILING_FT_TO_M;
  const interLines = Math.floor(lengthM / (FALSECEILING_INTER_MM / FALSECEILING_MM_PER_M) + 1e-9) + 1;
  const interM = interLines * widthM;
  const interFt = interM / FALSECEILING_FT_TO_M;
  const screws = boards * FALSECEILING_SCREWS_PER_BOARD;
  const screwsBuy = Math.ceil(screws / 100 - 1e-9) * 100;
  const compoundKg = effArea * FALSECEILING_COMPOUND_KG_PER_SQFT;
  const compoundBags = Math.ceil(compoundKg / FALSECEILING_COMPOUND_BAG_KG - 1e-9);
  const downLow = Math.floor(areaSqFt / FALSECEILING_DOWNLIGHT_LO_SQFT + 1e-9);
  const downHigh = Math.ceil(areaSqFt / FALSECEILING_DOWNLIGHT_HI_SQFT - 1e-9);
  const driversLow = Math.ceil(coveRunRft / FALSECEILING_DRIVER_LO_RFT - 1e-9);
  const driversHigh = Math.ceil(coveRunRft / FALSECEILING_DRIVER_HI_RFT - 1e-9);
  const typeLabel = FALSECEILING_TYPE_LABELS[type];
  const designLabel = FALSECEILING_DESIGN_LABELS[design];
  const cityLabel = FALSECEILING_CITY_LABELS[city];
  let verdict;
  if (mode === "cost") {
    verdict = "₹" + falseCeilingFmtINR(totalTyp) + " typically (₹" + falseCeilingFmtINR(totalLow) + "–₹" + falseCeilingFmtINR(totalHigh) + ") for a " + falseCeilingFmt1(areaSqFt) + " sq ft " + typeLabel + " ceiling, " + designLabel + ", in " + cityLabel + " — ₹" + falseCeilingFmt0(perSqFtTyp) + " per sq ft.";
  } else {
    verdict = boards + " gypsum boards, " + falseCeilingFmt1(perimeterChannelFt) + " ft of perimeter channel and " + falseCeilingFmt1(ceilSectionFt) + " ft of ceiling sections for a " + falseCeilingFmt1(areaSqFt) + " sq ft ceiling — plus " + screws + " screws, " + falseCeilingFmt1(compoundKg) + " kg of joint compound and " + downLow + "–" + downHigh + " downlights.";
  }
  let flagSummary;
  if (mode === "cost") {
    flagSummary = gst ? "Includes 18% GST. Indicative 2026 range — confirm with a written quote." : "GST not included. Indicative 2026 range — confirm with a written quote.";
  } else {
    flagSummary = "Gypsum / POP framing to IS 2095 — grid and PVC ceilings use a different BOQ.";
  }
  const verdictLabel = verdict.slice(0, -1) + " — " + flagSummary;
  let n1;
  let n2;
  let n3;
  let n4;
  let n5;
  let n6;
  if (mode === "cost") {
    n1 = "Ceiling: " + falseCeilingFmt1(effArea) + " sq ft effective area (" + falseCeilingFmt1(areaSqFt) + " sq ft × " + falseCeilingFmt2(designMult) + " for a " + designLabel + " design) × ₹" + falseCeilingFmt0(rateTyp) + " per sq ft (" + typeLabel + " typical, range ₹" + rateLow + "–₹" + rateHigh + ") = ₹" + falseCeilingFmtINR(ceilingTyp) + " (range ₹" + falseCeilingFmtINR(ceilingLow) + "–₹" + falseCeilingFmtINR(ceilingHigh) + ").";
    if (cove) {
      n2 = "Cove lighting: " + falseCeilingFmt1(coveRunRft) + " Rft of cove run (30% of the " + falseCeilingFmt1(perimeterFt) + " ft perimeter) × ₹160 per Rft (range ₹120–₹200) = ₹" + falseCeilingFmtINR(coveTyp) + ".";
    } else {
      n2 = "No cove lighting: the cove run is 30% of the " + falseCeilingFmt1(perimeterFt) + " ft perimeter (" + falseCeilingFmt1(FALSECEILING_COVE_RUN_FRACTION * perimeterFt) + " Rft), priced at ₹120–₹200 per Rft — switch cove lighting on to add ₹" + falseCeilingFmtINR(FALSECEILING_COVE_RUN_FRACTION * perimeterFt * FALSECEILING_COVE_TYP) + " typically.";
    }
    const extraBits = [];
    if (profile > 0) extraBits.push("profile lighting " + falseCeilingFmtNum(profile) + " m × ₹3,750 a metre = ₹" + falseCeilingFmtINR(profileTyp));
    if (finishing) extraBits.push("finishing " + falseCeilingFmt1(effArea) + " sq ft × ₹47.50 a sq ft = ₹" + falseCeilingFmtINR(finishingTyp));
    if (extras > 0) extraBits.push("extras ₹" + falseCeilingFmtINR(extras));
    if (extraBits.length) {
      n3 = "Added: " + extraBits.join("; ") + ".";
    } else {
      n3 = "No profile lighting, finishing or extras added — profile lighting is ₹2,500–₹5,000 a metre and finishing (putty + primer + emulsion) is ₹35–₹60 a sq ft.";
    }
    n4 = "City: " + cityLabel + " × " + falseCeilingFmt2(cityMult) + " (midpoint ratio from InteriorCalculator's 200 sq ft gypsum-with-cove table, Tier-2 as base). Subtotal ₹" + falseCeilingFmtINR(subtotalTyp) + (gst ? " × 1.18 for 18% GST" : " — GST off") + " = ₹" + falseCeilingFmtINR(totalTyp) + " typically, ₹" + falseCeilingFmt0(perSqFtTyp) + " per sq ft. The band figure (ceiling + cove only, before city and GST) is ₹" + falseCeilingFmt1(bandPerSqFt) + " per sq ft.";
    if (type === "pop") {
      n5 = "Toolique lists POP at a single ₹130 per sq ft — above this page's ₹55–₹90 plain-POP range. Toolique prices a premium hand-troweled POP with chicken mesh and 3-stage plaster; InteriorCalculator's range is plain POP. Both are printed here so the gap is visible, not hidden.";
    } else if (type === "grid") {
      n5 = "Kalikolom's grid/tile drop-ceiling tool prices the same 168 sq ft room at ₹18,204 (₹108 per sq ft) — above this page's grid range. Kalikolom prices a tile-and-grid system with mineral-fibre tiles, a different system from the gypsum/POP/grid rates here; use its figure if you are buying tiles, this page's if you are comparing systems.";
    } else {
      n5 = "Where the sources disagree the page says so: Toolique's POP single rate (₹130) sits above InteriorCalculator's plain-POP range (₹55–₹90), and Kalikolom's grid/tile drop ceiling (₹108 per sq ft) sits above this page's grid range — both are different systems, priced differently.";
    }
    n6 = "Indicative 2026 range, not a quote — rates vary by contractor, site condition and finish, and the published ranges do not all say whether GST is included. Get a written, itemised quote before ordering.";
  } else {
    n1 = "Boards: " + falseCeilingFmt1(effArea) + " sq ft effective area × 1.10 for wastage ÷ 32 sq ft a board (4 ft × 8 ft) = " + boards + " gypsum boards to buy.";
    n2 = "GI framing to IS 2095: perimeter channel " + falseCeilingFmt1(perimeterChannelFt) + " ft (" + falseCeilingFmt2(perimeterChannelM) + " m) — the room perimeter; ceiling sections " + ceilLines + " lines at 457 mm centres × " + falseCeilingFmt2(lengthM) + " m = " + falseCeilingFmt1(ceilSectionFt) + " ft (" + falseCeilingFmt2(ceilSectionM) + " m); intermediate channels " + interLines + " lines at 1,220 mm centres × " + falseCeilingFmt2(widthM) + " m = " + falseCeilingFmt1(interFt) + " ft (" + falseCeilingFmt2(interM) + " m).";
    n3 = "Fixings and finish: " + screws + " drywall screws (" + boards + " boards × 37 — 200 mm centres along each board's 7.32 m of edge, shared edges counted per board, so a conservative count; " + screwsBuy + " to buy, rounded up to the nearest 100) and " + falseCeilingFmt1(compoundKg) + " kg of joint compound (" + falseCeilingFmt1(effArea) + " sq ft × 0.06 kg a sq ft, 3 coats — " + compoundBags + " bag" + (compoundBags === 1 ? "" : "s") + " of 25 kg).";
    n4 = "Lighting: " + downLow + "–" + downHigh + " recessed downlights (1 per 20–25 sq ft of the " + falseCeilingFmt1(areaSqFt) + " sq ft room)" + (cove ? "; cove LED " + falseCeilingFmt1(coveRunRft) + " Rft with " + driversLow + (driversLow === driversHigh ? "" : "–" + driversHigh) + " SMPS driver" + (driversHigh === 1 ? "" : "s") + " of 150 W (1 per 45–55 Rft)." : " — no cove lighting, so no cove LED or driver.");
    n5 = "This BOQ is the gypsum / POP framing for the room — perimeter channel, ceiling sections, intermediate channels, screws and joint compound to IS 2095. Grid ceilings use 2 × 2 ft tiles on a T-grid and PVC uses tongue-and-groove panels, so their BOQ is different; the figures above are the gypsum/POP framing for the same room.";
    n6 = "Planning quantities, not an order — measure the room yourself, check the board size your supplier stocks (4 ft × 8 ft here), and add wastage for cut edges and openings before ordering.";
  }
  const notes = [n1, n2, n3, n4, n5, n6];
  return {
    mode: mode,
    unit: u,
    type: type,
    design: design,
    city: city,
    cove: cove,
    finishing: finishing,
    gst: gst,
    length: input.length,
    width: input.width,
    profile: profile,
    extras: extras,
    modeLabel: FALSECEILING_MODE_LABELS[mode],
    typeLabel: typeLabel,
    designLabel: designLabel,
    cityLabel: cityLabel,
    lengthFt: lengthFt,
    widthFt: widthFt,
    lengthM: lengthM,
    widthM: widthM,
    areaSqFt: areaSqFt,
    areaM2: areaM2,
    perimeterFt: perimeterFt,
    perimeterM: perimeterM,
    coveRunRft: coveRunRft,
    effArea: effArea,
    designMult: designMult,
    rateLow: rateLow,
    rateTyp: rateTyp,
    rateHigh: rateHigh,
    ceilingLow: ceilingLow,
    ceilingTyp: ceilingTyp,
    ceilingHigh: ceilingHigh,
    coveLow: coveLow,
    coveTyp: coveTyp,
    coveHigh: coveHigh,
    profileLow: profileLow,
    profileTyp: profileTyp,
    profileHigh: profileHigh,
    finishingLow: finishingLow,
    finishingTyp: finishingTyp,
    finishingHigh: finishingHigh,
    cityMult: cityMult,
    subtotalLow: subtotalLow,
    subtotalTyp: subtotalTyp,
    subtotalHigh: subtotalHigh,
    totalLow: totalLow,
    totalTyp: totalTyp,
    totalHigh: totalHigh,
    perSqFtTyp: perSqFtTyp,
    bandPerSqFt: bandPerSqFt,
    boards: boards,
    perimeterChannelFt: perimeterChannelFt,
    perimeterChannelM: perimeterChannelM,
    ceilLines: ceilLines,
    ceilSectionM: ceilSectionM,
    ceilSectionFt: ceilSectionFt,
    interLines: interLines,
    interM: interM,
    interFt: interFt,
    screws: screws,
    screwsBuy: screwsBuy,
    compoundKg: compoundKg,
    compoundBags: compoundBags,
    downLow: downLow,
    downHigh: downHigh,
    driversLow: driversLow,
    driversHigh: driversHigh,
    verdict: verdict,
    verdictLabel: verdictLabel,
    notes: notes,
  };
}

