    if (input.areaBasis === "carpet") {
      n4 = "You entered carpet area. NoBroker's guide prices on carpet area, but Black Ant Studio warns that some vendors quote the same rate on built-up area — always ask which area a quote uses, because the same rate on built-up area gives a higher total. This page applies the rate to the area exactly as you entered it, with no invented conversion.";
    } else {
      n4 = "You entered built-up area. NoBroker's guide prices on carpet area, but Black Ant Studio warns that some vendors quote the same rate on built-up area — always ask which area a quote uses, because the same rate on built-up area gives a higher total. This page applies the rate to the area exactly as you entered it, with no invented conversion.";
    }
