  "westbengal": null,
  "madhyapradesh": [{ "limit": 1000000, "rate": 8, "below": false }, { "limit": 2000000, "rate": 10, "below": false }, { "limit": null, "rate": 14, "below": false }],
  "bihar": [{ "limit": 100000, "rate": 8, "below": false }, { "limit": 800000, "rate": 9, "below": true }, { "limit": 1500000, "rate": 10, "below": true }, { "limit": null, "rate": 12, "below": false }],
  "odisha": [{ "limit": 50000, "rate": 6, "below": false }, { "limit": 1000000, "rate": 8, "below": false }, { "limit": 2000000, "rate": 10, "below": false }, { "limit": 4000000, "rate": 12, "below": false }, { "limit": null, "rate": 20, "below": false }]
