          return `
        <article class="story">
          <h3>${e(st.title)}</h3>
          <p>${e(st.body)}</p>
          <p class="story-result">${resultLine}</p>
          ${st.tryIt ? `<p><button class="calc-btn" type="button" data-preset="${e(st.preset)}">Try these figures →</button></p>` : ""}
        </article>`;
