export function rentReceiptClient(c) {
  const $ = id => document.getElementById(id);

  function rentReceiptFmt0(x) {
    return String(Math.round(x + 1e-9));
  }

  function rentReceiptFmt1(x) {
    return (Math.round(x * 10 + 1e-9) / 10).toFixed(1);
  }

  function rentReceiptFmt2(x) {
    return (Math.round(x * 100 + 1e-9) / 100).toFixed(2);
  }

  function rentReceiptFmtNum(x) {
    return String(x);
  }

  function rentReceiptFmtINR(x) {
    const n = Math.round(x + 1e-9);
    const s = String(n);
    if (s.length <= 3) return s;
    const last3 = s.slice(-3);
    let rest = s.slice(0, -3);
    const parts = [];
    while (rest.length > 2) { parts.unshift(rest.slice(-2)); rest = rest.slice(0, -2); }
    if (rest) parts.unshift(rest);
    return parts.join(",") + "," + last3;
  }

  function rentReceiptFmtINR2(x) {
    const whole = Math.floor(rentReceiptR2(x));
    const frac = Math.round((rentReceiptR2(x) - whole) * 100);
    return rentReceiptFmtINR(whole) + "." + String(frac).padStart(2, "0");
  }

  function rentReceiptIsNum(v) {
    return typeof v === "number" && Number.isFinite(v);
  }

  function rentReceiptIsInt(v) {
    return typeof v === "number" && Number.isInteger(v);
  }

  function rentReceiptR2(x) {
    return Math.round(x * 100 + 1e-9) / 100;
  }

  function rentReceiptR1(x) {
    return Math.round(x * 10 + 1e-9) / 10;
  }

  function rentReceiptWordsUnder100(n) {
    if (n < 20) return RENT_RECEIPT_ONES[n];
    const ten = Math.floor(n / 10);
    const one = n % 10;
    if (one === 0) return RENT_RECEIPT_TENS[ten];
    return RENT_RECEIPT_TENS[ten] + "-" + RENT_RECEIPT_ONES[one];
  }

  function rentReceiptWordsUnder1000(n) {
    const hundred = Math.floor(n / 100);
    const rest = n % 100;
    let s = "";
    if (hundred) s += RENT_RECEIPT_ONES[hundred] + " Hundred";
    if (rest) s += (s ? " " : "") + rentReceiptWordsUnder100(rest);
    return s;
  }

  function rentReceiptWords(n) {
    if (!rentReceiptIsInt(n) || n < 0 || n > 999999999) return null;
    if (n === 0) return "Zero";
    const parts = [];
    let rem = n;
    const crore = Math.floor(rem / 10000000);
    rem = rem % 10000000;
    const lakh = Math.floor(rem / 100000);
    rem = rem % 100000;
    const thousand = Math.floor(rem / 1000);
    rem = rem % 1000;
    if (crore) parts.push(rentReceiptWordsUnder1000(crore) + " Crore");
    if (lakh) parts.push(rentReceiptWordsUnder1000(lakh) + " Lakh");
    if (thousand) parts.push(rentReceiptWordsUnder1000(thousand) + " Thousand");
    const rest = rentReceiptWordsUnder1000(rem);
    if (rest) parts.push(rest);
    return parts.join(" ");
  }

  function rentReceiptAmountWords(n) {
    const w = rentReceiptWords(n);
    return w === null ? null : w + " Rupees Only";
  }

  function rentReceiptDaysInMonth(year, month) {
    if (month === 2) {
      const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
      return leap ? 29 : 28;
    }
    return [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1];
  }

  function rentReceiptMonthLabel(year, month) {
    return RENT_RECEIPT_MONTH_NAMES[month - 1] + " " + year;
  }

  function rentReceiptDateLabel(day, month, year) {
    return day + " " + RENT_RECEIPT_MONTH_NAMES[month - 1] + " " + year;
  }

  function rentReceiptParseStartMonth(s) {
    if (typeof s !== "string") return null;
    const m = /^(\d{4})-(\d{2})$/.exec(s);
    if (!m) return null;
    const year = Number(m[1]);
    const month = Number(m[2]);
    if (year < RENT_RECEIPT_START_YEAR_MIN || year > RENT_RECEIPT_START_YEAR_MAX) return null;
    if (month < 1 || month > 12) return null;
    return { year: year, month: month };
  }

  function rentReceiptNotes(r) {
    const first = r.months + (r.months === 1 ? " receipt" : " receipts") + ", " + r.startLabel + " to " + r.endLabel + " — ₹" + rentReceiptFmtINR(r.totalRent) + " in total (₹" + rentReceiptFmtINR(r.monthlyRent) + " a month).";
    let second;
    if (r.panRequired) {
      second = "Landlord PAN is required — the rent for a full year at ₹" + rentReceiptFmtINR(r.monthlyRent) + " a month is ₹" + rentReceiptFmtINR(r.annualisedRent) + ", over the ₹1,00,000 limit (CBDT Circular No. 08/2013).";
    } else {
      second = "Landlord PAN is not required — the rent for a full year at ₹" + rentReceiptFmtINR(r.monthlyRent) + " a month is ₹" + rentReceiptFmtINR(r.annualisedRent) + ", under the ₹1,00,000 limit.";
    }
    let third;
    if (r.paymentMode === "cash") {
      if (r.stampCount > 0) {
        third = "Cash payment over ₹5,000 a receipt, so " + (r.stampCount === 1 ? "the receipt carries" : "each of the " + r.stampCount + " receipts carries") + " a ₹1 revenue-stamp box — sign across the stamp (Indian Stamp Act, Schedule I, Article 53).";
      } else {
        third = "Cash payment, but ₹" + rentReceiptFmtINR(r.monthlyRent) + " a receipt is not over the ₹5,000 limit, so no revenue stamp is needed.";
      }
    } else {
      third = "Paid by " + r.paymentModeLabel.toLowerCase() + ", so no revenue stamp is shown on these receipts — the " + r.paymentModeLabel.toLowerCase() + " record is the proof.";
    }
    return [first, second, third];
  }

  function rentReceiptValid(input) {
    if (!input || typeof input !== "object" || Array.isArray(input)) return false;
    const keys = Object.keys(input);
    if (keys.length !== RENT_RECEIPT_KEYS.length) return false;
    for (const k of RENT_RECEIPT_KEYS) if (!keys.includes(k)) return false;
    if (typeof input.tenantName !== "string" || input.tenantName.trim().length < RENT_RECEIPT_NAME_MIN || input.tenantName.trim().length > RENT_RECEIPT_NAME_MAX) return false;
    if (typeof input.landlordName !== "string" || input.landlordName.trim().length < RENT_RECEIPT_NAME_MIN || input.landlordName.trim().length > RENT_RECEIPT_NAME_MAX) return false;
    if (typeof input.propertyAddress !== "string" || input.propertyAddress.trim().length < RENT_RECEIPT_ADDRESS_MIN || input.propertyAddress.trim().length > RENT_RECEIPT_ADDRESS_MAX) return false;
    if (!rentReceiptIsInt(input.monthlyRent) || input.monthlyRent < RENT_RECEIPT_RENT_MIN || input.monthlyRent > RENT_RECEIPT_RENT_MAX) return false;
    if (!RENT_RECEIPT_PAYMENT_MODES.includes(input.paymentMode)) return false;
    if (typeof input.landlordPan !== "string") return false;
    if (input.landlordPan !== "" && !RENT_RECEIPT_PAN_RE.test(input.landlordPan)) return false;
    if (rentReceiptParseStartMonth(input.startMonth) === null) return false;
    if (!rentReceiptIsInt(input.months) || input.months < RENT_RECEIPT_MONTHS_MIN || input.months > RENT_RECEIPT_MONTHS_MAX) return false;
    return true;
  }

  function rentReceiptCompute(input) {
    if (!rentReceiptValid(input)) return null;
    const start = rentReceiptParseStartMonth(input.startMonth);
    const receipts = [];
    let y = start.year;
    let m = start.month;
    for (let i = 0; i < input.months; i++) {
      const days = rentReceiptDaysInMonth(y, m);
      const monthLabel = rentReceiptMonthLabel(y, m);
      receipts.push({
        number: i + 1,
        numberLabel: String(i + 1).padStart(3, "0"),
        monthKey: y + "-" + String(m).padStart(2, "0"),
        monthLabel: monthLabel,
        periodStart: "1 " + monthLabel,
        periodEnd: days + " " + monthLabel,
        date: days + " " + monthLabel,
        amount: input.monthlyRent,
        amountWords: rentReceiptAmountWords(input.monthlyRent),
        needsStamp: input.paymentMode === "cash" && input.monthlyRent > RENT_RECEIPT_STAMP_THRESHOLD
      });
      m++;
      if (m > 12) { m = 1; y++; }
    }
    const totalRent = input.monthlyRent * input.months;
    const annualisedRent = input.monthlyRent * 12;
    const stampCount = receipts.filter((rc) => rc.needsStamp).length;
    const r = {
      tenantName: input.tenantName.trim(),
      landlordName: input.landlordName.trim(),
      propertyAddress: input.propertyAddress.trim(),
      monthlyRent: input.monthlyRent,
      paymentMode: input.paymentMode,
      paymentModeLabel: RENT_RECEIPT_PAYMENT_MODE_LABELS[input.paymentMode],
      landlordPan: input.landlordPan,
      startMonth: input.startMonth,
      months: input.months,
      receipts: receipts,
      totalRent: totalRent,
      totalWords: rentReceiptAmountWords(totalRent),
      annualisedRent: annualisedRent,
      panRequired: annualisedRent > RENT_RECEIPT_PAN_THRESHOLD,
      stampCount: stampCount,
      startLabel: receipts[0].monthLabel,
      endLabel: receipts[receipts.length - 1].monthLabel,
      notes: []
    };
    r.notes = rentReceiptNotes(r);
    return r;
  }

  const RENT_RECEIPT_KEYS = ["tenantName", "landlordName", "propertyAddress", "monthlyRent", "paymentMode", "landlordPan", "startMonth", "months"];

  const RENT_RECEIPT_PAYMENT_MODES = ["bank", "upi", "cash", "cheque"];

  const RENT_RECEIPT_PAYMENT_MODE_LABELS = { "bank": "Bank transfer", "upi": "UPI", "cash": "Cash", "cheque": "Cheque" };

  const RENT_RECEIPT_MONTH_NAMES = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];

  const RENT_RECEIPT_ONES = ["Zero", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine", "Ten", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen"];

  const RENT_RECEIPT_TENS = ["", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"];

  const RENT_RECEIPT_RENT_MIN = 100;

  const RENT_RECEIPT_RENT_MAX = 1000000;

  const RENT_RECEIPT_MONTHS_MIN = 1;

  const RENT_RECEIPT_MONTHS_MAX = 12;

  const RENT_RECEIPT_NAME_MIN = 1;

  const RENT_RECEIPT_NAME_MAX = 100;

  const RENT_RECEIPT_ADDRESS_MIN = 1;

  const RENT_RECEIPT_ADDRESS_MAX = 200;

  const RENT_RECEIPT_START_YEAR_MIN = 2000;

  const RENT_RECEIPT_START_YEAR_MAX = 2100;

  const RENT_RECEIPT_PAN_THRESHOLD = 100000;

  const RENT_RECEIPT_STAMP_THRESHOLD = 5000;

  const RENT_RECEIPT_STAMP_DUTY = 1;

  const RENT_RECEIPT_PAN_RE = /^[A-Z]{5}[0-9]{4}[A-Z]$/;

  // Grouped 2dp money (₹6.87): composes the pure helpers — Fmt2 for
  // the paise, FmtINR for the Indian grouping. Not a copy of either.
  function inr2(x) {
    const s = rentReceiptFmt2(x);
    const dot = s.indexOf(".");
    return rentReceiptFmtINR(Number(s.slice(0, dot))) + s.slice(dot);
  }

  const tenantNameEl = $("tenantName");
  const landlordNameEl = $("landlordName");
  const propertyAddressEl = $("propertyAddress");
  const monthlyRentEl = $("monthlyRent");
  const paymentModeEl = $("paymentMode");
  const landlordPanEl = $("landlordPan");
  const startMonthEl = $("startMonth");
  const monthsEl = $("months");
  const presetSelect = $("preset");
  const pill = $("rent-receipt-pill");
  const resultTagMain = $("result-tag-main");
  const resultTagSub = $("result-tag-sub");
  const resultHeading = $("result-heading");
  const output = $("answer");
  const fact1Val = $("rent-receipt-fact1");
  const fact2Val = $("rent-receipt-fact2");
  const fact3Val = $("rent-receipt-fact3");
  const fact4Val = $("rent-receipt-fact4");
  const fact5Val = $("rent-receipt-fact5");
  const fact6Val = $("rent-receipt-fact6");
  const fact1Label = $("rent-receipt-fact1-label");
  const fact2Label = $("rent-receipt-fact2-label");
  const fact3Label = $("rent-receipt-fact3-label");
  const fact4Label = $("rent-receipt-fact4-label");
  const fact5Label = $("rent-receipt-fact5-label");
  const fact6Label = $("rent-receipt-fact6-label");
  const linesBody = $("rent-receipt-lines-body");
  const linesWrap = $("rent-receipt-lines-wrap");
  const scheduleNote = $("rent-receipt-schedule-note");
  const glanceBox = $("glance-box");
  const glanceTitle = $("glance-title");
  const glanceText = $("glance-text");
  const verdictEl = $("rent-receipt-verdict-line");
  const working = $("working");
  const workingDown = $("working-down");
  const workingNote = $("working-note");
  const notesEl = $("rent-receipt-notes");
  const formError = $("calc-error");
  const status = $("copy-status");
  const copyBox = $("copy-text");
  const copyButton = $("copy-result");
  const history = [];

  // Limits are the CONTRACT limits (names 1-100 chars, address
  // 1-200 chars, monthly rent a whole number from Rs 100 to
  // Rs 10,00,000, PAN empty or AAAAA9999A, start month YYYY-MM
  // 2000-2100, months 1-12).
  const PAYMENT_MODES = ["bank", "upi", "cash", "cheque"];
  const PAN_RE = /^[A-Z]{5}[0-9]{4}[A-Z]$/;

  function setError(id, msg) {
    const err = $(id + "-error");
    if (err) err.textContent = msg;
  }

  function setFormError(msg) {
    if (formError) formError.textContent = msg;
  }

  function paymentModeLabel(mode) {
    if (mode === "upi") return "UPI";
    if (mode === "cash") return "Cash";
    if (mode === "cheque") return "Cheque";
    return "Bank transfer";
  }

  function readSelect(el, id, allowed, label) {
    const v = el.value;
    if (!allowed.includes(v)) {
      setError(id, "Pick " + label + ".");
      return null;
    }
    setError(id, "");
    return v;
  }

  function readText(el, id, min, max, label) {
    const v = el.value.trim();
    if (v.length < min || v.length > max) {
      setError(id, label + " must be " + min + " to " + max + " characters.");
      return null;
    }
    setError(id, "");
    return v;
  }

  function readNum(el, id, min, max, label, integerOnly) {
    const raw = el.value.trim();
    if (raw === "") {
      setError(id, "Enter " + label + ".");
      return null;
    }
    const v = Number(raw);
    if (!Number.isFinite(v) || (integerOnly && !Number.isInteger(v)) || v < min || v > max) {
      setError(id, label + " must be a number between " + min + " and " + max + ".");
      return null;
    }
    setError(id, "");
    return v;
  }

  function readPan(el, id) {
    const v = el.value.trim().toUpperCase();
    el.value = v;
    if (v === "") {
      setError(id, "");
      return "";
    }
    if (!PAN_RE.test(v)) {
      setError(id, "PAN must be 10 characters: 5 letters, 4 digits, 1 letter (e.g. ABCDE1234F).");
      return null;
    }
    setError(id, "");
    return v;
  }

  function readStartMonth(el, id) {
    const v = el.value.trim();
    if (rentReceiptParseStartMonth(v) === null) {
      setError(id, "Pick a start month (YYYY-MM, 2000–2100).");
      return null;
    }
    setError(id, "");
    return v;
  }

  function readInputs() {
    const input = {};
    let ok = true;
    const tenantName = readText(tenantNameEl, "tenantName", 1, 100, "the tenant's name");
    if (tenantName === null) ok = false;
    input.tenantName = tenantName === null ? "" : tenantName;
    const landlordName = readText(landlordNameEl, "landlordName", 1, 100, "the landlord's name");
    if (landlordName === null) ok = false;
    input.landlordName = landlordName === null ? "" : landlordName;
    const propertyAddress = readText(propertyAddressEl, "propertyAddress", 1, 200, "the property address");
    if (propertyAddress === null) ok = false;
    input.propertyAddress = propertyAddress === null ? "" : propertyAddress;
    const monthlyRent = readNum(monthlyRentEl, "monthlyRent", 100, 1000000, "the monthly rent in whole rupees", true);
    if (monthlyRent === null) ok = false;
    input.monthlyRent = monthlyRent === null ? 0 : monthlyRent;
    const paymentMode = readSelect(paymentModeEl, "paymentMode", PAYMENT_MODES, "bank transfer, UPI, cash or cheque");
    if (paymentMode === null) ok = false;
    input.paymentMode = paymentMode === null ? "bank" : paymentMode;
    const landlordPan = readPan(landlordPanEl, "landlordPan");
    if (landlordPan === null) ok = false;
    input.landlordPan = landlordPan === null ? "" : landlordPan;
    const startMonth = readStartMonth(startMonthEl, "startMonth");
    if (startMonth === null) ok = false;
    input.startMonth = startMonth === null ? "2026-04" : startMonth;
    const months = readNum(monthsEl, "months", 1, 12, "the number of months", true);
    if (months === null) ok = false;
    input.months = months === null ? 0 : months;
    return ok ? input : null;
  }

  function escapeText(s) {
    return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
  }

  function receiptBoxHtml(r, rc) {
    const panLine = r.landlordPan
      ? "<p>Landlord: " + escapeText(r.landlordName) + " — PAN: " + escapeText(r.landlordPan) + "</p>"
      : "<p>Landlord: " + escapeText(r.landlordName) + "</p>";
    const stamp = rc.needsStamp
      ? '<div class="receipt-stamp">Revenue Stamp ₹1 — affix here and sign across it</div>'
      : "";
    return `<article class="receipt-box">
      <div class="receipt-head"><span>RENT RECEIPT</span><span>Receipt No. ${rc.numberLabel}</span><span>Date: ${escapeText(rc.date)}</span></div>
      <div class="receipt-body">
        <p>Received with thanks from <strong>${escapeText(r.tenantName)}</strong> the sum of <strong>₹${rentReceiptFmtINR(rc.amount)} (${escapeText(rc.amountWords)})</strong> being the rent for <strong>${escapeText(rc.monthLabel)}</strong> (${escapeText(rc.periodStart)} to ${escapeText(rc.periodEnd)}) towards the property <strong>${escapeText(r.propertyAddress)}</strong>, paid by <strong>${escapeText(r.paymentModeLabel)}</strong>.</p>
        ${panLine}
        ${stamp}
        <p class="receipt-sign">Signature of Landlord / Owner: ___________________</p>
      </div>
    </article>`;
  }

  function clearResult() {
    output.textContent = "—";
    resultHeading.textContent = "—";
    resultTagSub.textContent = "Enter your details to generate your receipts.";
    fact1Val.textContent = "—";
    fact2Val.textContent = "—";
    fact3Val.textContent = "—";
    fact4Val.textContent = "—";
    fact5Val.textContent = "—";
    fact6Val.textContent = "—";
    linesBody.innerHTML = "";
    scheduleNote.textContent = "";
    glanceText.textContent = "Enter your details to generate your receipts.";
    verdictEl.textContent = "";
    working.textContent = "";
    workingDown.textContent = "";
    workingNote.textContent = "";
    notesEl.innerHTML = "";
    pill.textContent = "—";
  }

  function panText(r) {
    return r.panRequired ? "PAN required" : "PAN not required";
  }

  function stampText(r) {
    if (r.stampCount === 0) return "No stamp";
    return r.stampCount + (r.stampCount === 1 ? " stamp box" : " stamp boxes");
  }

  function renderReceipts(r) {
    linesBody.innerHTML = r.receipts.map(rc => receiptBoxHtml(r, rc)).join("");
    scheduleNote.textContent = r.stampCount > 0
      ? r.stampCount + (r.stampCount === 1 ? " receipt carries" : " receipts carry") + " a ₹1 revenue-stamp box — sign across the stamp."
      : "No revenue stamp is needed on these receipts.";
    linesWrap.hidden = false;
  }

  function renderResult(r, input) {
    const tagMain = (r.months + (r.months === 1 ? " RECEIPT" : " RECEIPTS") + " · " + r.startLabel.toUpperCase() + " – " + r.endLabel.toUpperCase() + " · ₹" + rentReceiptFmtINR(r.totalRent) + " TOTAL").toUpperCase();
    const tagSub = (input.tenantName.toUpperCase() + " → " + input.landlordName.toUpperCase() + " · ₹" + rentReceiptFmtINR(r.monthlyRent) + " A MONTH · " + r.paymentModeLabel.toUpperCase());
    const heading = r.months + (r.months === 1 ? " rent receipt" : " rent receipts") + " — ₹" + rentReceiptFmtINR(r.totalRent) + " in total";
    const answerText = r.months + (r.months === 1 ? " receipt" : " receipts") + ", " + r.startLabel + " to " + r.endLabel + " — ₹" + rentReceiptFmtINR(r.totalRent) + " in total (" + r.totalWords + ").";
    const workingText = "₹" + rentReceiptFmtINR(r.monthlyRent) + " a month × " + r.months + (r.months === 1 ? " month" : " months") + " = ₹" + rentReceiptFmtINR(r.totalRent) + ". Each receipt is dated at the end of its month — " + r.receipts[0].date + " for " + r.receipts[0].monthLabel + (r.months > 1 ? " to " + r.receipts[r.receipts.length - 1].date + " for " + r.receipts[r.receipts.length - 1].monthLabel : "") + ".";
    const panLine = r.panRequired
      ? "Landlord PAN is required — the rent for a full year at ₹" + rentReceiptFmtINR(r.monthlyRent) + " a month is ₹" + rentReceiptFmtINR(r.annualisedRent) + ", over the ₹1,00,000 limit."
      : "Landlord PAN is not required — the rent for a full year at ₹" + rentReceiptFmtINR(r.monthlyRent) + " a month is ₹" + rentReceiptFmtINR(r.annualisedRent) + ", under the ₹1,00,000 limit.";
    const stampLine = r.paymentMode === "cash"
      ? (r.stampCount > 0
        ? "Cash payment over ₹5,000 a receipt, so " + (r.stampCount === 1 ? "the receipt carries" : "each of the " + r.stampCount + " receipts carries") + " a ₹1 revenue-stamp box."
        : "Cash payment, but ₹" + rentReceiptFmtINR(r.monthlyRent) + " a receipt is not over the ₹5,000 limit, so no revenue stamp is needed.")
      : "Paid by " + r.paymentModeLabel.toLowerCase() + ", so no revenue stamp is shown on these receipts.";
    resultTagMain.textContent = tagMain;
    pill.textContent = tagMain;
    resultHeading.textContent = heading;
    output.textContent = answerText;
    resultTagSub.textContent = tagSub;
    fact1Label.textContent = "Receipts";
    fact2Label.textContent = "Period";
    fact3Label.textContent = "Monthly rent";
    fact4Label.textContent = "Total rent";
    fact5Label.textContent = "Landlord PAN";
    fact6Label.textContent = "Revenue stamps";
    fact1Val.textContent = String(r.months);
    fact2Val.textContent = r.startLabel + " – " + r.endLabel;
    fact3Val.textContent = "₹" + rentReceiptFmtINR(r.monthlyRent);
    fact4Val.textContent = "₹" + rentReceiptFmtINR(r.totalRent);
    fact5Val.textContent = panText(r);
    fact6Val.textContent = stampText(r);
    glanceTitle.textContent = heading;
    glanceText.textContent = heading + ". " + answerText + " " + panLine;
    verdictEl.textContent = panLine;
    working.textContent = workingText;
    workingDown.textContent = stampLine;
    workingNote.textContent = "Total in words: " + r.totalWords + ". " + panLine + " " + stampLine;
    const notes = (r.notes && r.notes.length) ? r.notes : rentReceiptNotes(r);
    notesEl.innerHTML = notes.map(n => "<li>" + escapeText(n) + "</li>").join("");
    renderReceipts(r);
    setFormError("");
  }

  function compute() {
    const input = readInputs();
    if (!input) { clearResult(); return null; }
    if (!rentReceiptValid(input)) {
      setFormError("Check the details — one of them is outside the range this generator covers.");
      clearResult();
      return null;
    }
    const r = rentReceiptCompute(input);
    if (!r) {
      setFormError("Check the details — one of them is outside the range this generator covers.");
      clearResult();
      return null;
    }
    return { input, r };
  }

  function applyPreset(id) {
    const pr = c.presets.find(p => p.id === id);
    if (!pr) return;
    applyPresetFromInput(pr);
    presetSelect.value = pr.id;
  }

  function applyPresetFromInput(inp) {
    tenantNameEl.value = inp.tenantName;
    landlordNameEl.value = inp.landlordName;
    propertyAddressEl.value = inp.propertyAddress;
    monthlyRentEl.value = inp.monthlyRent;
    paymentModeEl.value = inp.paymentMode;
    landlordPanEl.value = inp.landlordPan;
    startMonthEl.value = inp.startMonth;
    monthsEl.value = inp.months;
  }

  function historyLabel(cur) {
    const { r, input } = cur;
    return r.months + (r.months === 1 ? " receipt" : " receipts") + " · ₹" + rentReceiptFmtINR(r.totalRent) + " · " + input.tenantName + " → " + input.landlordName + " · " + r.startLabel;
  }

  function pushHistory(label) {
    const cur = compute();
    if (!cur) return;
    history.unshift({ label, input: cur.input, r: cur.r });
    if (history.length > 5) history.pop();
    renderHistory();
  }

  function renderHistory() {
    const list = $("history-list");
    const empty = $("history-empty");
    const clear = $("clear-history");
    if (!history.length) {
      list.innerHTML = "";
      empty.hidden = false;
      clear.disabled = true;
      return;
    }
    empty.hidden = true;
    clear.disabled = false;
    list.innerHTML = history.map((h, i) => `
      <button class="history-item" type="button" data-history="${i}">${escapeText(h.label)}</button>`).join("");
    list.querySelectorAll("[data-history]").forEach(btn => {
      btn.addEventListener("click", () => {
        const h = history[Number(btn.getAttribute("data-history"))];
        if (!h) return;
        applyPresetFromInput(h.input);
        presetSelect.value = "custom";
        renderResult(h.r, h.input);
      });
    });
  }

  function copyTextFor(cur) {
    const { r, input } = cur;
    let text = "Rent Receipt Generator — " + r.months + (r.months === 1 ? " receipt" : " receipts") + ", " + r.startLabel + " to " + r.endLabel + ": ₹" + rentReceiptFmtINR(r.totalRent) + " in total (" + r.totalWords + "), ₹" + rentReceiptFmtINR(r.monthlyRent) + " a month, " + input.tenantName + " to " + input.landlordName + ", paid by " + r.paymentModeLabel.toLowerCase() + ".";
    text += " " + panText(r) + "; " + stampText(r) + ".";
    return text + " visitbest.in/rent-receipt-generator/";
  }

  function setFinancialYear() {
    const now = new Date();
    const fyStartYear = now.getMonth() >= 3 ? now.getFullYear() : now.getFullYear() - 1;
    startMonthEl.value = fyStartYear + "-04";
    monthsEl.value = 12;
    presetSelect.value = "custom";
    const cur = compute();
    if (cur) renderResult(cur.r, cur.input);
  }

  const form = $("rent-receipt-form");
  form.addEventListener("submit", ev => {
    ev.preventDefault();
    const cur = compute();
    if (!cur) return;
    renderResult(cur.r, cur.input);
    pushHistory(historyLabel(cur));
    $("result").focus();
  });
  presetSelect.addEventListener("change", () => {
    if (presetSelect.value === "custom") return;
    applyPreset(presetSelect.value);
    const cur = compute();
    if (cur) renderResult(cur.r, cur.input);
  });
  landlordPanEl.addEventListener("change", () => {
    landlordPanEl.value = landlordPanEl.value.trim().toUpperCase();
  });
  $("fy-year").addEventListener("click", () => {
    setFinancialYear();
    $("result").focus();
  });
  $("print-receipts").addEventListener("click", () => {
    const cur = compute();
    if (!cur) return;
    renderResult(cur.r, cur.input);
    window.print();
  });
  [tenantNameEl, landlordNameEl, propertyAddressEl, monthlyRentEl, paymentModeEl, landlordPanEl, startMonthEl, monthsEl].forEach(el => {
    el.addEventListener("change", () => {
      presetSelect.value = "custom";
      const cur = compute();
      if (cur) renderResult(cur.r, cur.input);
    });
  });
  document.querySelectorAll("[data-preset]").forEach(btn => {
    btn.addEventListener("click", () => {
      applyPreset(btn.getAttribute("data-preset"));
      const cur = compute();
      if (cur) renderResult(cur.r, cur.input);
      $("result").focus();
    });
  });
  copyButton.addEventListener("click", () => {
    const cur = compute();
    if (!cur) return;
    const text = copyTextFor(cur);
    copyBox.value = text;
    copyBox.select();
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(() => {
        status.textContent = "Copied.";
      }).catch(() => {
        status.textContent = "Copy the text below.";
      });
    } else {
      document.execCommand("copy");
      status.textContent = "Copied.";
    }
  });
  $("clear-history").addEventListener("click", () => {
    history.length = 0;
    renderHistory();
  });
  $("reset").addEventListener("click", () => {
    applyPreset(c.defaultPreset);
    const cur = compute();
    if (cur) renderResult(cur.r, cur.input);
  });
  const initial = compute();
  if (initial) renderResult(initial.r, initial.input);
}

export function renderRentReceiptGeneratorBody(p, others, css, clientSource) {
  const e = escapeHTML;
  const safeJSON = v => JSON.stringify(v).replace(/</g, "\\u003c");
  // Presets and stories carry extra fields (id, label, title, body, …);
  // rentReceiptCompute accepts exactly the 8 RENT_RECEIPT_KEYS, so strip to those first.
  const rentReceiptInput = obj => ({ tenantName: obj.tenantName, landlordName: obj.landlordName, propertyAddress: obj.propertyAddress, monthlyRent: obj.monthlyRent, paymentMode: obj.paymentMode, landlordPan: obj.landlordPan, startMonth: obj.startMonth, months: obj.months });

  // Grouped 2dp money (₹6.87): composes the pure helpers — Fmt2 for
  // the paise, FmtINR for the Indian grouping. Not a copy of either.
  const inr2 = x => {
    const s = rentReceiptFmt2(x);
    const dot = s.indexOf(".");
    return rentReceiptFmtINR(Number(s.slice(0, dot))) + s.slice(dot);
  };

  const config = { key: p.key, title: p.title, presets: p.presets, defaultPreset: p.defaultPreset, sample: p.sample };
  const sample = rentReceiptCompute(rentReceiptInput(p.sample));

  const paymentModeLabel = mode => {
    if (mode === "upi") return "UPI";
    if (mode === "cash") return "Cash";
    if (mode === "cheque") return "Cheque";
    return "Bank transfer";
  };
  const panText = r => r.panRequired ? "PAN required" : "PAN not required";
  const stampText = r => {
    if (r.stampCount === 0) return "No stamp";
    return r.stampCount + (r.stampCount === 1 ? " stamp box" : " stamp boxes");
  };

  const receiptBoxHtml = (r, rc) => {
    const panLine = r.landlordPan
      ? `<p>Landlord: ${e(r.landlordName)} — PAN: ${e(r.landlordPan)}</p>`
      : `<p>Landlord: ${e(r.landlordName)}</p>`;
    const stamp = rc.needsStamp
      ? `<div class="receipt-stamp">Revenue Stamp ₹1 — affix here and sign across it</div>`
      : "";
    return `<article class="receipt-box">
      <div class="receipt-head"><span>RENT RECEIPT</span><span>Receipt No. ${rc.numberLabel}</span><span>Date: ${e(rc.date)}</span></div>
      <div class="receipt-body">
        <p>Received with thanks from <strong>${e(r.tenantName)}</strong> the sum of <strong>₹${rentReceiptFmtINR(rc.amount)} (${e(rc.amountWords)})</strong> being the rent for <strong>${e(rc.monthLabel)}</strong> (${e(rc.periodStart)} to ${e(rc.periodEnd)}) towards the property <strong>${e(r.propertyAddress)}</strong>, paid by <strong>${e(r.paymentModeLabel)}</strong>.</p>
        ${panLine}
        ${stamp}
        <p class="receipt-sign">Signature of Landlord / Owner: ___________________</p>
      </div>
    </article>`;
  };

  const resultLine = (r, input) => {
    if (!r) return "";
    return r.months + (r.months === 1 ? " receipt" : " receipts") + " · " + r.startLabel + " to " + r.endLabel + " · ₹" + rentReceiptFmtINR(r.totalRent) + " total · " + panText(r) + " · " + stampText(r) + ".";
  };

  const presetSummary = pr => {
    const r = rentReceiptCompute(rentReceiptInput(pr));
    if (!r) return "—";
    return "→ " + resultLine(r, pr);
  };
  const presetOptions = p.presets.map(pr => `
    <option value="${e(pr.id)}"${pr.id === p.defaultPreset ? " selected" : ""}>${e(pr.label)} — ${presetSummary(pr)}</option>
  `).join("");

  const sampleAnswer = `${sample.months} receipts, ${sample.startLabel} to ${sample.endLabel} — ₹${rentReceiptFmtINR(sample.totalRent)} in total (${sample.totalWords}).`;
  const sampleAnswerSmall = `${p.sample.tenantName} → ${p.sample.landlordName} · ₹${rentReceiptFmtINR(p.sample.monthlyRent)} a month · ${paymentModeLabel(p.sample.paymentMode)} · PAN ${p.sample.landlordPan}`;
  const sampleTagMain = `${sample.months} RECEIPTS · ${sample.startLabel.toUpperCase()} – ${sample.endLabel.toUpperCase()} · ₹${rentReceiptFmtINR(sample.totalRent)} TOTAL`;
  const sampleTagSub = `${p.sample.tenantName.toUpperCase()} → ${p.sample.landlordName.toUpperCase()} · ₹${rentReceiptFmtINR(p.sample.monthlyRent)} A MONTH · ${paymentModeLabel(p.sample.paymentMode).toUpperCase()}`;
  const sampleHeading = `${sample.months} rent receipts — ₹${rentReceiptFmtINR(sample.totalRent)} in total`;
  const sampleWorking = `₹${rentReceiptFmtINR(p.sample.monthlyRent)} a month × ${sample.months} months = ₹${rentReceiptFmtINR(sample.totalRent)}. Each receipt is dated at the end of its month — ${sample.receipts[0].date} for ${sample.receipts[0].monthLabel} to ${sample.receipts[sample.receipts.length - 1].date} for ${sample.receipts[sample.receipts.length - 1].monthLabel}.`;
  const samplePan = sample.panRequired
    ? `Landlord PAN is required — the rent for a full year at ₹${rentReceiptFmtINR(p.sample.monthlyRent)} a month is ₹${rentReceiptFmtINR(sample.annualisedRent)}, over the ₹1,00,000 limit.`
    : `Landlord PAN is not required — the rent for a full year at ₹${rentReceiptFmtINR(p.sample.monthlyRent)} a month is ₹${rentReceiptFmtINR(sample.annualisedRent)}, under the ₹1,00,000 limit.`;
  const sampleStamp = sample.paymentMode === "cash"
    ? (sample.stampCount > 0
      ? `Cash payment over ₹5,000 a receipt, so each of the ${sample.stampCount} receipts carries a ₹1 revenue-stamp box.`
      : `Cash payment, but ₹${rentReceiptFmtINR(p.sample.monthlyRent)} a receipt is not over the ₹5,000 limit, so no revenue stamp is needed.`)
    : `Paid by ${paymentModeLabel(sample.paymentMode).toLowerCase()}, so no revenue stamp is shown on these receipts.`;
  const sampleTotalWords = `Total in words: ${sample.totalWords}. ${samplePan} ${sampleStamp}`;
  const glanceText = `${sampleHeading}. ${sampleAnswer} ${samplePan}`;

  const sampleReceiptRows = sample.receipts.map(rc => `
      <tr><td>${rc.numberLabel}</td><td>${e(rc.monthLabel)}</td><td>${e(rc.date)}</td><td>₹${rentReceiptFmtINR(rc.amount)}</td><td>${e(rc.amountWords)}</td><td>${rc.needsStamp ? "₹1 stamp" : "—"}</td></tr>`).join("");
  const sampleReceiptBoxes = sample.receipts.map(rc => receiptBoxHtml(sample, rc)).join("");

  // Tool-switch nav: every other calculator from `others`, plus this
  // page itself (aria-current) — 100 links once this page is added.
  // `others` excludes this page, so filter defensively and append it.
  const navOthers = others.filter(item => item.slug !== p.slug);
  const navLinks = navOthers.map(item => `<a href="/${e(item.slug)}/">${e(item.title)}</a>`).join("\n              ") + `\n              <a href="/rent-receipt-generator/" aria-current="page">Rent Receipt Generator</a>`;

  // Related tools: ONLY the 10 calculators verified live (HTTP 200)
  // on 15 November 2026. Titles come from `others` where available.
  const relatedTools = [
    { slug: "hra-calculator", title: "HRA Calculator" },
    { slug: "income-tax-calculator", title: "Income Tax Calculator" },
    { slug: "emi-calculator", title: "EMI Calculator" },
    { slug: "percentage-calculator", title: "Percentage Calculator" },
    { slug: "gst-calculator", title: "GST Calculator" },
    { slug: "cgpa-to-percentage-calculator", title: "CGPA Calculator" },
    { slug: "bmi-calculator", title: "BMI Calculator" },
    { slug: "sip-calculator", title: "SIP Calculator" },
    { slug: "fd-calculator", title: "FD Calculator" },
    { slug: "ppf-calculator", title: "PPF Calculator" }
  ];
  const relatedLinks = relatedTools.map(tool => {
    const found = others.find(item => item.slug === tool.slug);
    const title = found ? found.title : tool.title;
    return `<a href="/${e(tool.slug)}/">${e(title)}</a>`;
  }).join("\n          ");

  return `<div class="calc-page">
    <div class="calc-wrap">
        <nav class="breadcrumbs" aria-label="Breadcrumb">
          <a href="/">Home</a>
          <span class="sep">/</span>
          <span>${e(p.title)}</span>
        </nav>

        <div class="hero-grid">
          <div class="hero-copy">
            <p class="eyebrow">Free rent receipt generator</p>
            <h1 class="calc-title">${e(p.title)}</h1>
            <p class="calc-lead">${e(p.lead)}</p>

            <div class="benefits">
              <span>✓ Free to use</span>
              <span>✓ No signup</span>
              <span>✓ Browser calculation</span>
            </div>

            <div class="hero-links">
              <a class="calc-btn calc-btn-primary" href="#calculator">
                How do I make rent receipts for my HRA claim? →
              </a>
              <a href="#methodology" class="calc-link">How the receipts are worked out ↓</a>
            </div>

            <div class="facts">
              <div>
                <strong>${sample.months} receipts for ₹${rentReceiptFmtINR(sample.totalRent)} on the sample</strong>
                <small>On the sample: ${p.sample.tenantName} pays ${p.sample.landlordName} ₹${rentReceiptFmtINR(p.sample.monthlyRent)} a month by ${paymentModeLabel(p.sample.paymentMode).toLowerCase()}, ${sample.startLabel} to ${sample.endLabel} — ₹${rentReceiptFmtINR(sample.totalRent)} in total, ${sample.totalWords}</small>
              </div>
              <div>
                <strong>${panText(sample)} · ${stampText(sample)}</strong>
                <small>The rent for a full year is ₹${rentReceiptFmtINR(sample.annualisedRent)}, over the ₹1,00,000 limit — so the landlord's PAN goes on every receipt. Paid by ${paymentModeLabel(sample.paymentMode).toLowerCase()}, so no revenue stamp.</small>
              </div>
              <div>
                <strong>Checked 15 November 2026</strong>
                <small>See the methodology at the foot of the page</small>
              </div>
            </div>

            <p class="scope-note">
              <strong>Receipts, not an exemption calculation.</strong>
              These receipts prove the rent was paid; the HRA exemption is the least of three figures and only in the old regime — the HRA Calculator, linked below, works that out.
            </p>
          </div>

          <section class="calculator" id="calculator" aria-labelledby="tool-heading">
            <h2 id="tool-heading">Make your rent receipts for the year</h2>
            <form id="rent-receipt-form" novalidate>
              <div class="field">
                <label for="preset">Try a preset</label>
                <select id="preset" name="preset">
                  ${presetOptions}
                  <option value="custom">Custom — my own details</option>
                </select>
              </div>
              <div class="field-grid">
                <div class="field">
                  <label for="tenantName">Tenant's name</label>
                  <input id="tenantName" name="tenantName" type="text" maxlength="100" value="Asha Verma">
                  <p class="field-error" id="tenantName-error" role="alert"></p>
                  <p class="field-hint">Who paid the rent, as on the rent agreement.</p>
                </div>
                <div class="field">
                  <label for="landlordName">Landlord's name</label>
                  <input id="landlordName" name="landlordName" type="text" maxlength="100" value="Rajesh Kumar">
                  <p class="field-error" id="landlordName-error" role="alert"></p>
                  <p class="field-hint">Who received the rent, as on the rent agreement.</p>
                </div>
              </div>
              <div class="field">
                <label for="propertyAddress">Property address</label>
                <input id="propertyAddress" name="propertyAddress" type="text" maxlength="200" value="Flat 302, Sunrise Apartments, Andheri West, Mumbai 400053">
                <p class="field-error" id="propertyAddress-error" role="alert"></p>
                <p class="field-hint">The full address of the rented property, as on the agreement.</p>
              </div>
              <div class="field-grid">
                <div class="field">
                  <label for="monthlyRent">Monthly rent (₹)</label>
                  <input id="monthlyRent" name="monthlyRent" type="number" min="100" max="1000000" step="1" value="12500" inputmode="numeric">
                  <p class="field-error" id="monthlyRent-error" role="alert"></p>
                  <p class="field-hint">Whole rupees only (₹100–₹10,00,000 a month). No paise.</p>
                </div>
                <div class="field">
                  <label for="paymentMode">How was it paid?</label>
                  <select id="paymentMode" name="paymentMode">
                    <option value="bank" selected>Bank transfer</option>
                    <option value="upi">UPI</option>
                    <option value="cash">Cash</option>
                    <option value="cheque">Cheque</option>
                  </select>
                  <p class="field-error" id="paymentMode-error" role="alert"></p>
                  <p class="field-hint">Cash over ₹5,000 a receipt adds a ₹1 revenue-stamp box; the other modes do not.</p>
                </div>
              </div>
              <div class="field-grid">
                <div class="field">
                  <label for="landlordPan">Landlord's PAN (optional)</label>
                  <input id="landlordPan" name="landlordPan" type="text" maxlength="10" value="ABCDE1234F" autocapitalize="characters" spellcheck="false">
                  <p class="field-error" id="landlordPan-error" role="alert"></p>
                  <p class="field-hint">10 characters: 5 letters, 4 digits, 1 letter. Required when the rent for a full year is over ₹1,00,000 — leave it blank otherwise.</p>
                </div>
                <div class="field">
                  <label for="months">Number of months</label>
                  <input id="months" name="months" type="number" min="1" max="12" step="1" value="12" inputmode="numeric">
                  <p class="field-error" id="months-error" role="alert"></p>
                  <p class="field-hint">1–12 months. One receipt is made per month.</p>
                </div>
              </div>
              <div class="field-grid">
                <div class="field">
                  <label for="startMonth">Start month</label>
                  <input id="startMonth" name="startMonth" type="month" min="2000-01" max="2100-12" value="2026-04">
                  <p class="field-error" id="startMonth-error" role="alert"></p>
                  <p class="field-hint">The first month of the set. Each receipt is dated at the end of its own month.</p>
                </div>
                <div class="field">
                  <button class="calc-btn" type="button" id="fy-year">Full financial year (April–March)</button>
                  <p class="field-hint">Sets the start month to April and the number of months to 12, for the current financial year.</p>
                </div>
              </div>
              <p class="field-error calc-error" id="calc-error" role="alert"></p>
              <div class="field-grid">
                <div class="field">
                  <p class="field-hint" style="margin-top: 26px;">The generator runs entirely in your browser — nothing you type is sent or saved.</p>
                </div>
                <div class="field">
                  <p class="field-hint" style="margin-top: 26px;">The PAN flag tests the rent for a full year (monthly rent × 12) against ₹1,00,000; the stamp box appears only on cash receipts over ₹5,000.</p>
                </div>
              </div>
              <button class="calc-btn" type="submit" id="calculate">Generate rent receipts</button>
              <button class="calc-btn" type="button" id="print-receipts">Print receipts</button>
              <button class="calc-btn" type="button" id="reset">Reset</button>
            </form>
            <div class="result" id="result" tabindex="-1" aria-live="polite">
              <p class="result-pill" id="rent-receipt-pill">${sampleTagMain}</p>
              <p class="result-tag" id="result-tag-main">${sampleTagMain}</p>
              <p class="result-tag-sub" id="result-tag-sub">${sampleTagSub}</p>
              <h3 id="result-heading">${e(sampleHeading)}</h3>
              <p class="answer-line"><span id="answer">${sampleAnswer}</span> <small>${sampleAnswerSmall}</small></p>
              <dl class="result-facts">
                <div><dt id="rent-receipt-fact1-label">Receipts</dt><dd id="rent-receipt-fact1">${sample.months}</dd></div>
                <div><dt id="rent-receipt-fact2-label">Period</dt><dd id="rent-receipt-fact2">${sample.startLabel} – ${sample.endLabel}</dd></div>
                <div><dt id="rent-receipt-fact3-label">Monthly rent</dt><dd id="rent-receipt-fact3">₹${rentReceiptFmtINR(sample.monthlyRent)}</dd></div>
                <div><dt id="rent-receipt-fact4-label">Total rent</dt><dd id="rent-receipt-fact4">₹${rentReceiptFmtINR(sample.totalRent)}</dd></div>
                <div><dt id="rent-receipt-fact5-label">Landlord PAN</dt><dd id="rent-receipt-fact5">${panText(sample)}</dd></div>
                <div><dt id="rent-receipt-fact6-label">Revenue stamps</dt><dd id="rent-receipt-fact6">${stampText(sample)}</dd></div>
              </dl>
              <div class="glance" id="glance-box">
                <p class="glance-title" id="glance-title">${e(sampleHeading)}</p>
                <p id="glance-text">${e(glanceText)}</p>
              </div>
              <p class="verdict-line" id="rent-receipt-verdict-line">${e(samplePan)}</p>
              <div class="working" id="working">${e(sampleWorking)}</div>
              <div class="working" id="working-down">${e(sampleStamp)}</div>
              <p class="band-note" id="working-note">${e(sampleTotalWords)}</p>
              <div class="rent-receipt-lines" id="rent-receipt-lines-wrap">
                <div id="rent-receipt-lines-body">${sampleReceiptBoxes}
                </div>
                <p class="field-hint" id="rent-receipt-schedule-note">No revenue stamp is needed on these receipts.</p>
              </div>
              <ul class="checklist" id="rent-receipt-notes">
                ${(sample.notes && sample.notes.length ? sample.notes : rentReceiptNotes(sample)).map(n => `<li>${e(n)}</li>`).join("")}
              </ul>
              <p class="asof-note" id="rent-receipt-asof-note">Figures as of 15 November 2026.</p>
              <div class="copy-row">
                <button class="calc-btn" type="button" id="copy-result">Copy result</button>
                <span class="copy-status" id="copy-status" role="status"></span>
              </div>
              <textarea id="copy-text" class="copy-text" readonly aria-label="Result text to copy"></textarea>
              <div class="history">
                <div class="history-head">
                  <h4>Recent calculations</h4>
                  <button class="calc-btn" type="button" id="clear-history" disabled>Clear</button>
                </div>
                <p id="history-empty">No calculations yet — work one out above.</p>
                <div id="history-list"></div>
              </div>
            </div>
          </section>
        </div>
    </div>

    <section class="calc-section" id="overview">
      <div class="calc-wrap">
        <div class="section-head">
          <h2>${e(p.overviewTitle)}</h2>
        </div>
        <p>${e(p.overview)}</p>
        <p><strong>${e(p.notice)}</strong></p>
      </div>
    </section>

    <section class="calc-section" id="breakdown">
      <div class="calc-wrap">
        <div class="section-head">
          <h2>The sample: ${sample.months} receipts at ₹${rentReceiptFmtINR(p.sample.monthlyRent)} a month — ${e(p.sample.tenantName)} to ${e(p.sample.landlordName)}</h2>
          <p>${e(p.inputNote)}</p>
        </div>
        <div class="rent-receipt-table-wrap">
          <table class="rent-receipt-table">
            <thead><tr><th>No.</th><th>Month</th><th>Date</th><th>Amount</th><th>Amount in words</th><th>Stamp</th></tr></thead>
            <tbody>
              ${sampleReceiptRows}
            </tbody>
          </table>
        </div>
        <p class="field-hint">Total: ₹${rentReceiptFmtINR(sample.totalRent)} (${e(sample.totalWords)}). ${e(samplePan)} ${e(sampleStamp)}</p>
      </div>
    </section>

    <section class="calc-section soft" id="presets">
      <div class="calc-wrap">
        <div class="section-head">
          <h2>Try a preset</h2>
          <p>Twelve worked sets, from a single cash receipt at ₹9,500 to a full financial year at ₹20,000 a month — tap one to load its details into the generator above.</p>
        </div>
        <div class="preset-list">
          ${p.presets.map(pr => `
          <button class="calc-btn" type="button" data-preset="${e(pr.id)}">${e(pr.label)} — ${presetSummary(pr)}</button>`).join("")}
        </div>
      </div>
    </section>

    <section class="calc-section" id="how-to-use">
      <div class="calc-wrap">
        <div class="section-head">
          <h2>How to use this rent receipt generator</h2>
        </div>
        <ol class="steps">
          ${p.steps.map(([t2, d2]) => `
          <li><strong>${e(t2)}.</strong> ${e(d2)}</li>`).join("")}
        </ol>
      </div>
    </section>

    <section class="calc-section" id="rules">
      <div class="calc-wrap">
        <div class="section-head">
          <h2>${e(p.rulesTitle)}</h2>
          <p>${e(p.rulesNote)}</p>
        </div>
        <div class="rent-receipt-table-wrap">
          <table class="rent-receipt-table">
            <thead><tr><th>Rule</th><th>Detail</th></tr></thead>
            <tbody>
              ${p.rulesRows.map(row => `
              <tr>
                <td>${e(row.rule)}</td>
                <td>${e(row.detail)}</td>
              </tr>`).join("")}
            </tbody>
          </table>
        </div>
      </div>
    </section>

    <section class="calc-section soft" id="distinction">
      <div class="calc-wrap">
        <div class="section-head">
          <h2>A rent receipt is not an HRA calculator</h2>
        </div>
        <p>This generator makes receipts. You give it a monthly rent and a period, and it works out one numbered receipt per month, each dated at the end of its month, with the amount in figures and in words, the landlord's PAN where the annual rent crosses ₹1,00,000, and a revenue-stamp box where one applies. The answer is a set of documents.</p>
        <p>An HRA exemption is a different calculation: it takes the receipts and works out the least of three figures — the HRA actually received, 50% of basic plus DA in a metro city (40% elsewhere), and the rent paid minus 10% of basic plus DA — and it only exists in the old tax regime. The HRA Calculator is that separate tool: it takes the rent this page documents and turns it into an exemption figure. Generate first here, then work out the exemption from the total above.</p>
        <p>So the two tools answer different questions. If you need the receipts for your employer, start here. If you already have them — say ₹1,50,000 for the year — the HRA Calculator, linked below, works out how much of it is exempt.</p>
      </div>
    </section>

    <section class="calc-section" id="examples">
      <div class="calc-wrap">
        <div class="section-head">
          <h2>Ten sets, ten answers</h2>
          <p>Ten worked examples — each one reproduced by this generator, except where a difference is stated.</p>
        </div>
        ${p.stories.map(st => {
          const r = rentReceiptCompute(rentReceiptInput(st));
          const line = resultLine(r, st);
          return `
        <article class="story">
          <h3>${e(st.title)}</h3>
          <p>${e(st.body)}</p>
          ${line ? `<p class="story-result">${line}</p>` : ""}
          ${st.tryIt && st.preset ? `<p><button class="calc-btn" type="button" data-preset="${e(st.preset)}">Try these figures →</button></p>` : ""}
        </article>`;
        }).join("")}
      </div>
    </section>

    ${Array.isArray(p.factorRows) && p.factorRows.length ? `
    <section class="calc-section" id="factors">
      <div class="calc-wrap">
        <div class="section-head">
          <h2>${e(p.factorTitle)}</h2>
          <p>${e(p.factorNote)}</p>
        </div>
        <div class="rent-receipt-table-wrap">
          <table class="rent-receipt-table">
            <thead><tr><th>Figure</th><th>How it is worked out</th><th>Typical</th><th>On the sample</th></tr></thead>
            <tbody>
              ${p.factorRows.map(row => `
              <tr>
                <td>${e(row.factor)}</td>
                <td>${e(row.how)}</td>
                <td>${e(row.typical)}</td>
                <td>${e(row.sample)}</td>
              </tr>`).join("")}
            </tbody>
          </table>
        </div>
      </div>
    </section>` : ""}

    ${Array.isArray(p.rateRows) && p.rateRows.length ? `
    <section class="calc-section soft" id="rates">
      <div class="calc-wrap">
        <div class="section-head">
          <h2>${e(p.rateTitle)}</h2>
          <p>${e(p.rateNote)}</p>
        </div>
        <div class="rent-receipt-table-wrap">
          <table class="rent-receipt-table">
            <thead><tr><th>Figure</th><th>Note</th><th>Source</th><th>Typical</th></tr></thead>
            <tbody>
              ${p.rateRows.map(row => `
              <tr>
                <td>${e(row.measure)}</td>
                <td>${e(row.note)}</td>
                <td>${e(row.source)}</td>
                <td>${e(row.typical)}</td>
              </tr>`).join("")}
            </tbody>
          </table>
        </div>
      </div>
    </section>` : ""}

    ${Array.isArray(p.mistakes) && p.mistakes.length ? `
    <section class="calc-section soft" id="mistakes">
      <div class="calc-wrap">
        <div class="section-head">
          <h2>Common rent receipt mistakes to avoid</h2>
        </div>
        <dl class="mistakes">
          ${p.mistakes.map(([label, title, body]) => `
          <div>
            <dt>${e(label)}</dt>
            <dd><strong>${e(title)}</strong> — ${e(body)}</dd>
          </div>`).join("")}
        </dl>
      </div>
    </section>` : ""}

    <section class="calc-section" id="checklist">
      <div class="calc-wrap">
        <div class="section-head">
          <h2>${e(p.checklistTitle)}</h2>
        </div>
        <ul class="checklist">
          ${p.checklist.map(item => `
          <li>${e(item)}</li>`).join("")}
        </ul>
      </div>
    </section>

    <section class="calc-section soft" id="faq">
      <div class="calc-wrap">
        <div class="section-head">
          <h2>Rent receipt generator FAQs</h2>
        </div>
        <dl class="faq">
          ${p.faq.map(([q, a2]) => `
          <div>
            <dt>${e(q)}</dt>
            <dd>${e(a2)}</dd>
          </div>`).join("")}
        </dl>
      </div>
    </section>

    <section class="calc-section" id="methodology">
      <div class="calc-wrap">
        <div class="section-head">
          <h2>Methodology and honest limits</h2>
        </div>
        <p>${e(p.methodology)}</p>
        <p>${e(p.modelNote)}</p>
        <p>Honest limits: a rent receipt proves the rent was paid — it does not decide the HRA exemption, which is the least of three figures under Sec 10(13A) + Rule 2A and only in the old regime. The PAN flag tests the annualised rent (monthly rent × 12) against ₹1,00,000; if your tenancy covers part of a year, the rent actually paid in the year is what your employer looks at. The ₹1 revenue-stamp box appears on cash receipts over ₹5,000 only — the Stamp Act duty attaches to the receipt as an instrument, and the cash-only rule is practice, not the Act text, so ask your employer if they want a stamp on a transfer receipt too. Amounts in words use the Indian system (lakh/crore); rent is whole rupees, so no paise ever appear. The CBDT circular wording is quoted from secondary sources because the circular could not be fetched from an official site, and the FY 2026-27 eight-city HRA change is reported by secondary sources only — re-check the current notification before relying on it. Nothing you type is uploaded or stored: the receipts are generated in your browser.</p>
      </div>
    </section>

    <section class="calc-section cta">
      <div class="calc-wrap">
        <div class="section-head">
          <h2>Plan around the answer — the exemption and the rest</h2>
          <p>
            Try different figures or a different period — or run the same check
            with the related tools for your other plans.
          </p>
        </div>

        <div class="others-row">
          ${relatedLinks}
        </div>
      </div>
    </section>
  </div>

  <script type="application/ld+json">${safeJSON({
    "@context": "https://schema.org",
    "@type": "FAQPage",
    mainEntity: p.faq.map(([name, text]) => ({
      "@type": "Question",
      name,
      acceptedAnswer: { "@type": "Answer", text }
    }))
  })}</script>
  <script>(${clientSource})(${safeJSON(config)});</script>`;
}

// Inverter / Battery Backup Calculator.
// Sizes a home inverter and battery for Indian power cuts: the
// running load from an appliance list, the inverter VA, the backup
// hours from the battery, the battery Ah needed for the wanted
// backup, and the monthly running cost (charging + battery
// replacement + maintenance).
// - Appliance watts (typical Indian ratings, toq.in defaults):
//   ceiling fan 75 W (startup x2), LED bulb 12 W, tube light 20 W,
//   LED TV 100 W, Wi-Fi router 15 W, laptop 65 W, refrigerator
//   180 W (startup x3), air cooler 200 W (startup x2), water pump
//   0.5 HP 750 W (startup x3), plus an "other load" watts field.
// - Running load W = sum of counts x watts + other watts.
// - Surge load W = running load + startup extras (fan +75 each,
//   fridge +360 each, cooler +200 each, pump +1500 each).
// - Inverter VA = running load / 0.8 power factor, rounded UP to
//   the next standard slab: 600 / 850 / 1,100 / 1,600 / 2,000 /
//   2,500 / 3,000 VA (toq.in slab set). Above 3,000 VA the page
//   says the load is above the standard home range and gives the
//   exact VA.
// - Battery usable energy Wh = Ah x volts x derate, derate by
//   chemistry (toq.in): flat plate 0.60, tubular 0.65, LFP 0.75.
//   The derate covers inverter conversion losses and a safe depth
//   of discharge.
// - Backup hours = usable Wh / running load W.
// - Battery Ah needed for the wanted backup = running load x
//   hours / (volts x derate), rounded UP to a standard size:
//   80 / 100 / 120 / 150 / 180 / 200 / 220 Ah. Above 220 Ah the
//   page gives the exact Ah and says a bigger bank (for example
//   two batteries in parallel) is needed.
// - Monthly charging cost: load kWh in the month = running load
//   x outage hours / 1000; grid kWh = load kWh / charging
//   efficiency (0.75 lead-acid, 0.88 LFP — toq.in LFP row);
//   cost = grid kWh x tariff (Rs/kWh, default 6.5).
// - Battery cost a month = (Rs/Ah x Ah) / (life years x 12);
//   Rs/Ah and life by chemistry (toq.in): flat Rs 65/Ah, 3.5 yr;
//   tubular Rs 85/Ah, 5 yr; LFP Rs 180/Ah, 9 yr.
// - Maintenance: Rs 50 a month for lead-acid (distilled water
//   top-ups, about Rs 600 a year — toq.in); Rs 0 for LFP.
// - Monthly total = charging + battery a month + maintenance.
// - Existing inverter check (optional input, 0 = none): available
//   watts = VA x 0.8. "fits" when it covers the surge load,
//   "fits-running-only" when it covers the running load but not
//   the surge, "undersized" otherwise.
// - Verdict: "ok" when the required VA is a standard slab AND the
//   backup meets the wanted hours; "short-backup" when the VA is
//   fine but the backup is shorter than wanted; "oversize" when
//   the load is above the 3,000 VA standard range.
// - All derived figures are computed from the UNROUNDED values;
//   the displayed money fields are rounded to 2dp in the model
//   (whole rupees for display). This is the 370 rule.
// - Documented differences (stated on the page, see math-tests.md):
//   Lentoindia uses a flat 0.80 efficiency with no depth-of-
//   discharge split (150 Ah x 12 V x 0.8 / 250 W = 5.76 hours);
//   this page uses the chemistry derate (tubular 0.65), so the
//   same case gives 4.68 hours. DesiUtility's printed Ah formula
//   gives about 319 Ah for its own 650 W / 4 h example, not the
//   about 135 Ah it quotes; this page follows the formula as
//   printed and gives 333 Ah at the tubular derate. DesiUtility's
//   "4-5 hours" for a 150 Ah tubular battery on a 500-700 W load
//   does not reproduce under its own formula (1.9-2.3 hours) or
//   this page's (1.7-2.3 hours). DesiUtility's 2BHK example uses
//   a 200 W fridge and 9 W LEDs (654 W -> 818 VA); this page
//   uses toq.in's 180 W fridge and 12 W LEDs (657 W -> 821 VA
//   -> 850 VA slab). Bijlibee's usable-energy factor is 0.612
//   (1102 Wh from an 1800 Wh bank); this page uses 0.65 for
//   tubular (1170 Wh, 1.57 hours on a 746 W load against
//   Bijlibee's 1.48 hours on 742 W). Bijlibee sizes the inverter
//   on the surge load (1400 VA); this page sizes on the running
//   load (1100 VA) and warns when the surge exceeds the slab.
//   Toq.in's monthly totals include Rs 50 a month of lead-acid
//   maintenance; this page includes the same Rs 50 and says so.
// - Validation: counts are whole numbers within their ranges
//   (fans 0-10, LED bulbs 0-20, tube lights 0-10, TVs 0-4,
//   routers 0-2, laptops 0-4, fridges 0-2, coolers 0-2, pumps
//   0-1); other watts 0-2000; battery Ah 40-300 (whole);
//   battery volts 12, 24 or 48; battery type flat, tubular or
//   lfp; wanted backup 0.5-12 hours; outage hours 0-300 a month;
//   tariff Rs 1-30 per kWh; existing inverter 0 (none) or
//   600-5000 VA (whole). The running load must be above 0.
//   Invalid inputs return null, never a number.
// - Rounding is round-half-up with a 1e-9 nudge, as in the
//   368/369/370/371/373 pure files.
// - SELF-CONTAINMENT NOTE (15 Nov 2026): every helper in this file
//   is EXPORTED (not a plain module-level helper) so that apply.py
//   copies them into the embedded browser client along with the
//   other pure functions. The 363-367 chain leaves the equivalent
//   helpers behind (e.g. interiorDesignIsBool is referenced by the
//   embedded interiorDesign client but never defined there), so
//   those calculators throw a ReferenceError in the browser when
//   Convert is pressed; this pack must not repeat that.
export const INVB_KEYS = ["fans", "ledBulbs", "tubeLights", "tvs", "routers", "laptops", "fridges", "coolers", "pumps", "otherWatts", "batteryAh", "batteryVolts", "batteryType", "desiredHours", "outageHours", "tariff", "existingVa"];
export const INVB_FANS_MIN = 0;
export const INVB_FANS_MAX = 10;
export const INVB_LED_MIN = 0;
export const INVB_LED_MAX = 20;
export const INVB_TUBE_MIN = 0;
export const INVB_TUBE_MAX = 10;
export const INVB_TV_MIN = 0;
export const INVB_TV_MAX = 4;
export const INVB_ROUTER_MIN = 0;
export const INVB_ROUTER_MAX = 2;
export const INVB_LAPTOP_MIN = 0;
export const INVB_LAPTOP_MAX = 4;
export const INVB_FRIDGE_MIN = 0;
export const INVB_FRIDGE_MAX = 2;
export const INVB_COOLER_MIN = 0;
export const INVB_COOLER_MAX = 2;
export const INVB_PUMP_MIN = 0;
export const INVB_PUMP_MAX = 1;
export const INVB_OTHER_WATTS_MIN = 0;
export const INVB_OTHER_WATTS_MAX = 2000;
export const INVB_BATTERY_AH_MIN = 40;
export const INVB_BATTERY_AH_MAX = 300;
export const INVB_DESIRED_HOURS_MIN = 0.5;
export const INVB_DESIRED_HOURS_MAX = 12;
export const INVB_OUTAGE_HOURS_MIN = 0;
export const INVB_OUTAGE_HOURS_MAX = 300;
export const INVB_TARIFF_MIN = 1;
export const INVB_TARIFF_MAX = 30;
export const INVB_EXISTING_VA_MIN = 600;
export const INVB_EXISTING_VA_MAX = 5000;
export const INVB_POWER_FACTOR = 0.8;
export const INVB_SLABS = [600, 850, 1100, 1600, 2000, 2500, 3000];
export const INVB_STD_AH = [80, 100, 120, 150, 180, 200, 220];
export const INVB_WATTS = { fans: 75, ledBulbs: 12, tubeLights: 20, tvs: 100, routers: 15, laptops: 65, fridges: 180, coolers: 200, pumps: 750 };
export const INVB_SURGE_EXTRA = { fans: 75, fridges: 360, coolers: 200, pumps: 1500 };
export const INVB_DERATE = { flat: 0.60, tubular: 0.65, lfp: 0.75 };
export const INVB_PRICE_PER_AH = { flat: 65, tubular: 85, lfp: 180 };
export const INVB_LIFE_YEARS = { flat: 3.5, tubular: 5, lfp: 9 };
export const INVB_CHARGE_EFF = { flat: 0.75, tubular: 0.75, lfp: 0.88 };
export const INVB_MAINT_PER_MONTH = { flat: 50, tubular: 50, lfp: 0 };
export function invbFmt0(x) {
  return String(Math.round(x + 1e-9));
}
export function invbFmt1(x) {
  return (Math.round(x * 10 + 1e-9) / 10).toFixed(1);
}
export function invbFmt2(x) {
  return (Math.round(x * 100 + 1e-9) / 100).toFixed(2);
}
export function invbFmtNum(x) {
  return String(x);
}
export function invbFmtINR(x) {
  const n = Math.round(x + 1e-9);
  const s = String(n);
  if (s.length <= 3) return s;
  const last3 = s.slice(-3);
  let rest = s.slice(0, -3);
  const parts = [];
  while (rest.length > 2) { parts.unshift(rest.slice(-2)); rest = rest.slice(0, -2); }
  if (rest) parts.unshift(rest);
  return parts.join(",") + "," + last3;
}
export function invbFmtINR2(x) {
  const whole = Math.floor(invbR2(x));
  const frac = Math.round((invbR2(x) - whole) * 100);
  return invbFmtINR(whole) + "." + String(frac).padStart(2, "0");
}
export function invbIsNum(v) {
  return typeof v === "number" && Number.isFinite(v);
}
export function invbIsInt(v) {
  return typeof v === "number" && Number.isInteger(v);
}
export function invbR2(x) {
  return Math.round(x * 100 + 1e-9) / 100;
}
export function invbR1(x) {
  return Math.round(x * 10 + 1e-9) / 10;
}
export function invbR0(x) {
  return Math.round(x + 1e-9);
}
export function invbHoursText(h) {
  if (h === null || h === undefined) return "—";
  const whole = Math.floor(h);
  const mins = Math.round((h - whole) * 60);
  if (mins === 60) return (whole + 1) + " hours";
  if (whole === 0) return mins + " min";
  if (mins === 0) return whole + (whole === 1 ? " hour" : " hours");
  return whole + " h " + mins + " min";
}
export function invbRunningW(input) {
  let total = input.otherWatts;
  for (const k of Object.keys(INVB_WATTS)) total += input[k] * INVB_WATTS[k];
  return total;
}
export function invbSurgeW(input) {
  let total = invbRunningW(input);
  for (const k of Object.keys(INVB_SURGE_EXTRA)) total += input[k] * INVB_SURGE_EXTRA[k];
  return total;
}
export function invbNextSlab(va) {
  for (const s of INVB_SLABS) if (s >= va - 1e-9) return s;
  return null;
}
export function invbNextStdAh(ah) {
  for (const s of INVB_STD_AH) if (s >= ah - 1e-9) return s;
  return null;
}
export function invbNotes(r) {
  const first = "Running load " + invbFmtINR(r.runningW) + " W (surge " + invbFmtINR(r.surgeW) + " W) — inverter " + (r.requiredVa === null ? invbFmtINR(r.requiredVaExact) + " VA, above the standard home range" : invbFmtINR(r.requiredVa) + " VA") + ", backup " + invbFmt1(r.backupHours) + " hours on a " + invbFmtINR(r.batteryAh) + " Ah " + r.batteryType + " battery.";
  let second;
  if (r.requiredAh === null) {
    second = "For " + invbFmt1(r.desiredHours) + " hours of backup you need about " + invbFmt1(r.requiredAhExact) + " Ah at " + invbFmtINR(r.batteryVolts) + " V — above the largest standard size (220 Ah), so a bigger bank is needed.";
  } else {
    second = "For " + invbFmt1(r.desiredHours) + " hours of backup you need about " + invbFmt1(r.requiredAhExact) + " Ah at " + invbFmtINR(r.batteryVolts) + " V — a " + invbFmtINR(r.requiredAh) + " Ah battery.";
  }
  let third;
  if (r.existingVa === 0) {
    third = "Running cost: charging ₹" + invbFmtINR(r.monthlyChargingCost) + " + battery ₹" + invbFmtINR(r.batteryPerMonth) + " + maintenance ₹" + invbFmtINR(r.maintenancePerMonth) + " = ₹" + invbFmtINR(r.monthlyTotal) + " a month (₹" + invbFmtINR(r.yearlyTotal) + " a year).";
  } else if (r.existingVerdict === "fits") {
    third = "Your " + invbFmtINR(r.existingVa) + " VA inverter covers the surge load (" + invbFmtINR(r.availableW) + " W available) — it fits. Running cost ₹" + invbFmtINR(r.monthlyTotal) + " a month.";
  } else if (r.existingVerdict === "fits-running-only") {
    third = "Your " + invbFmtINR(r.existingVa) + " VA inverter covers the running load (" + invbFmtINR(r.availableW) + " W available) but not the " + invbFmtINR(r.surgeW) + " W surge — start motor appliances one at a time. Running cost ₹" + invbFmtINR(r.monthlyTotal) + " a month.";
  } else {
    third = "Your " + invbFmtINR(r.existingVa) + " VA inverter gives only " + invbFmtINR(r.availableW) + " W — too small for a " + invbFmtINR(r.runningW) + " W load. Running cost ₹" + invbFmtINR(r.monthlyTotal) + " a month.";
  }
  return [first, second, third];
}
export function invbValid(input) {
  if (!input || typeof input !== "object" || Array.isArray(input)) return false;
  const keys = Object.keys(input);
  if (keys.length !== INVB_KEYS.length) return false;
  for (const k of INVB_KEYS) if (!keys.includes(k)) return false;
  const counts = [["fans", INVB_FANS_MIN, INVB_FANS_MAX], ["ledBulbs", INVB_LED_MIN, INVB_LED_MAX], ["tubeLights", INVB_TUBE_MIN, INVB_TUBE_MAX], ["tvs", INVB_TV_MIN, INVB_TV_MAX], ["routers", INVB_ROUTER_MIN, INVB_ROUTER_MAX], ["laptops", INVB_LAPTOP_MIN, INVB_LAPTOP_MAX], ["fridges", INVB_FRIDGE_MIN, INVB_FRIDGE_MAX], ["coolers", INVB_COOLER_MIN, INVB_COOLER_MAX], ["pumps", INVB_PUMP_MIN, INVB_PUMP_MAX]];
  for (const [k, lo, hi] of counts) {
    if (!invbIsInt(input[k]) || input[k] < lo || input[k] > hi) return false;
  }
  if (!invbIsNum(input.otherWatts) || input.otherWatts < INVB_OTHER_WATTS_MIN || input.otherWatts > INVB_OTHER_WATTS_MAX) return false;
  if (!invbIsInt(input.batteryAh) || input.batteryAh < INVB_BATTERY_AH_MIN || input.batteryAh > INVB_BATTERY_AH_MAX) return false;
  if (input.batteryVolts !== 12 && input.batteryVolts !== 24 && input.batteryVolts !== 48) return false;
  if (input.batteryType !== "flat" && input.batteryType !== "tubular" && input.batteryType !== "lfp") return false;
  if (!invbIsNum(input.desiredHours) || input.desiredHours < INVB_DESIRED_HOURS_MIN || input.desiredHours > INVB_DESIRED_HOURS_MAX) return false;
  if (!invbIsNum(input.outageHours) || input.outageHours < INVB_OUTAGE_HOURS_MIN || input.outageHours > INVB_OUTAGE_HOURS_MAX) return false;
  if (!invbIsNum(input.tariff) || input.tariff < INVB_TARIFF_MIN || input.tariff > INVB_TARIFF_MAX) return false;
  if (!invbIsInt(input.existingVa) || input.existingVa < 0 || input.existingVa > INVB_EXISTING_VA_MAX) return false;
  if (input.existingVa !== 0 && input.existingVa < INVB_EXISTING_VA_MIN) return false;
  if (invbRunningW(input) <= 0) return false;
  return true;
}
export function invbCompute(input) {
  if (!invbValid(input)) return null;
  const rw = invbRunningW(input);
  const sw = invbSurgeW(input);
  const derate = INVB_DERATE[input.batteryType];
  const vaExact = rw / INVB_POWER_FACTOR;
  const va = invbNextSlab(vaExact);
  const surgeVaExact = sw / INVB_POWER_FACTOR;
  const surgeExceedsSlab = va !== null && surgeVaExact > va + 1e-9;
  const storedWh = input.batteryAh * input.batteryVolts;
  const usableWh = storedWh * derate;
  const backupHours = usableWh / rw;
  const reqAhExact = rw * input.desiredHours / (input.batteryVolts * derate);
  const reqAh = invbNextStdAh(reqAhExact);
  const loadKwh = rw * input.outageHours / 1000;
  const gridKwh = loadKwh / INVB_CHARGE_EFF[input.batteryType];
  const charging = gridKwh * input.tariff;
  const price = INVB_PRICE_PER_AH[input.batteryType] * input.batteryAh;
  const batteryPm = price / (INVB_LIFE_YEARS[input.batteryType] * 12);
  const maint = INVB_MAINT_PER_MONTH[input.batteryType];
  const monthlyTotal = charging + batteryPm + maint;
  let availableW = null;
  let existingVerdict = null;
  if (input.existingVa !== 0) {
    availableW = input.existingVa * INVB_POWER_FACTOR;
    if (availableW >= sw - 1e-9) existingVerdict = "fits";
    else if (availableW >= rw - 1e-9) existingVerdict = "fits-running-only";
    else existingVerdict = "undersized";
  }
  let verdict;
  if (va === null) verdict = "oversize";
  else if (backupHours >= input.desiredHours - 1e-9) verdict = "ok";
  else verdict = "short-backup";
  const r = {
    fans: input.fans, ledBulbs: input.ledBulbs,
    tubeLights: input.tubeLights, tvs: input.tvs,
    routers: input.routers, laptops: input.laptops,
    fridges: input.fridges, coolers: input.coolers,
    pumps: input.pumps, otherWatts: input.otherWatts,
    batteryAh: input.batteryAh, batteryVolts: input.batteryVolts,
    batteryType: input.batteryType,
    desiredHours: input.desiredHours,
    outageHours: input.outageHours, tariff: input.tariff,
    existingVa: input.existingVa,
    runningW: rw, surgeW: sw,
    requiredVaExact: invbR1(vaExact), requiredVa: va,
    surgeVaExact: invbR1(surgeVaExact),
    surgeExceedsSlab: surgeExceedsSlab,
    storedWh: storedWh, usableWh: invbR2(usableWh),
    backupHours: invbR2(backupHours),
    requiredAhExact: invbR1(reqAhExact), requiredAh: reqAh,
    monthlyLoadKwh: invbR2(loadKwh), monthlyGridKwh: invbR2(gridKwh),
    monthlyChargingCost: invbR2(charging),
    batteryPrice: price, batteryPerMonth: invbR2(batteryPm),
    maintenancePerMonth: maint,
    monthlyTotal: invbR2(monthlyTotal),
    yearlyTotal: invbR2(monthlyTotal * 12),
    availableW: (availableW === null ? null : invbR1(availableW)),
    existingVerdict: existingVerdict,
    verdict: verdict,
    notes: []
  };
  r.notes = invbNotes(r);
  return r;
}

