  const presetSelect = $("preset");
  const pill = $("roadtax-pill");
  const resultTagMain = $("result-tag-main");
  const resultTagSub = $("result-tag-sub");
  const resultHeading = $("result-heading");
  const output = $("answer");
  const fact1Val = $("roadtax-fact1");
  const fact2Val = $("roadtax-fact2");
  const fact3Val = $("roadtax-fact3");
  const fact4Val = $("roadtax-fact4");
  const fact5Val = $("roadtax-fact5");
  const fact6Val = $("roadtax-fact6");
  const fact7Val = $("roadtax-fact7");
  const fact1Label = $("roadtax-fact1-label");
  const fact2Label = $("roadtax-fact2-label");
  const fact3Label = $("roadtax-fact3-label");
  const fact4Label = $("roadtax-fact4-label");
  const fact5Label = $("roadtax-fact5-label");
  const fact6Label = $("roadtax-fact6-label");
