  const roadtaxInput = obj => ({ state: obj.state, vehicleType: obj.vehicleType, fuel: obj.fuel, price: obj.price, insurance: obj.insurance });

  const config = { key: p.key, title: p.title, presets: p.presets, defaultPreset: p.defaultPreset, sample: p.sample };
  const sample = roadtaxCompute(roadtaxInput(p.sample));

